		movew	%d0,(%a2)
		movew	%d0,(%a1)	/* start the Z80*/
		movew	%d7,(%a2)	/* reset the Z80*/

Init_ClearRAM:
		movel	%d0,-(%a6)		/* Clear normal RAM*/
		dbf	%d6,Init_ClearRAM
		movel	(%a5)+,(%a4)	/* set VDP display mode and increment*/
		movel	(%a5)+,(%a4)	/* set VDP to CRAM write*/
