Init_ClearCRAM:
		movel	%d0,(%a3)			/* Clear CRAM*/
		dbf	%d3,Init_ClearCRAM
		movel	(%a5)+,(%a4)
		moveq	#((0x50>>2)-1),%d4

Init_ClearVSRAM:
