		cmpl	(LockonHeader),%d0
		bnew	SonicAndKnucklesStartup

DetermineWhichGame:
		lea	(LockonSerialsText),%a1
		moveq	#3,%d1	/* 3 Sonic 2 headers, 1 Sonic 3 header*/

.compareSerials:
		lea	(LockonSerialNumber),%a0
		moveq	#0,%d3
		moveq	#0xD,%d2

.compareChars1:
		moveb	(%a1)+,%d0
		cmpb	(%a0)+,%d0
		beqs	.matchingChar1
		moveq	#1,%d3

.matchingChar1:
		dbf	%d2,.compareChars1
