/* =============== S U B R O U T I N E =======================================*/


Test_Checksum:
		btst	#6,(HW_Expansion_Control)
		beqs	1f
		cmpil	#0x534D264B,(Checksum_string)
		beqw	Test_Checksum_Done
1:
		moveal	#ErrorTrap,%a6
		movel	(ROMEndLoc),%d6
		moveq	#0,%d7
		addw	(%a6)+,%d7
		cmpl	%a6,%d6
		nop
		nop
		cmpw	(Checksum),%d7
		nop
		nop
		lea	(System_stack),%a6
		moveq	#0,%d7
		movew	#((0x1F0>>2)-1),%d6
1:
		movel	%d7,(%a6)+
		dbf	%d6,1b	/* clear RAM from 0xFFFE00 to 0xFFFFEF*/
		moveb	(HW_Version),%d6
		andib	#0xC0,%d6
		moveb	%d6,(Graphics_flags)
		movel	#0x534D264B,(Checksum_string)

Test_Checksum_Done:
		rts
/* End of function Test_Checksum*/

