SonicAndKnucklesStartup:
		bsrs	Test_Checksum
		movew	%d1,(SK_alone_flag)
		bsrw	DetectPAL
		bsrw	Init_VDP
		bsrw	SndDrvInit
		bsrw	Init_Controllers
		jsr	(SRAM_Load)
		moveb	#0,(Game_mode)

GameLoop:
		moveb	(Game_mode),%d0
		andiw	#0x7C,%d0
		moveal	GameModes(%pc,%d0:w),%a0
		jsr	(%a0)
		bras	GameLoop
