GameModes:	.long Sega_Screen		/*   0*/
		.long Title_Screen		/*   4*/
		.long Level			/*   8*/
		.long Level			/*  0xC*/
		.long JumpToSegaScreen		/* 0x10*/
		.long ContinueScreen		/* 0x14*/
		.long JumpToSegaScreen		/* 0x18*/
		.long LevelSelect_S2Options	/* 0x1C*/
