DetectPAL:
		lea	(VDP_control_port),%a5
		movew	#0x8174,(%a5)		/* VDP Command 0x8174 - Display on, VInt on, DMA on, PAL off*/
		moveq	#0,%d0

.waitForVBlankStart:
		movew	(%a5),%d1
		andiw	#8,%d1
		beqs	.waitForVBlankStart

.waitForVBlankEnd:
		movew	(%a5),%d1
		andiw	#8,%d1
		bnes	.waitForVBlankEnd	/* Wait for VBlank to run once*/

.waitForNextVBlank:
		addqw	#1,%d0
		movew	(%a5),%d1
		andiw	#8,%d1
		beqs	.waitForNextVBlank
		movew	%d0,(V_blank_cycles)	/* Count cycles between VBlanks (likely to detect PAL systems and/or for other timing mechanisms*/
		rts
/* End of function DetectPAL*/

