VInt:
		nop
		moveml	%d0-%a6,-(%sp)
		tstb	(V_int_routine)
		beqw	VInt_0_Main
1:
		movew	(VDP_control_port),%d0
		andiw	#8,%d0
		beqs	1b	/* wait until vertical blanking is taking place*/

		movel	#0x40000010,(VDP_control_port)
		movel	(V_scroll_value),(VDP_data_port)
		btst	#6,(Graphics_flags)
		beqs	1f	/* branch .if it's not a PAL system*/
		movew	#0x700,%d0
1:
		dbf	%d0,1b	/* otherwise, waste a bit of time here*/
1:
		moveb	(V_int_routine),%d0
		moveb	#0,(V_int_routine)
		movew	#1,(H_int_flag)		/* Allow H Interrupt code to run*/
		andiw	#0x3E,%d0
		movew	VInt_Table(%pc,%d0:w),%d0
		jsr	VInt_Table(%pc,%d0:w)

VInt_Done:
		addql	#1,(V_int_run_count)
		moveml	(%sp)+,%d0-%a6
		rte
/* --------------------------------------------------------------------------- */
VInt_Table:	.word VInt_0-VInt_Table
		.word VInt_2-VInt_Table
		.word VInt_4-VInt_Table
		.word VInt_6-VInt_Table
		.word VInt_8-VInt_Table
