VInt_0:
		addqw	#4,%sp

VInt_0_Main:
		addqw	#1,(Lag_frame_count)

		/* branch .if a level or demo is running*/
		cmpib	#0x88,(Game_mode)
		beqs	VInt_0_Level
		cmpib	#0x8C,(Game_mode)
		beqs	VInt_0_Level
		cmpib	#8,(Game_mode)
		beqs	VInt_0_Level
		cmpib	#0xC,(Game_mode)
		beqs	VInt_0_Level
		bras	VInt_Done	/* otherwise, return from V-int*/
