		beqs	1f	/* branch .if it isn't a PAL system*/
		movew	#0x700,%d0
1:
		dbf %d0,1b	/* otherwise, waste a bit of time here*/
1:
		movew	#1,(H_int_flag)
		movew	(H_int_counter_command),(VDP_control_port)
		stopZ80

		tstw	(Competition_mode)
		beqs	VInt_0_Done
		movel	#0x40000010,(VDP_control_port)
		movel	(V_scroll_value),(VDP_data_port)
		tstw	(Use_normal_sprite_table)
		beqs	1f
		dma_68kToVDP Sprite_table_buffer,0xF800,0x280,VRAM
		bras	VInt_0_Done
