/* --------------------------------------------------------------------------- */
/* Horizontal interrupt handler for Competition Mode*/
/* --------------------------------------------------------------------------- */

HInt:
		tstw	(H_int_flag)
		beqw	HInt_Done
		movew	#0,(H_int_flag)
		movel	%a5,-(%sp)
		movel	%d0,-(%sp)
1:
		movew	(VDP_control_port),%d0
		andiw	#4,%d0	/* is horizontal blanking occuring?*/
		beqs	1b	/* .if not, wait until it is*/

		movew	(VDP_reg_1_command),%d0
		andib	#0xBF,%d0
		movew	%d0,(VDP_control_port)	/* blank the display*/
		movel	#0x40000010,(VDP_control_port)
		movel	(V_scroll_value_P2_copy),(VDP_data_port)
		stopZ80
		tstw	(Use_normal_sprite_table)
		beqs	1f
		dma_68kToVDP Sprite_table_buffer_P2,0xF800,0x280,VRAM
		bras	2f
1:
		dma_68kToVDP Sprite_table_buffer_P2_2,0xF800,0x280,VRAM
1:
		startZ80
1:
		movew	(VDP_control_port),%d0
		andiw	#4,%d0	/* is a horizontal blank occuring?*/
		beqs	1b	/* .if not, wait*/
		movew	(VDP_reg_1_command),%d0
		orib	#0x40,%d0
		movew	%d0,(VDP_control_port)	/* enable display*/
		movel	(%sp)+,%d0
		moveal	(%sp)+,%a5

HInt_Done:
		rte

/* --------------------------------------------------------------------------- */
/* Used for water levels apart from Hydrocity, for uneven water surfaces*/
/* --------------------------------------------------------------------------- */

HInt3:
		tstw	(H_int_flag)
		beqs	HInt3_Done
		movew	#0,(H_int_flag)
		moveml	%d0-%d1/%a0-%a2,-(%sp)

		lea	(VDP_data_port),%a1
		movew	#0x8AFF,VDP_control_port-VDP_data_port(%a1)		/* Reset HInt timing*/
		stopZ80
		moveal	(Water_palette_data_addr),%a2
		moveq	#0xC,%d0
1:
		dbf %d0,1b	/* waste a few cycles here*/

		movew	(%a2)+,%d1
		moveb	(H_int_counter),%d0
		subib	#200,%d0	/* is H-int occuring below line 200?*/
		bcss	.transferColors0	/* .if it is, branch*/
		subb	%d0,%d1
		bcss	.skipTransfer0

.transferColors0:
		movew	(%a2)+,%d0
		lea	(Water_palette),%a0
		addaw	%d0,%a0
		addiw	#0xC000,%d0
		swap	%d0
		movel	%d0,VDP_control_port-VDP_data_port(%a1)	/* write to CRAM at appropriate address*/
		movel	(%a0)+,(%a1)	/* transfer two colors*/
		movew	(%a0)+,(%a1)	/* transfer the third color*/
		nop
		nop
		moveq	#0x24,%d0

.wasteSomeCycles0:
		dbf	%d0,.wasteSomeCycles0
		dbf	%d1,.transferColors0	/* repeat for number of colors*/

.skipTransfer0:
		startZ80
		moveml	(%sp)+,%d0-%d1/%a0-%a2
		tstb	(Do_Updates_in_H_int)
		bnes	HInt3_Do_Updates

HInt3_Done:
		rte
/* --------------------------------------------------------------------------- */

HInt3_Do_Updates:
		clrb	(Do_Updates_in_H_int)
		moveml	%d0-%a6,-(%sp)
		jsr	(Do_Updates)
		moveml	(%sp)+,%d0-%a6
		rte

