/* --------------------------------------------------------------------------- */

HInt2:
		move	#0x2700,%sr
		tstw	(H_int_flag)
		beqs	HInt2_Done
		movew	#0,(H_int_flag)
		moveml	%a0-%a1,-(%sp)

		lea	(VDP_data_port),%a1
		movew	#0x8ADF,VDP_control_port-VDP_data_port(%a1)
		lea	(Water_palette),%a0
		movel	#0xC0000000,VDP_control_port-VDP_data_port(%a1)
	.rept 32
		movel	(%a0)+,(%a1)
	.endr
