/* =============== S U B R O U T I N E =======================================*/


Init_Controllers:
		stopZ80
		moveq	#0x40,%d0
		moveb	%d0,(HW_Port_1_Control)
		moveb	%d0,(HW_Port_2_Control)
		moveb	%d0,(HW_Expansion_Control)
		startZ80
		rts
/* End of function Init_Controllers*/


/* =============== S U B R O U T I N E =======================================*/


Poll_Controllers:
		lea	(Ctrl_1),%a0
		lea	(HW_Port_1_Data),%a1
		bsrs	Poll_Controller	/* poll first controller*/
		addqw	#2,%a1	/* poll second controller*/
/* End of function Poll_Controllers*/


/* =============== S U B R O U T I N E =======================================*/


Poll_Controller:
		moveb	#0,(%a1)			/* Poll controller data port*/
		nop
		nop
		moveb	(%a1),%d0			/* Get controller port data (start/A)*/
		lslb	#2,%d0
		andib	#0xC0,%d0
		moveb	#0x40,(%a1)		/* Poll controller data port again*/
		nop
		nop
		moveb	(%a1),%d1			/* Get controller port data (B/C/Dpad)*/
		andib	#0x3F,%d1
		orb	%d1,%d0			/* Fuse together into one controller bit array*/
		notb	%d0
		moveb	(%a0),%d1			/* Get press button data*/
		eorb	%d0,%d1			/* Toggle off buttons that are being held*/
		moveb	%d0,(%a0)+		/* Put raw controller input (for held buttons) in F604/F606*/
		andb	%d0,%d1
		moveb	%d1,(%a0)+		/* Put pressed controller input in F605/F607*/
		rts
/* End of function Poll_Controller*/


/* =============== S U B R O U T I N E =======================================*/


Init_VDP:
		lea	(VDP_control_port),%a0
		lea	(VDP_data_port),%a1
		lea	(VDP_register_values),%a2
		moveq	#18,%d7

.setRegisters:
		movew	(%a2)+,(%a0)
		dbf	%d7,.setRegisters
		movew	(VDP_register_values+2),%d0	/* get command for register #1*/
		movew	%d0,(VDP_reg_1_command)	/* and store it in RAM (for easy display blanking/enabling)*/
		movew	#0x8ADF,(H_int_counter_command)
		moveq	#0,%d0
		movel	#0x40000010,(VDP_control_port)
		movew	%d0,(%a1)
		movew	%d0,(%a1)
		movel	#0xC0000000,(VDP_control_port)
		movew	#0x3F,%d7

.clearCRAM:
		movew	%d0,(%a1)
		dbf	%d7,.clearCRAM
		clrl	(V_scroll_value)
		clrl	(_unkF61A)
		movel	%d1,-(%sp)
		dmaFillVRAM 0,0x0000,0x10000	/* clear entire VRAM*/
		movel	(%sp)+,%d1
		rts
/* End of function Init_VDP*/

/* --------------------------------------------------------------------------- */
VDP_register_values:
		.word 0x8004 /* H-int disabled*/
		.word 0x8134 /* V-int enabled, display blanked, DMA enabled, 224 line display*/
		.word 0x8230 /* Scroll A PNT base 0xC000*/
		.word 0x8320 /* Window PNT base 0x8000*/
		.word 0x8407 /* Scroll B PNT base 0xE000*/
		.word 0x857C /* Sprite attribute table base 0xF800*/
		.word 0x8600
		.word 0x8700 /* Backdrop color is color 0 of the first palette line*/
		.word 0x8800
		.word 0x8900
		.word 0x8A00
		.word 0x8B00 /* Full-screen horizontal and vertical scrolling*/
		.word 0x8C81 /* 40 cell wide display, no interlace*/
		.word 0x8D3C /* Horizontal scroll table base 0xF000*/
		.word 0x8E00
		.word 0x8F02 /* Auto-ncrement is 2*/
		.word 0x9001 /* Scroll planes are 64x32 cells*/
		.word 0x9100
		.word 0x9200 /* Window disabled*/

/* =============== S U B R O U T I N E =======================================*/


Clear_DisplayData:
		stopZ80
		dmaFillVRAM 0,0x0000,0x40

		tstw	(Competition_mode)
		beqs	Clear_DisplayData_No2P
		dmaFillVRAM 0,0x8000,0x4000
		bras	Clear_DisplayData_Cont
/* --------------------------------------------------------------------------- */

Clear_DisplayData_No2P:
		dmaFillVRAM 0,0xC000,0x1000	/* clear plane A PNT*/
		dmaFillVRAM 0,0xE000,0x1000	/* clear plane B PNT*/

Clear_DisplayData_Cont:
		clrl	(V_scroll_value)
		clrl	(_unkF61A)
		clearRAM Sprite_table_buffer,0x284
		clearRAM H_scroll_buffer,0x404

		startZ80
		rts
/* End of function Clear_DisplayData*/


/* =============== S U B R O U T I N E =======================================*/


SndDrvInit:
		nop
		movew	#0x100,(Z80_bus_request)
		movew	#0x100,(Z80_reset)	/* release Z80 reset*/

		/* Load SMPS sound driver*/
		lea	(Z80_SoundDriver),%a0
		lea	(Z80_RAM),%a1
		bsrw	Kos_Decomp
		/* Load default variables*/
		moveq	#0,%d1
		lea	(Z80_RAM+z80_stack),%a1
		movew	#((zTracksStart-z80_stack/ 8)-1),%d0
1:
		movepl	%d1,0(%a1)
		movepl	%d1,1(%a1)
		addqw	#8,%a1
		dbf %d0,1b
		/* Detect PAL region consoles*/
		btst	#6,(Graphics_flags)
		beqs	1f
		moveb	#1,(Z80_RAM+zPalFlag)
1:
		movew	#0,(Z80_reset)	/* reset Z80*/
		nop
		nop
		nop
		nop
		movew	#0x100,(Z80_reset)	/* release reset*/
		startZ80
		rts
/* End of function SndDrvInit*/

/* --------------------------------------------------------------------------- */
/* Always replaces an index previous passed to this function*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Play_Sound:
		stopZ80
		moveb	%d0,(Z80_RAM+zMusicNumber)
		startZ80
		rts
/* End of function Play_Sound*/

/* --------------------------------------------------------------------------- */
/* plays a sound .if the source object is on-screen*/
/* unused/dead code, left over from Sonic 2*/

Play_Sound_Local:
		tstb	render_flags(%a0)
		bpls	Play_Sound_2_Done

/* --------------------------------------------------------------------------- */
/* Can handle up to two different indexes in one frame*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Play_Sound_2:
		stopZ80
		cmpb	(Z80_RAM+zSFXNumber0),%d0
		beqs	2f
		tstb	(Z80_RAM+zSFXNumber0)
		bnes	1f
		moveb	%d0,(Z80_RAM+zSFXNumber0)
		startZ80
		rts
1:
		moveb	%d0,(Z80_RAM+zSFXNumber1)
1:
		startZ80

Play_Sound_2_Done:
		rts
/* End of function Play_Sound_2*/


/* =============== S U B R O U T I N E =======================================*/


Change_Music_Tempo:
		stopZ80
		moveb	%d0,(Z80_RAM+zTempoSpeedup)
		startZ80
		rts
/* End of function Change_Music_Tempo*/


/* =============== S U B R O U T I N E =======================================*/


Pause_Game:
		nop
		tstw	(Ending_running_flag)
		beqs	Pause_Main
		rts
/* --------------------------------------------------------------------------- */

Pause_Main:
		tstb	(Life_count)
		beqw	Pause_Unpause
		tstw	(Game_paused)
		bnes	1f
		moveb	(Ctrl_1_pressed),%d0
		andib	#0x80,%d0	/* is Start pressed?*/
		beqw	Pause_NoPause	/* .if not, branch*/
1:
		movew	#1,(Game_paused)
		stopZ80
		moveb	#1,(Z80_RAM+zPauseFlag)	/* Pause the music*/
		startZ80

Pause_Loop:
		moveb	#0x10,(V_int_routine)
		bsrw	Wait_VSync
		tstb	(Slow_motion_flag)
		beqs	Pause_NoSlowMo
		btst	#6,(Ctrl_1_pressed)
		beqs	Pause_ChkFrameAdvance	/* branch .if A isn't pressed*/
		moveb	#4,(Game_mode)
		nop
		bras	Pause_ResumeMusic
/* --------------------------------------------------------------------------- */

Pause_ChkFrameAdvance:
		btst	#4,(Ctrl_1)
		bnes	Pause_FrameAdvance	/* branch .if B is held*/
		btst	#5,(Ctrl_1_pressed)
		bnes	Pause_FrameAdvance	/* branch .if C is pressed*/

Pause_NoSlowMo:
		cmpib	#0xE,(Current_zone)
		blos	Pause_ChkStart	/* .if the zone is below ALZ*/
		cmpib	#0x12,(Current_zone)
		bhis	Pause_ChkStart	/* .if the zone is above EMZ*/
		tstb	(Competition_mode_type)
		bpls	Pause_ChkStart
		btst	#4,(Ctrl_1_pressed)
		beqs	Pause_ChkStart
		moveb	#0xC0,(Game_mode)	/* If in time attack mode, go back to 2P menu .if B is pressed*/
		bras	Pause_ResumeMusic
/* --------------------------------------------------------------------------- */

Pause_ChkStart:
		moveb	(Ctrl_1_pressed),%d0
		andib	#0x80,%d0
		beqs	Pause_Loop

Pause_ResumeMusic:
		stopZ80
		moveb	#0x80,(Z80_RAM+zPauseFlag)	/* Unpause music*/
		startZ80

Pause_Unpause:
		movew	#0,(Game_paused)

Pause_NoPause:
		rts
/* --------------------------------------------------------------------------- */

Pause_FrameAdvance:
		movew	#1,(Game_paused)
		stopZ80
		moveb	#0x80,(Z80_RAM+zPauseFlag)	/* Unpause music*/
		startZ80
		rts	/* advance by a single frame*/
/* End of function Pause_Game*/

/* --------------------------------------------------------------------------- */
/* Copies a plane map to a plane PNT*/
/* Inputs:*/
/* %a1 = map address*/
/* %d0 = VDP command to write to the PNT*/
/* %d1 = number of cells in a row - 1*/
/* %d2 = number of cell rows - 1*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Plane_Map_To_VRAM:
		lea	(VDP_data_port),%a6
		movel	#0x800000,%d4	/* row increment value*/
1:
		movel	%d0,VDP_control_port-VDP_data_port(%a6)
		movew	%d1,%d3
1:
		movew	(%a1)+,(%a6)
		dbf %d3,1b	/* copy one row*/
		addl	%d4,%d0	/* move onto next row*/
		dbf %d2,1b	/* and copy it*/
		rts
/* End of function Plane_Map_To_VRAM*/

/* --------------------------------------------------------------------------- */
/* Copies a plane map to a plane PNT, used for a 128-cell wide plane*/
/* Inputs:*/
/* %a1 = map address*/
/* %d0 = VDP command to write to the PNT*/
/* %d1 = number of cells in a row - 1*/
/* %d2 = number of cell rows - 1*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Plane_Map_To_VRAM_2:
		lea	(VDP_data_port),%a6
		movel	#0x1000000,%d4	/* row increment value*/
1:
		movel	%d0,VDP_control_port-VDP_data_port(%a6)
		movew	%d1,%d3
1:
		movew	(%a1)+,(%a6)
		dbf %d3,1b	/* copy one row*/
		addl	%d4,%d0	/* move onto next row*/
		dbf %d2,1b	/* and copy it*/
		rts
/* End of function Plane_Map_To_VRAM_2*/

/* --------------------------------------------------------------------------- */
/* Adds art to the DMA queue*/
/* Inputs:*/
/* %d1 = source address*/
/* %d2 = destination VRAM address*/
/* %d3 = number of words to transfer*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Add_To_DMA_Queue:
		/* Detect .if transfer crosses 128KB boundary*/
		lsrl	#1,%d1
		movew	%d3,%d0
		negw	%d0
		subw	%d1,%d0
		bccs	.transfer
		/* Do first transfer*/
		moveml	%d1-%d3,-(%sp)
		addw	%d0,%d3		/* %d3 = words remaining in 128KB "bank"*/
		bsrs	.transfer
		moveml	(%sp)+,%d1-%d3
		/* Get second transfer's source, destination, and length*/
		moveq	#0,%d0
		subw	%d1,%d0
		subw	%d0,%d3
		addl	%d0,%d1
		addw	%d0,%d2
		addw	%d0,%d2
		/* Do second transfer*/
	.transfer:

		moveal	(DMA_queue_slot),%a1
		cmpaw	#DMA_queue_slot,%a1	/* is the queue full?*/
		beqs	Add_To_DMA_Queue_Done	/* .if it is, return*/

		movew	#0x9300,%d0
		moveb	%d3,%d0
		movew	%d0,(%a1)+	/* command to specify transfer length in words & 0x00FF*/

		movew	#0x9400,%d0
		lsrw	#8,%d3
		moveb	%d3,%d0
		movew	%d0,(%a1)+	/* command to specify transfer length in words & 0xFF00*/

		movew	#0x9500,%d0
		moveb	%d1,%d0
		movew	%d0,(%a1)+	/* command to specify transfer source & 0x0001FE*/

		movew	#0x9600,%d0
		lsrl	#8,%d1
		moveb	%d1,%d0
		movew	%d0,(%a1)+	/* command to specify transfer source & 0x01FE00*/

		movew	#0x9700,%d0
		lsrl	#8,%d1
		andib	#0x7F,%d1		/* this instruction safely allows source to be in RAM// S2's lacks this*/
		moveb	%d1,%d0
		movew	%d0,(%a1)+	/* command to specify transfer source & 0xFE0000*/

		andil	#0xFFFF,%d2
		lsll	#2,%d2
		lsrw	#2,%d2
		swap	%d2
		oril	#0x40000080,%d2
		movel	%d2,(%a1)+	/* command to specify transfer destination and begin DMA*/

		movel	%a1,(DMA_queue_slot)	/* set new free slot address*/
		cmpaw	#DMA_queue_slot,%a1	/* has the end of the queue been reached?*/
		beqs	Add_To_DMA_Queue_Done	/* .if it has, branch*/
		movew	#0,(%a1)	/* place stop token at the end of the queue*/

Add_To_DMA_Queue_Done:
		rts
/* End of function Add_To_DMA_Queue*/


/* =============== S U B R O U T I N E =======================================*/


Process_DMA_Queue:
		lea	(VDP_control_port),%a5
		lea	(DMA_queue),%a1

.loop0:
		movew	(%a1)+,%d0	/* has a stop token been encountered?*/
		beqs	.stop	/* .if it has, branch*/
		movew	%d0,(%a5)
		movew	(%a1)+,(%a5)
		movew	(%a1)+,(%a5)
		movew	(%a1)+,(%a5)
		movew	(%a1)+,(%a5)
		movew	(%a1)+,(%a5)
		movew	(%a1)+,(%a5)
		cmpaw	#DMA_queue_slot,%a1	/* has the end of the queue been reached?*/
		bnes	.loop0	/* .if not, loop*/

.stop:
		movew	#0,(DMA_queue)
		movel	#DMA_queue,(DMA_queue_slot)
		rts
/* End of function Process_DMA_Queue*/

/* --------------------------------------------------------------------------- */
/* Nemesis decompression subroutine, decompresses art directly to VRAM*/
/* Inputs:*/
/* %a0 = art address*/
/* a VDP command to write to the destination VRAM address must be issued*/
/* before calling this routine*/
/* See http://www.segaretro.org/Nemesis_compression for format description*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Nem_Decomp:
		moveml	%d0-%a1/%a3-%a5,-(%sp)
		lea	(Nem_pcD_WriteRowToVDP),%a3
		lea	(VDP_data_port),%a4	/* write all rows to the VDP data port*/
		bras	Nem_Decomp_Main
/* End of function Nem_Decomp*/

/* --------------------------------------------------------------------------- */
/* Nemesis decompression subroutine, decompresses art to RAM*/
/* Inputs:*/
/* %a0 = art address*/
/* %a4 = destination RAM address*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Nem_Decomp_To_RAM:
		moveml	%d0-%a1/%a3-%a5,-(%sp)
		lea	(Nem_pcD_WriteRowToRAM),%a3
/* End of function Nem_Decomp_To_RAM*/

/* --------------------------------------------------------------------------- */
/* Main Nemesis decompression subroutine*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Nem_Decomp_Main:
		lea	(Nem_code_table),%a1
		movew	(%a0)+,%d2	/* get number of patterns*/
		lslw	#1,%d2
		bccs	1f	/* branch .if the sign bit isn't set*/
		addaw	#Nem_pcD_WriteRowToVDP_XOR-Nem_pcD_WriteRowToVDP,%a3	/* otherwise the file uses XOR mode*/
1:
		lslw	#2,%d2	/* get number of 8-pixel rows in the uncompressed data*/
		moveaw	%d2,%a5	/* and store it in %a5 because there aren't any spare data registers*/
		moveq	#8,%d3	/* 8 pixels in a pattern row*/
		moveq	#0,%d2
		moveq	#0,%d4
		bsrw	Nem_Build_Code_Table
		moveb	(%a0)+,%d5	/* get first byte of compressed data*/
		aslw	#8,%d5	/* shift up by a byte*/
		moveb	(%a0)+,%d5	/* get second byte of compressed data*/
		movew	#0x10,%d6	/* set initial shift value*/
		bsrs	Nem_Process_Compressed_Data
		moveml	(%sp)+,%d0-%a1/%a3-%a5
		rts
/* End of function Nem_Decomp_Main*/

/* --------------------------------------------------------------------------- */
/* Part of the Nemesis decompressor, processes the actual compressed data*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/

/* pcD is used throughout this subroutine as an initialism for Process_Compressed_Data*/
Nem_Process_Compressed_Data:
		movew	%d6,%d7
		subqw	#8,%d7	/* get shift value*/
		movew	%d5,%d1
		lsrw	%d7,%d1	/* shift so that high bit of the code is in bit position 7*/
		cmpib	#0xFC,%d1	/* are the high 6 bits set?*/
		bhss	Nem_pcD_InlineData	/* .if they are, it signifies inline data*/
		andiw	#0xFF,%d1
		addw	%d1,%d1
		moveb	(%a1,%d1:w),%d0	/* get the length of the code in bits*/
		extw	%d0
		subw	%d0,%d6	/* subtract from shift value so that the next code is read next time around*/
		cmpiw	#9,%d6	/* does a new byte need to be read?*/
		bhss	1f	/* .if not, branch*/
		addqw	#8,%d6
		aslw	#8,%d5
		moveb	(%a0)+,%d5	/* read next byte*/
1:
		moveb	1(%a1,%d1:w),%d1
		movew	%d1,%d0
		andiw	#0xF,%d1	/* get palette index for pixel*/
		andiw	#0xF0,%d0

Nem_pcD_GetRepeatCount:
		lsrw	#4,%d0	/* get repeat count*/

Nem_pcD_WritePixel:
		lsll	#4,%d4	/* shift up by a nybble*/
		orb	%d1,%d4	/* write pixel*/
		subqw	#1,%d3	/* has an entire 8-pixel row been written?*/
		bnes	Nem_pcD_WritePixel_Loop	/* .if not, loop*/
		jmp	(%a3)	/* otherwise, write the row to its destination*/
/* --------------------------------------------------------------------------- */

Nem_pcD_NewRow:
		moveq	#0,%d4	/* reset row*/
		moveq	#8,%d3	/* reset nybble counter*/

Nem_pcD_WritePixel_Loop:
		dbf	%d0,Nem_pcD_WritePixel
		bras	Nem_Process_Compressed_Data
/* --------------------------------------------------------------------------- */

Nem_pcD_InlineData:
		subqw	#6,%d6	/* 6 bits needed to signal inline data*/
		cmpiw	#9,%d6
		bhss	1f
		addqw	#8,%d6
		aslw	#8,%d5
		moveb	(%a0)+,%d5
1:
		subqw	#7,%d6	/* and 7 bits needed for the inline data itself*/
		movew	%d5,%d1
		lsrw	%d6,%d1	/* shift so that low bit of the code is in bit position 0*/
		movew	%d1,%d0
		andiw	#0xF,%d1	/* get palette index for pixel*/
		andiw	#0x70,%d0	/* high nybble is repeat count for pixel*/
		cmpiw	#9,%d6
		bhss	Nem_pcD_GetRepeatCount
		addqw	#8,%d6
		aslw	#8,%d5
		moveb	(%a0)+,%d5
		bras	Nem_pcD_GetRepeatCount
/* --------------------------------------------------------------------------- */

Nem_pcD_WriteRowToVDP:
		movel	%d4,(%a4)	/* write 8-pixel row*/
		subqw	#1,%a5
		movew	%a5,%d4	/* have all the 8-pixel rows been written?*/
		bnes	Nem_pcD_NewRow	/* .if not, branch*/
		rts	/* otherwise the decompression is finished*/
/* --------------------------------------------------------------------------- */

Nem_pcD_WriteRowToVDP_XOR:
		eorl	%d4,%d2	/* XOR the previous row by the current row*/
		movel	%d2,(%a4)	/* and write the result*/
		subqw	#1,%a5
		movew	%a5,%d4
		bnes	Nem_pcD_NewRow
		rts
/* --------------------------------------------------------------------------- */

Nem_pcD_WriteRowToRAM:
		movel	%d4,(%a4)+
		subqw	#1,%a5
		movew	%a5,%d4
		bnes	Nem_pcD_NewRow
		rts
/* --------------------------------------------------------------------------- */

Nem_pcD_WriteRowToRAM_XOR:
		eorl	%d4,%d2
		movel	%d2,(%a4)+
		subqw	#1,%a5
		movew	%a5,%d4
		bnes	Nem_pcD_NewRow
		rts
/* End of function Nem_Process_Compressed_Data*/

/* --------------------------------------------------------------------------- */
/* Part of the Nemesis decompressor, builds the code table (in RAM)*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/

/* BCT is used throughout this subroutine as an initialism for Build_Code_Table*/
Nem_Build_Code_Table:
		moveb	(%a0)+,%d0	/* read first byte*/

Nem_BCT_ChkEnd:
		cmpib	#0xFF,%d0	/* has the end of the code table description been reached?*/
		bnes	Nem_BCT_NewPalIndex	/* .if not, branch*/
		rts	/* otherwise, this subroutine's work is done*/
/* --------------------------------------------------------------------------- */

Nem_BCT_NewPalIndex:
		movew	%d0,%d7

Nem_BCT_Loop:
		moveb	(%a0)+,%d0	/* read next byte*/
		cmpib	#0x80,%d0	/* sign bit being set signifies a new palette index*/
		bhss	Nem_BCT_ChkEnd	/* a bmi could have been used instead of a compare and bcc*/
		moveb	%d0,%d1
		andiw	#0xF,%d7	/* get palette index*/
		andiw	#0x70,%d1	/* get repeat count for palette index*/
		orw	%d1,%d7	/* combine the two*/
		andiw	#0xF,%d0	/* get the length of the code in bits*/
		moveb	%d0,%d1
		lslw	#8,%d1
		orw	%d1,%d7	/* combine with palette index and repeat count to form code table entry*/
		moveq	#8,%d1
		subw	%d0,%d1	/* is the code 8 bits long?*/
		bnes	Nem_BCT_ShortCode	/* .if not, a bit of extra processing is needed*/
		moveb	(%a0)+,%d0	/* get code*/
		addw	%d0,%d0	/* each code gets a word-sized entry in the table*/
		movew	%d7,(%a1,%d0:w)	/* store the entry for the code*/
		bras	Nem_BCT_Loop	/* repeat*/
/* --------------------------------------------------------------------------- */

/* the Nemesis decompressor uses prefix-free codes (no valid code is a prefix of a longer code)*/
/* e.g. .if 10 is a valid 2-bit code, 110 is a valid 3-bit code but 100 isn't*/
/* also, when the actual compressed data is processed the high bit of each code is in bit position 7*/
/* so the code needs to be bit-shifted appropriately over here before being used as a code table index*/
/* additionally, the code needs multiple entries in the table because no masking is done during compressed data processing*/
/* so .if 11000 is a valid code then all indices of the form 11000XXX need to have the same entry*/
Nem_BCT_ShortCode:
		moveb	(%a0)+,%d0	/* get code*/
		lslw	%d1,%d0	/* shift so that high bit is in bit position 7*/
		addw	%d0,%d0	/* get index into code table*/
		moveq	#1,%d5
		lslw	%d1,%d5
		subqw	#1,%d5	/* %d5 = 2^%d1 - 1*/

Nem_BCT_ShortCode_Loop:
		movew	%d7,(%a1,%d0:w)	/* store entry*/
		addqw	#2,%d0	/* increment index*/
		dbf	%d5,Nem_BCT_ShortCode_Loop	/* repeat for required number of entries*/
		bras	Nem_BCT_Loop
/* End of function Nem_Build_Code_Table*/

/* --------------------------------------------------------------------------- */
/* Adds pattern load requests to the Nemesis decompression queue*/
/* Input: %d0 = ID of the PLC to load*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Load_PLC:
		moveml	%a1-%a2,-(%sp)
		lea	(Offs_PLC),%a1
		addw	%d0,%d0
		movew	(%a1,%d0:w),%d0
		lea	(%a1,%d0:w),%a1
		lea	(Nem_decomp_queue),%a2

.findFreeSlot0:
		tstl	(%a2)	/* is the current slot in the queue free?*/
		beqs	.getPieceCount0	/* .if it is, branch*/
		addqw	#6,%a2	/* otherwise check the next slot*/
		bras	.findFreeSlot0
/* --------------------------------------------------------------------------- */

.getPieceCount0:
		movew	(%a1)+,%d0
		bmis	.done0

.queuePieces0:
		movel	(%a1)+,(%a2)+	/* store compressed data location*/
		movew	(%a1)+,(%a2)+	/* store destination in VRAM*/
		dbf	%d0,.queuePieces0

.done0:
		moveml	(%sp)+,%a1-%a2
		rts
/* End of function Load_PLC*/

/* --------------------------------------------------------------------------- */
/* Loads a raw PLC from ROM*/
/* Input: %a1 = address of the PLC*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Load_PLC_Raw:
		lea	(Nem_decomp_queue),%a2

.findFreeSlot1:
		tstl	(%a2)
		beqs	.getPieceCount1
		addqw	#6,%a2
		bras	.findFreeSlot1
/* --------------------------------------------------------------------------- */

.getPieceCount1:
		movew	(%a1)+,%d0
		bmis	.done1

.queuePieces1:
		movel	(%a1)+,(%a2)+
		movew	(%a1)+,(%a2)+
		dbf	%d0,.queuePieces1

.done1:
		rts
/* End of function Load_PLC_Raw*/

/* --------------------------------------------------------------------------- */
/* Adds pattern load requests to the Nemesis decompression queue*/
/* Differs from Load_PLC in that it clears the queue before loading*/
/* Input: %d0 = ID of the PLC to load*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Load_PLC_2:
		moveml	%a1-%a2,-(%sp)		/* This differs from Load_PLC in that it overrides any PLCs already in the queue*/
		lea	(Offs_PLC),%a1
		addw	%d0,%d0
		movew	(%a1,%d0:w),%d0
		lea	(%a1,%d0:w),%a1
		bsrs	Clear_Nem_Queue
		lea	(Nem_decomp_queue),%a2
		movew	(%a1)+,%d0
		bmis	.done2

.queuePieces2:
		movel	(%a1)+,(%a2)+
		movew	(%a1)+,(%a2)+
		dbf	%d0,.queuePieces2

.done2:
		moveml	(%sp)+,%a1-%a2
		rts
/* End of function Load_PLC_2*/

/* --------------------------------------------------------------------------- */
/* Clears the Nemesis decompression queue and its associated variables*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Clear_Nem_Queue:
		lea	(Nem_decomp_queue),%a2
		moveq	#((0x80>>2)-1),%d0	/* clear till the end of Nem_decomp_vars*/
1:
		clrl	(%a2)+
		dbf %d0,1b
		rts
/* End of function Clear_Nem_Queue*/

/* --------------------------------------------------------------------------- */
/* Initializes Nemesis decompression queue processing*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Process_Nem_Queue_Init:
		tstl	(Nem_decomp_queue)
		beqs	2f	/* return .if the queue is empty*/
		tstw	(Nem_patterns_left)
		bnes	2f	/* return .if processing of a previous piece is still going on*/
		moveal	(Nem_decomp_queue),%a0
		lea	(Nem_pcD_WriteRowToVDP),%a3
		nop
		lea	(Nem_code_table),%a1
		movew	(%a0)+,%d2
