		aslw	#8,%d5
		moveb	(%a0)+,%d5
		moveq	#0x10,%d6
		moveq	#0,%d0
		movel	%a0,(Nem_decomp_queue)
		movel	%a3,(Nem_decomp_vars)
		movel	%d0,(Nem_repeat_count)
		movel	%d0,(Nem_palette_index)
		movel	%d0,(Nem_previous_row)
		movel	%d5,(Nem_data_word)
		movel	%d6,(Nem_shift_value)
		movew	%d2,(Nem_patterns_left)
1:
		rts
/* End of function Process_Nem_Queue_Init*/

/* --------------------------------------------------------------------------- */
/* Processes the first piece on the Nemesis decompression queue*/
/* Decompresses 6 patterns per frame*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Process_Nem_Queue:
		tstw	(Nem_patterns_left)
		beqw	Process_Nem_Queue_Done
		movew	#6,(Nem_frame_patterns_left)	/* decompress 6 patterns per frame*/
		moveq	#0,%d0
		movew	(Nem_decomp_destination),%d0
		addiw	#6*0x20,(Nem_decomp_destination)	/* increment by 6 patterns' worth of data*/
		bras	Process_Nem_Queue_Main
/* End of function Process_Nem_Queue*/

/* --------------------------------------------------------------------------- */
/* Processes the first piece on the Nemesis decompression queue*/
/* Decompresses 3 patterns per frame*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Process_Nem_Queue_2:
		tstw	(Nem_patterns_left)
		beqs	Process_Nem_Queue_Done
		movew	#3,(Nem_frame_patterns_left)	/* decompress 3 patterns per frame*/
		moveq	#0,%d0
		movew	(Nem_decomp_destination),%d0
		addiw	#3*0x20,(Nem_decomp_destination)	/* increment by 3 patterns' worth of data*/
/* End of function Process_Nem_Queue_2*/

/* --------------------------------------------------------------------------- */
/* Main Nemesis decompression queue processor*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Process_Nem_Queue_Main:
		lea	(VDP_control_port),%a4
		lsll	#2,%d0
		lsrw	#2,%d0
		oriw	#0x4000,%d0
		swap	%d0	/* %d0 = VDP command word to write to VRAM destination*/
		movel	%d0,(%a4)
		subqw	#VDP_control_port-VDP_data_port,%a4	/* %a4 = VDP_data_port*/
		moveal	(Nem_decomp_queue),%a0
		moveal	(Nem_decomp_vars),%a3
		movel	(Nem_repeat_count),%d0
		movel	(Nem_palette_index),%d1
		movel	(Nem_previous_row),%d2
		movel	(Nem_data_word),%d5
		movel	(Nem_shift_value),%d6
		lea	(Nem_code_table),%a1

Process_Nem_Queue_Loop:
		moveaw	#8,%a5	/* decompress all 8 rows in a pattern*/
		bsrw	Nem_pcD_NewRow
		subqw	#1,(Nem_patterns_left)	/* have all the patterns been decompressed?*/
		beqs	Process_Nem_Queue_ShiftUp	/* .if yes, shift all other queue entries up*/
		subqw	#1,(Nem_frame_patterns_left)	/* has the current frame's worth of patterns been decompressed?*/
		bnes	Process_Nem_Queue_Loop	/* .if not, loop*/
		movel	%a0,(Nem_decomp_queue)
		movel	%a3,(Nem_decomp_vars)
		movel	%d0,(Nem_repeat_count)
		movel	%d1,(Nem_palette_index)
		movel	%d2,(Nem_previous_row)
		movel	%d5,(Nem_data_word)
		movel	%d6,(Nem_shift_value)

Process_Nem_Queue_Done:
		rts
/* --------------------------------------------------------------------------- */

/* this routine is idiotic because:*/
/* a) it doesn't copy the VRAM location for the last entry in the queue*/
/* b) it doesn't actually mark the last slot in the queue as clear*/
/* so basically don't store an entry in the last slot unless you want the game to screw up to high heaven*/
Process_Nem_Queue_ShiftUp:
		lea	(Nem_decomp_queue),%a0
		moveq	#0x15,%d0
1:
		movel	6(%a0),(%a0)+
		dbf %d0,1b
		rts
/* End of function Process_Nem_Queue_Main*/

/* --------------------------------------------------------------------------- */
		lea	(Offs_PLC),%a1
		addw	%d0,%d0
		movew	(%a1,%d0:w),%d0
		lea	(%a1,%d0:w),%a1

/* --------------------------------------------------------------------------- */
/* Loads a raw PLC from the ROM and decompresses it immediately*/
/* Input: %a1 = the address of the PLC*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Load_PLC_Immediate:
		movew	(%a1)+,%d1

.decompPieces:
		moveal	(%a1)+,%a0	/* get source address*/
		moveq	#0,%d0
		movew	(%a1)+,%d0	/* get destination VRAM address*/
		lsll	#2,%d0
		lsrw	#2,%d0
		oriw	#0x4000,%d0
		swap	%d0	/* %d0 = VDP command to write to destination*/
		movel	%d0,(VDP_control_port)
		bsrw	Nem_Decomp
		dbf	%d1,.decompPieces
		rts
/* End of function Load_PLC_Immediate*/

/* --------------------------------------------------------------------------- */
/* Enigma decompression subroutine*/
/* Inputs:*/
/* %a0 = compressed data location*/
/* %a1 = destination (in RAM)*/
/* %d0 = starting art tile*/
/* See http://www.segaretro.org/Enigma_compression for format description*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Eni_Decomp:
		moveml	%d0-%d7/%a1-%a5,-(%sp)
		moveaw	%d0,%a3	/* store starting art tile*/
		moveb	(%a0)+,%d0
		extw	%d0
		moveaw	%d0,%a5	/* store number of bits in inline copy value*/
		moveb	(%a0)+,%d4
		lslb	#3,%d4	/* store pcCVH flags bitfield*/
		moveaw	(%a0)+,%a2
		addaw	%a3,%a2	/* store incremental copy word*/
		moveaw	(%a0)+,%a4
		addaw	%a3,%a4	/* store literal copy word*/
		moveb	(%a0)+,%d5
		aslw	#8,%d5
		moveb	(%a0)+,%d5	/* get first word in format list*/
		moveq	#0x10,%d6		/* initial shift value*/

Eni_Decomp_Loop:
		moveq	#7,%d0	/* assume a format list entry is 7 bits*/
		movew	%d6,%d7
		subw	%d0,%d7
		movew	%d5,%d1
		lsrw	%d7,%d1
		andiw	#0x7F,%d1	/* get format list entry*/
		movew	%d1,%d2	/* and copy it*/
		cmpiw	#0x40,%d1	/* is the high bit of the entry set?*/
		bhss	1f
		moveq	#6,%d0	/* .if it isn't, the entry is actually 6 bits*/
		lsrw	#1,%d2
1:
		bsrw	Eni_Decomp_FetchByte
		andiw	#0xF,%d2	/* get repeat count*/
		lsrw	#4,%d1
		addw	%d1,%d1
		jmp	Eni_Decomp_Index(%pc,%d1:w)
/* --------------------------------------------------------------------------- */

Eni_Decomp_00:
		movew	%a2,(%a1)+	/* copy incremental copy word*/
		addqw	#1,%a2	/* increment it*/
		dbf	%d2,Eni_Decomp_00	/* repeat*/
		bras	Eni_Decomp_Loop
/* --------------------------------------------------------------------------- */

Eni_Decomp_01:
		movew	%a4,(%a1)+	/* copy literal copy word*/
		dbf	%d2,Eni_Decomp_01	/* repeat*/
		bras	Eni_Decomp_Loop
/* --------------------------------------------------------------------------- */

Eni_Decomp_100:
