1:
		movew	%d1,(%a1)+	/* copy inline value*/
		dbf %d2,1b	/* repeat*/
		bras	Eni_Decomp_Loop
/* --------------------------------------------------------------------------- */

Eni_Decomp_101:
		bsrw	Eni_Decomp_FetchInlineValue
1:
		movew	%d1,(%a1)+	/* copy inline value*/
		addqw	#1,%d1	/* increment*/
		dbf %d2,1b	/* repeat*/
		bras	Eni_Decomp_Loop
/* --------------------------------------------------------------------------- */

Eni_Decomp_110:
