		dbf %d2,1b	/* and repeat*/
		bras	Eni_Decomp_Loop
/* --------------------------------------------------------------------------- */

Eni_Decomp_Index:
		bras	Eni_Decomp_00
/* --------------------------------------------------------------------------- */
		bras	Eni_Decomp_00
/* --------------------------------------------------------------------------- */
		bras	Eni_Decomp_01
/* --------------------------------------------------------------------------- */
		bras	Eni_Decomp_01
/* --------------------------------------------------------------------------- */
		bras	Eni_Decomp_100
/* --------------------------------------------------------------------------- */
		bras	Eni_Decomp_101
/* --------------------------------------------------------------------------- */
		bras	Eni_Decomp_110
/* --------------------------------------------------------------------------- */
		bras	Eni_Decomp_111
/* --------------------------------------------------------------------------- */

Eni_Decomp_Done:
