1:
		movew	%a0,%d0
		lsrw	#1,%d0
		bccs	1f
		addqw	#1,%a0	/* make sure it's an even address*/
1:
		moveml	(%sp)+,%d0-%d7/%a1-%a5
		rts
/* End of function Eni_Decomp*/

/* --------------------------------------------------------------------------- */
/* Part of the Enigma decompressor*/
/* Fetches an inline copy value and stores it in %d1*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Eni_Decomp_FetchInlineValue:
		movew	%a3,%d3	/* copy starting art tile*/
		moveb	%d4,%d1	/* copy pcCVH bitfield*/
		addb	%d1,%d1	/* is the priority bit set?*/
		bccs	1f	/* .if not, branch*/
		subqw	#1,%d6
		btst	%d6,%d5	/* is the priority bit set in the inline render flags?*/
		beqs	1f	/* .if not, branch*/
		oriw	#0x8000,%d3	/* otherwise set priority bit in art tile*/
1:
		addb	%d1,%d1	/* is the high palette line bit set?*/
		bccs	1f	/* .if not, branch*/
		subqw	#1,%d6
		btst	%d6,%d5
		beqs	1f
		addiw	#0x4000,%d3
1:
		addb	%d1,%d1	/* is the low palette line bit set?*/
		bccs	1f	/* .if not, branch*/
		subqw	#1,%d6
		btst	%d6,%d5
		beqs	1f
		addiw	#0x2000,%d3
1:
		addb	%d1,%d1	/* is the vertical flip flag set?*/
		bccs	1f	/* .if not, branch*/
		subqw	#1,%d6
		btst	%d6,%d5
		beqs	1f
		oriw	#0x1000,%d3
1:
		addb	%d1,%d1	/* is the horizontal flip flag set?*/
		bccs	1f	/* .if not, branch*/
		subqw	#1,%d6
		btst	%d6,%d5
		beqs	1f
		oriw	#0x800,%d3
1:
		movew	%d5,%d1
		movew	%d6,%d7
		subw	%a5,%d7	/* subtract length in bits of inline copy value*/
		bccs	.enoughBits	/* branch .if a new word doesn't need to be read*/
		movew	%d7,%d6
		addiw	#0x10,%d6
		negw	%d7	/* calculate bit deficit*/
		lslw	%d7,%d1	/* and make space for that many bits*/
		moveb	(%a0),%d5	/* get next byte*/
		rolb	%d7,%d5	/* and rotate the required bits into the lowest positions*/
		addw	%d7,%d7
		andw	Eni_Decomp_Masks-2(%pc,%d7:w),%d5
		addw	%d5,%d1	/* combine upper bits with lower bits*/

.maskValue:
		movew	%a5,%d0	/* get length in bits of inline copy value*/
		addw	%d0,%d0
		andw	Eni_Decomp_Masks-2(%pc,%d0:w),%d1	/* mask value appropriately*/
		addw	%d3,%d1	/* add starting art tile*/
		moveb	(%a0)+,%d5
		lslw	#8,%d5
		moveb	(%a0)+,%d5	/* get next word*/
		rts
/* --------------------------------------------------------------------------- */

.enoughBits:
		beqs	.justEnough	/* .if the word has been exactly exhausted, branch*/
		lsrw	%d7,%d1	/* get inline copy value*/
		movew	%a5,%d0
		addw	%d0,%d0
		andw	Eni_Decomp_Masks-2(%pc,%d0:w),%d1	/* and mask it appropriately*/
		addw	%d3,%d1	/* add starting art tile*/
		movew	%a5,%d0
		bras	Eni_Decomp_FetchByte
/* --------------------------------------------------------------------------- */

.justEnough:
		moveq	#0x10,%d6	/* reset shift value*/
		bras	.maskValue
/* End of function Eni_Decomp_FetchInlineValue*/

/* --------------------------------------------------------------------------- */
Eni_Decomp_Masks:
		.word     1
		.word     3
		.word     7
		.word    0xF
		.word   0x1F
		.word   0x3F
		.word   0x7F
		.word   0xFF
		.word  0x1FF
		.word  0x3FF
		.word  0x7FF
		.word  0xFFF
		.word 0x1FFF
		.word 0x3FFF
		.word 0x7FFF
		.word 0xFFFF

/* --------------------------------------------------------------------------- */
/* Part of the Enigma decompressor, fetches the next byte .if needed*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Eni_Decomp_FetchByte:
		subw	%d0,%d6	/* subtract length of current entry from shift value so that next entry is read next time around*/
		cmpiw	#9,%d6	/* does a new byte need to be read?*/
		bhss	1f	/* .if not, branch*/
		addqw	#8,%d6
		aslw	#8,%d5
		moveb	(%a0)+,%d5
1:
		rts
/* End of function Eni_Decomp_FetchByte*/

/* --------------------------------------------------------------------------- */
/* Kosinski decompression subroutine*/
/* Inputs:*/
/* %a0 = compressed data location*/
/* %a1 = destination*/
/* See http://www.segaretro.org/Kosinski_compression for format description*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Kos_Decomp:
		subql	#2,%sp	/* make space for two bytes on the stack*/
		moveb	(%a0)+,1(%sp)
		moveb	(%a0)+,(%sp)
		movew	(%sp),%d5	/* copy first description field*/
		moveq	#0xF,%d4	/* 16 bits in a byte*/

Kos_Decomp_Loop:
		lsrw	#1,%d5	/* bit which is shifted out goes into C flag*/
		move	%sr,%d6
		dbf	%d4,Kos_Decomp_ChkBit
		moveb	(%a0)+,1(%sp)
		moveb	(%a0)+,(%sp)
		movew	(%sp),%d5	/* get next description field .if needed*/
		moveq	#0xF,%d4	/* reset bit counter*/

Kos_Decomp_ChkBit:
		move	%d6,ccr	/* was the bit set?*/
		bccs	Kos_Decomp_Match	/* .if not, branch (C flag clear means bit was clear)*/
		moveb	(%a0)+,(%a1)+	/* otherwise, copy byte as-is*/
		bras	Kos_Decomp_Loop
/* --------------------------------------------------------------------------- */

Kos_Decomp_Match:
		moveq	#0,%d3
		lsrw	#1,%d5	/* get next bit*/
		move	%sr,%d6
		dbf	%d4,Kos_Decomp_ChkBit2
		moveb	(%a0)+,1(%sp)
		moveb	(%a0)+,(%sp)
		movew	(%sp),%d5
		moveq	#0xF,%d4

Kos_Decomp_ChkBit2:
		move	%d6,ccr	/* was the bit set?*/
		bcss	Kos_Decomp_FullMatch	/* .if it was, branch*/
		lsrw	#1,%d5	/* bit which is shifted out goes into X flag*/
		dbf	%d4,1f 
		moveb	(%a0)+,1(%sp)
		moveb	(%a0)+,(%sp)
		movew	(%sp),%d5
		moveq	#0xF,%d4
1:
		roxlw	#1,%d3	/* get high repeat count bit (shift X flag in)*/
		lsrw	#1,%d5
		dbf	%d4,1f 
		moveb	(%a0)+,1(%sp)
		moveb	(%a0)+,(%sp)
		movew	(%sp),%d5
		moveq	#0xF,%d4
1:
		roxlw	#1,%d3	/* get low repeat count bit*/
		addqw	#1,%d3	/* increment repeat count*/
		moveq	#-1,%d2
		moveb	(%a0)+,%d2	/* calculate offset*/
		bras	Kos_Decomp_MatchLoop
/* --------------------------------------------------------------------------- */

Kos_Decomp_FullMatch:
		moveb	(%a0)+,%d0	/* get first byte*/
		moveb	(%a0)+,%d1	/* get second byte*/
		moveq	#-1,%d2
		moveb	%d1,%d2
		lslw	#5,%d2
		moveb	%d0,%d2	/* calculate offset*/
		andiw	#7,%d1	/* does a third byte need to be read?*/
		beqs	Kos_Decomp_FullMatch2	/* .if it does, branch*/
		moveb	%d1,%d3	/* copy repeat count*/
		addqw	#1,%d3	/* and increment it*/

Kos_Decomp_MatchLoop:
		moveb	(%a1,%d2:w),%d0
		moveb	%d0,(%a1)+	/* copy appropriate byte*/
		dbf	%d3,Kos_Decomp_MatchLoop	/* and repeat the copying*/
		bras	Kos_Decomp_Loop
/* --------------------------------------------------------------------------- */

Kos_Decomp_FullMatch2:
		moveb	(%a0)+,%d1
		beqs	Kos_Decomp_Done	/* 0 indicates end of compressed data*/
		cmpib	#1,%d1
		beqw	Kos_Decomp_Loop	/* 1 indicates a new description needs to be read*/
		moveb	%d1,%d3	/* otherwise, copy repeat count*/
		bras	Kos_Decomp_MatchLoop
/* --------------------------------------------------------------------------- */

Kos_Decomp_Done:
		addql	#2,%sp	/* restore stack pointer to original state*/
		rts
/* End of function Kos_Decomp*/

/* --------------------------------------------------------------------------- */
/* Adds a Kosinski Moduled archive to the module queue*/
/* Inputs:*/
/* %a1 = address of the archive*/
/* %d2 = destination in VRAM*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Queue_Kos_Module:
		lea	(Kos_module_queue),%a2
		tstl	(%a2)	/* is the first slot free?*/
		beqs	Process_Kos_Module_Queue_Init	/* .if it is, branch*/
		addqw	#6,%a2	/* otherwise, check next slot*/

.findFreeSlot:
		tstl	(%a2)
		beqs	.freeSlotFound
		addqw	#6,%a2
		bras	.findFreeSlot
/* --------------------------------------------------------------------------- */

.freeSlotFound:
		movel	%a1,(%a2)+	/* store source address*/
		movew	%d2,(%a2)+	/* store destination VRAM address*/
		rts
/* End of function Queue_Kos_Module*/

/* --------------------------------------------------------------------------- */
/* Initializes processing of the first module on the queue*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Process_Kos_Module_Queue_Init:
		movew	(%a1)+,%d3	/* get uncompressed size*/
		cmpiw	#0xA000,%d3
		bnes	1f
		movew	#0x8000,%d3	/* 0xA000 means 0x8000 for some reason*/
1:
		lsrw	#1,%d3
		movew	%d3,%d0
		rolw	#5,%d0
		andiw	#0x1F,%d0	/* get number of complete modules*/
		moveb	%d0,(Kos_modules_left)
		andil	#0x7FF,%d3	/* get size of last module in words*/
		bnes	1f	/* branch .if it's non-zero*/
		subqb	#1,(Kos_modules_left)	/* otherwise decrement the number of modules*/
		movel	#0x800,%d3	/* and take the size of the last module to be 0x800 words*/
1:
		movew	%d3,(Kos_last_module_size)
		movew	%d2,(Kos_module_destination)
		movel	%a1,(Kos_module_queue)
		addqb	#1,(Kos_modules_left)	/* store total number of modules*/
		rts
/* End of function Process_Kos_Module_Queue_Init*/

/* --------------------------------------------------------------------------- */
/* Processes the first module on the queue*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Process_Kos_Module_Queue:
		tstb	(Kos_modules_left)
		bnes	.modulesLeft

.done3:
		rts
/* --------------------------------------------------------------------------- */

.modulesLeft:
		bmis	.decompressionStarted
		cmpiw	#4,(Kos_decomp_queue_count)
		bhss	.done3	/* branch .if the Kosinski decompression queue is full*/
		moveal	(Kos_module_queue),%a1
		lea	(Kos_decomp_buffer),%a2
		bsrw	Queue_Kos	/* add current module to decompression queue*/
		orib	#0x80,(Kos_modules_left)	/* and set bit to signify decompression in progress*/
		rts
/* --------------------------------------------------------------------------- */

.decompressionStarted:
		tstw	(Kos_decomp_queue_count)
		bnes	.done3	/* branch .if the decompression isn't complete*/

		/* otherwise, DMA the decompressed data to VRAM*/
		andib	#0x7F,(Kos_modules_left)
		movel	#0x800,%d3
		subqb	#1,(Kos_modules_left)
		bnes	1f	/* branch .if it isn't the last module*/
		movew	(Kos_last_module_size),%d3
1:
		movew	(Kos_module_destination),%d2
		movew	%d2,%d0
		addw	%d3,%d0
		addw	%d3,%d0
		movew	%d0,(Kos_module_destination)	/* set new destination*/
		movel	(Kos_module_queue),%d0
		movel	(Kos_decomp_queue),%d1
		subl	%d1,%d0
		andil	#0xF,%d0
		addl	%d0,%d1	/* round to the nearest 0x10 boundary*/
		movel	%d1,(Kos_module_queue)	/* and set new source*/
		movel	#Kos_decomp_buffer,%d1
		andil	#0xFFFFFF,%d1
		jsr	(Add_To_DMA_Queue)
		tstb	(Kos_modules_left)
		bnes	1f	/* return .if this wasn't the last module*/
		lea	(Kos_module_queue),%a0
		lea	(Kos_module_queue+6),%a1
		movel	(%a1)+,(%a0)+	/* otherwise, shift all entries up*/
		movew	(%a1)+,(%a0)+
		movel	(%a1)+,(%a0)+
		movew	(%a1)+,(%a0)+
		movel	(%a1)+,(%a0)+
		movew	(%a1)+,(%a0)+
		movel	#0,(%a0)+	/* and mark the last slot as free*/
		movew	#0,(%a0)+
		movel	(Kos_module_queue),%d0
		beqs	1f	/* return .if the queue is now empty*/
		moveal	%d0,%a1
		movew	(Kos_module_destination),%d2
		jmp	(Process_Kos_Module_Queue_Init)
1:
		rts
/* End of function Process_Kos_Module_Queue*/

/* --------------------------------------------------------------------------- */
/* Adds Kosinski-compressed data to the decompression queue*/
/* Inputs:*/
/* %a1 = compressed data address*/
/* %a2 = decompression destination in RAM*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Queue_Kos:
		movew	(Kos_decomp_queue_count),%d0
		lslw	#3,%d0
		lea	(Kos_decomp_queue),%a3
		movel	%a1,(%a3,%d0:w)	/* store source*/
		movel	%a2,4(%a3,%d0:w)	/* store destination*/
		addqw	#1,(Kos_decomp_queue_count)
		rts
/* End of function Queue_Kos*/

/* --------------------------------------------------------------------------- */
/* Checks .if V-int occured in the middle of Kosinski queue processing*/
/* and stores the location from which processing is to resume .if it did*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Set_Kos_Bookmark:
		tstw	(Kos_decomp_queue_count)
		bpls	1f	/* branch .if a decompression wasn't in progress*/
		movel	0x42(%sp),%d0	/* check address V-int is supposed to rte to*/
		cmpil	#Process_Kos_Queue_Main,%d0
		blos	1f
		cmpil	#Process_Kos_Queue_Done,%d0
		bhss	1f
		movel	0x42(%sp),(Kos_decomp_bookmark)
		movel	#Backup_Kos_Registers,0x42(%sp)	/* force V-int to rte here instead .if needed*/
1:
		rts
/* End of function Set_Kos_Bookmark*/

/* --------------------------------------------------------------------------- */
/* Processes the first entry in the Kosinski decompression queue*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Process_Kos_Queue:
		tstw	(Kos_decomp_queue_count)
		beqw	Process_Kos_Queue_Done
		bmiw	Restore_Kos_Bookmark	/* branch .if a decompression was interrupted by V-int*/

Process_Kos_Queue_Main:
		oriw	#0x8000,(Kos_decomp_queue_count)	/* set sign bit to signify decompression in progress*/
		moveal	(Kos_decomp_queue),%a0
		moveal	(Kos_decomp_destination),%a1

		/* what follows is identical to the normal Kosinski decompressor except for using Kos_description_field instead of the stack*/
		lea	(Kos_description_field),%a2
		moveb	(%a0)+,1(%a2)
		moveb	(%a0)+,(%a2)
		movew	(%a2),%d5
		moveq	#0xF,%d4

Process_Kos_Queue_Loop:
		lsrw	#1,%d5
		move	%sr,%d6
		dbf	%d4,Process_Kos_Queue_ChkBit
		moveb	(%a0)+,1(%a2)
		moveb	(%a0)+,(%a2)
		movew	(%a2),%d5
		moveq	#0xF,%d4

Process_Kos_Queue_ChkBit:
		move	%d6,ccr
		bccs	Process_Kos_Queue_RLE
		moveb	(%a0)+,(%a1)+
		bras	Process_Kos_Queue_Loop
/* --------------------------------------------------------------------------- */

Process_Kos_Queue_RLE:
		moveq	#0,%d3
		lsrw	#1,%d5
		move	%sr,%d6
		dbf	%d4,Process_Kos_Queue_ChkBit2
		moveb	(%a0)+,1(%a2)
		moveb	(%a0)+,(%a2)
		movew	(%a2),%d5
		moveq	#0xF,%d4

Process_Kos_Queue_ChkBit2:
		move	%d6,ccr
		bcss	Process_Kos_Queue_SeparateRLE
		lsrw	#1,%d5
		dbf	%d4,1f 
		moveb	(%a0)+,1(%a2)
		moveb	(%a0)+,(%a2)
		movew	(%a2),%d5
		moveq	#0xF,%d4
1:
		roxlw	#1,%d3
		lsrw	#1,%d5
		dbf	%d4,1f 
		moveb	(%a0)+,1(%a2)
		moveb	(%a0)+,(%a2)
		movew	(%a2),%d5
		moveq	#0xF,%d4
1:
		roxlw	#1,%d3
		addqw	#1,%d3
		moveq	#-1,%d2
		moveb	(%a0)+,%d2
		bras	Process_Kos_Queue_RLELoop
/* --------------------------------------------------------------------------- */

Process_Kos_Queue_SeparateRLE:
		moveb	(%a0)+,%d0
		moveb	(%a0)+,%d1
		moveq	#-1,%d2
		moveb	%d1,%d2
		lslw	#5,%d2
		moveb	%d0,%d2
		andiw	#7,%d1
		beqs	Process_Kos_Queue_SeparateRLE2
		moveb	%d1,%d3
		addqw	#1,%d3

Process_Kos_Queue_RLELoop:
		moveb	(%a1,%d2:w),%d0
		moveb	%d0,(%a1)+
		dbf	%d3,Process_Kos_Queue_RLELoop
		bras	Process_Kos_Queue_Loop
/* --------------------------------------------------------------------------- */

Process_Kos_Queue_SeparateRLE2:
		moveb	(%a0)+,%d1
		beqs	Process_Kos_Queue_EndReached
		cmpib	#1,%d1
		beqw	Process_Kos_Queue_Loop
		moveb	%d1,%d3
		bras	Process_Kos_Queue_RLELoop
/* --------------------------------------------------------------------------- */

Process_Kos_Queue_EndReached:
		movel	%a0,(Kos_decomp_queue)
		movel	%a1,(Kos_decomp_destination)
		andiw	#0x7FFF,(Kos_decomp_queue_count)	/* clear decompression in progress bit*/
		subqw	#1,(Kos_decomp_queue_count)
		beqs	Process_Kos_Queue_Done	/* branch .if there aren't any entries remaining in the queue*/
		lea	(Kos_decomp_queue),%a0
		lea	(Kos_decomp_queue+8),%a1	/* otherwise, shift all entries up*/
		movel	(%a1)+,(%a0)+
		movel	(%a1)+,(%a0)+
		movel	(%a1)+,(%a0)+
		movel	(%a1)+,(%a0)+
		movel	(%a1)+,(%a0)+
		movel	(%a1)+,(%a0)+

Process_Kos_Queue_Done:
		rts
/* --------------------------------------------------------------------------- */

Restore_Kos_Bookmark:
		moveml	(Kos_decomp_stored_registers),%d0-%d6/%a0-%a2
		movel	(Kos_decomp_bookmark),-(%sp)
		movew	(Kos_decomp_stored_SR),-(%sp)
		rte
/* --------------------------------------------------------------------------- */

Backup_Kos_Registers:
		move	%sr,(Kos_decomp_stored_SR)
		moveml	%d0-%d6/%a0-%a2,(Kos_decomp_stored_registers)
		rts
/* End of function Process_Kos_Queue*/

/* --------------------------------------------------------------------------- */
/* Called at the end of each frame to perform vertical synchronization*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Wait_VSync:
		move	#0x2300,%sr
1:
		tstb	(V_int_routine)
		bnes	1b	/* wait until V-int's run*/
		rts
/* End of function Wait_VSync*/

/* --------------------------------------------------------------------------- */
/* Generates a pseudo-random number in %d0*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Random_Number:
		movel	(RNG_seed),%d1
		tstw	%d1
		bnes	1f
		movel	#0x2A6D365B,%d1	/* reset seed .if needed*/
1:
		movel	%d1,%d0
		asll	#2,%d1
		addl	%d0,%d1
		asll	#3,%d1
		addl	%d0,%d1
		movew	%d1,%d0
		swap	%d1
		addw	%d1,%d0
		movew	%d0,%d1
		swap	%d1
		movel	%d1,(RNG_seed)
		rts
/* End of function Random_Number*/

/* --------------------------------------------------------------------------- */
/* Calculates the sine and cosine of the angle in %d0 (360 degrees = 256)*/
/* Returns the sine in %d0 and the cosine in %d1 (both multiplied by 0x100)*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


GetSineCosine:
		andiw	#0xFF,%d0
		addw	%d0,%d0
		addiw	#0x40*2,%d0	/* 0x40 = 90 degrees, sin(x+90) = cos(x)*/
		movew	SineTable(%pc,%d0:w),%d1
		subiw	#0x40*2,%d0
		movew	SineTable(%pc,%d0:w),%d0
		rts
/* End of function GetSineCosine*/

/* --------------------------------------------------------------------------- */
SineTable:	.incbin "Levels/Misc/sine.bin" /* test*/
	.align 2

/* --------------------------------------------------------------------------- */
/* Calculates the arctangent of y/x and returns it in %d0 (360 degrees = 256)*/
/* Inputs: %d1 = input x, %d2 = input y*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


GetArcTan:
		moveml	%d3-%d4,-(%sp)
		moveq	#0,%d3
		moveq	#0,%d4
		movew	%d1,%d3
		movew	%d2,%d4
		orw	%d3,%d4
		beqs	GetArcTan_Zero	/* special case when both x and y are zero*/
		movew	%d2,%d4
		tstw	%d3
		bpls	1f
		negw	%d3
1:
		tstw	%d4
		bpls	1f
		negw	%d4
1:
		cmpw	%d3,%d4
		bhss	1f	/* .if +y+ >= +x+*/
		lsll	#8,%d4
		divuw	%d3,%d4
		moveq	#0,%d0
		moveb	ArcTanTable(%pc,%d4:w),%d0
		bras	2f
1:
		lsll	#8,%d3
		divuw	%d4,%d3
		moveq	#0x40,%d0
		subb	ArcTanTable(%pc,%d3:w),%d0	/* arctan(y/x) = 90 - arctan(x/y)*/
1:
		tstw	%d1
		bpls	1f
		negw	%d0
		addiw	#0x80,%d0	/* place angle in appropriate quadrant*/
1:
		tstw	%d2
		bpls	1f
		negw	%d0
		addiw	#0x100,%d0	/* place angle in appropriate quadrant*/
1:
		moveml	(%sp)+,%d3-%d4
		rts
/* --------------------------------------------------------------------------- */

GetArcTan_Zero:
		movew	#0x40,%d0	/* angle = 90 degrees*/
		moveml	(%sp)+,%d3-%d4
		rts
/* End of function GetArcTan*/

/* --------------------------------------------------------------------------- */
ArcTanTable:	.incbin "Levels/Misc/arctan.bin"
	.align 2
