/* =============== S U B R O U T I N E =======================================*/


SuperHyper_PalCycle:
		moveb	(Super_palette_status),%d0	/* 0 = off + 1 = fading + -1 = fading done*/
		beqw	locret_37EC			/* return, .if player isn't super*/
		bmiw	SuperHyper_PalCycle_Normal	/* branch, .if fade-in is done*/
		subqb	#1,%d0
		bnew	SuperHyper_PalCycle_Revert	/* branch for values greater than 1*/

		/* fade from Sonic's to Super Sonic's palette*/
		/* run frame timer*/
		subqb	#1,(Palette_timer)
		bplw	locret_37EC
		moveb	#1,(Palette_timer)

		/* Tails and Knuckles only*/
		/* Only Sonic has a fade-in// Tails and Knuckles just *pop* into their normal Super/Hyper palette cycle*/
		cmpiw	#2,(Player_mode)
		blos	SuperHyper_PalCycle_FadeIn
		moveb	#-1,(Super_palette_status)	/* -1 = fading done*/
		movew	#0,(Palette_frame)			/* Used by Knuckles and Tails' Super Flickies*/
		moveb	#0,(Palette_frame_Tails)		/* Used by Tails*/
		moveb	#0,(Player_1+object_control)		/* restore Player's movement*/
		rts
/* --------------------------------------------------------------------------- */

SuperHyper_PalCycle_FadeIn:
		/* increment palette frame and update Sonic's palette*/
		lea	(PalCycle_SuperSonic),%a0
		movew	(Palette_frame),%d0
		addqw	#6,(Palette_frame)			/* 1 palette entry = 1 word, Sonic uses 3 shades of blue*/
		cmpiw	#0x24,(Palette_frame)			/* has palette cycle reached the 6th frame?*/
		blos	SuperHyper_PalCycle_SonicApply		/* .if not, branch*/
		moveb	#-1,(Super_palette_status)	/* mark fade-in as done*/
		moveb	#0,(Player_1+object_control)		/* restore Sonic's movement*/

SuperHyper_PalCycle_SonicApply:
		lea	(Normal_palette+0x4),%a1
		movel	(%a0,%d0:w),(%a1)+	/* Write first two palette entries*/
		movew	4(%a0,%d0:w),(%a1) /* Write last palette entry*/

		tstb	(Water_flag)
		beqs	locret_37EC
		lea	(PalCycle_SuperSonicUnderwaterAIZICZ),%a0	/* Load underwater fade-in palette*/
		tstb	(Current_zone)				/* Is Sonic in Angel Island Zone?*/
		beqs	SuperHyper_PalCycle_ApplyUnderwater		/* If so, branch*/
		cmpib	#5,(Current_zone)				/* Is Sonic in IceCap Zone?*/
		beqs	SuperHyper_PalCycle_ApplyUnderwater		/* If so, branch*/
		lea	(PalCycle_SuperSonicUnderwaterHCZCNZLBZ),%a0	/* Load alternate underwater fade-in palette*/

SuperHyper_PalCycle_ApplyUnderwater:
		lea	(Water_palette+0x4),%a1
		movel	(%a0,%d0:w),(%a1)+	/* Write first two palette entries*/
		movew	4(%a0,%d0:w),(%a1) /* Write last palette entry*/

locret_37EC:
		rts
/* --------------------------------------------------------------------------- */

SuperHyper_PalCycle_Revert:	/* runs the fade in transition backwards*/
		cmpiw	#2,(Player_mode)	/* If Tails or Knuckles, branch, making this code Sonic-specific*/
		bhss	SuperHyper_PalCycle_RevertNotSonic

		/* run frame timer*/
		subqb	#1,(Palette_timer)
		bpls	locret_37EC
		moveb	#3,(Palette_timer)

		/* decrement palette frame and update Sonic's palette*/
		lea	(PalCycle_SuperSonic),%a0
		movew	(Palette_frame),%d0
		subqw	#6,(Palette_frame)	/* previous frame*/
		bhss	loc_381E		/* branch, .if it isn't the first frame*/
		/* Bug: this only clears the high byte of Palette_frame, causing subsequent*/
		/* fade-ins to pull color values from PalCycle_SuperTails*/
		movew	#0,(Palette_frame)
		moveb	#0,(Super_palette_status)	/* 0 = off*/

loc_381E:
		bras	SuperHyper_PalCycle_SonicApply
/* --------------------------------------------------------------------------- */

SuperHyper_PalCycle_RevertNotSonic:
		moveq	#0,%d0
		movew	%d0,(Palette_frame)
		moveb	%d0,(Super_palette_status)	/* 0 = off*/
		moveb	%d0,(Palette_frame_Tails)
		cmpiw	#3,(Player_mode)			/* If Knuckles, branch, making this code Tails-specific*/
		bhss	SuperHyper_PalCycle_RevertKnuckles

		lea	(PalCycle_SuperTails),%a0		/* Used here because the first set of colours is Tails' normal palette*/
		bsrw	SuperHyper_PalCycle_ApplyTails
		lea	(PalCycle_SuperSonic),%a0		/* Why does Tails manipulate Sonic's palette? For his Super-form's Super Flickies*/
		braw	SuperHyper_PalCycle_Apply
/* --------------------------------------------------------------------------- */

SuperHyper_PalCycle_RevertKnuckles:
		lea	(PalCycle_SuperHyperKnucklesRevert),%a0
		braw	SuperHyper_PalCycle_Apply
/* --------------------------------------------------------------------------- */

SuperHyper_PalCycle_Normal:
		cmpiw	#2,(Player_mode)		/* If Tails...*/
		beqw	SuperHyper_PalCycle_NormalTails
		cmpiw	#3,(Player_mode)		/* ...or Knuckles, branch, making this code Sonic-specific*/
		bhsw	SuperHyper_PalCycle_NormalKnuckles
		tstb	(Super_Sonic_Knux_flag)	/* If Hyper Sonic, branch*/
		bmis	SuperHyper_PalCycle_HyperSonic

SuperHyper_PalCycle_SuperSonic:	/* Tails' code falls back here so the Super Flickies' palette can update*/
		/* run frame timer*/
		subqb	#1,(Palette_timer)
		bplw	locret_37EC
		moveb	#6,(Palette_timer)

		/* increment palette frame and update Sonic's palette*/
		lea	(PalCycle_SuperSonic),%a0
		movew	(Palette_frame),%d0
		addqw	#6,(Palette_frame)	/* next frame*/
		cmpiw	#0x36,(Palette_frame)	/* is it the last frame?*/
		blos	loc_3898		/* .if not, branch*/
		movew	#0x24,(Palette_frame)	/* reset frame counter (Super Sonic's normal palette cycle starts at 0x24. Everything before that is for the palette fade)*/

loc_3898:
		braw	SuperHyper_PalCycle_SonicApply
/* --------------------------------------------------------------------------- */

SuperHyper_PalCycle_HyperSonic:
		/* run frame timer*/
		subqb	#1,(Palette_timer)
		bplw	locret_37EC
		moveb	#4,(Palette_timer)

		/* increment palette frame and update Sonic's palette*/
		lea	(PalCycle_HyperSonic),%a0
		movew	(Palette_frame),%d0
		addqw	#6,(Palette_frame)			/* next frame*/
		cmpiw	#0x48,(Palette_frame)			/* is it the last frame?*/
		blos	SuperHyper_PalCycle_HyperSonicApply	/* .if not, branch*/
		movew	#0,(Palette_frame)			/* reset frame counter*/

SuperHyper_PalCycle_HyperSonicApply:
		/* Redundant. SuperHyper_PalCycle_Apply does the exact same thing*/
		/* and other areas of code do branch to it instead of duplicating the code as seen here*/
		lea	(Normal_palette+0x4),%a1
		movel	(%a0,%d0:w),(%a1)+	/* Write first two palette entries*/
		movew	4(%a0,%d0:w),(%a1) /* Write last palette entry*/
		tstb	(Water_flag)
		beqw	locret_37EC
		lea	(Water_palette+0x4),%a1
		movel	(%a0,%d0:w),(%a1)+	/* Write first two palette entries*/
		movew	4(%a0,%d0:w),(%a1) /* Write last palette entry*/
		rts
/* --------------------------------------------------------------------------- */

SuperHyper_PalCycle_NormalTails:
		/* run frame timer*/
		subqb	#1,(Palette_timer_Tails)
		bplw	SuperHyper_PalCycle_SuperSonic
		moveb	#0xB,(Palette_timer_Tails)

		/* increment palette frame and update Tails' palette*/
		lea	(PalCycle_SuperTails),%a0
		moveq	#0,%d0
		moveb	(Palette_frame_Tails),%d0
		addqb	#6,(Palette_frame_Tails)	/* next frame*/
		cmpib	#0x24,(Palette_frame_Tails)	/* is it the last frame?*/
		blos	SuperHyper_PalCycle_ApplyTails	/* .if not, branch*/
		moveb	#0,(Palette_frame_Tails)	/* reset frame counter*/
		/* go straight to SuperHyper_PalCycle_ApplyTails...*/
/* End of function SuperHyper_PalCycle*/


/* =============== S U B R O U T I N E =======================================*/


SuperHyper_PalCycle_ApplyTails:
		/* Tails gets his own because of the unique location of his palette entries*/
		lea	(Normal_palette+0x10),%a1
		movel	(%a0,%d0:w),(%a1)+		/* Write first two palette entries*/
		movew	4(%a0,%d0:w),2(%a1)	/* Write last palette entry*/
		tstb	(Water_flag)
		beqw	SuperHyper_PalCycle_SuperSonic
		lea	(Water_palette+0x10),%a1
		movel	(%a0,%d0:w),(%a1)+		/* Write first two palette entries*/
		movew	4(%a0,%d0:w),2(%a1)	/* Write last palette entry*/
		braw	SuperHyper_PalCycle_SuperSonic
/* End of function SuperHyper_PalCycle_ApplyTails*/

/* --------------------------------------------------------------------------- */

SuperHyper_PalCycle_NormalKnuckles:
		/* run frame timer*/
		subqb	#1,(Palette_timer)
		bplw	locret_37EC
		moveb	#2,(Palette_timer)

		/* increment palette frame and update Knuckles' palette*/
		lea	(PalCycle_SuperHyperKnuckles),%a0
		movew	(Palette_frame),%d0
		addqw	#6,(Palette_frame)			/* next frame*/
		cmpiw	#0x3C,(Palette_frame)			/* is it the last frame?*/
		blos	SuperHyper_PalCycle_Apply		/* .if not, branch*/
		movew	#0,(Palette_frame)			/* reset frame counter*/
		moveb	#0xE,(Palette_timer)

SuperHyper_PalCycle_Apply:
		lea	(Normal_palette+0x4),%a1
		movel	(%a0,%d0:w),(%a1)+	/* Write first two palette entries*/
		movew	4(%a0,%d0:w),(%a1)	/* Write last palette entry*/
		tstb	(Water_flag)
		beqw	locret_37EC
		lea	(Water_palette+0x4),%a1
		movel	(%a0,%d0:w),(%a1)+	/* Write first two palette entries*/
		movew	4(%a0,%d0:w),(%a1)	/* Write last palette entry*/
		rts
