		andil	#0xFFFFFF,%d0
		moveal	%d0,%a0
		lea	(RAM_start),%a1
		bsrw	Kos_Decomp
		movew	%a1,%d3
		lsrw	#1,%d3

loc_4446:
		movel	#RAM_start,%d1
		movew	#0,%d2
		tstb	(Title_anim_buffer)		/* FFFFBC toggles on and off so that each animation frame could alternate locations for a sort of makeshift double-buffering*/
		beqs	loc_445A
		movew	#0x6000,%d2

loc_445A:
		andil	#0xFFFFFF,%d1
		jsr	(Add_To_DMA_Queue)

loc_4466:
		moveal	(%a2)+,%a0			/* Palette data address*/
		lea	(Target_palette),%a1
		moveq	#0xF,%d0

loc_446E:
		movel	(%a0)+,(%a1)+
		dbf	%d0,loc_446E
		tstb	(Title_anim_buffer)
		bnes	loc_44B8
		lea	(RAM_start+0x8000),%a1			/* Buffer 1*/
		moveal	(%a2)+,%a0				/* Enigma Mappings*/
		movew	#0,%d0
		bsrw	Eni_Decomp
		cmpiw	#7,%d7
		bhss	loc_449A
		tstb	(Graphics_flags)
		bmis	loc_449A
		moveq	#0,%d0
		movel	%d0,(RAM_start+0x83AC)

loc_449A:
		move	#0x2700,%sr
		lea	(Level_layout_header),%a1
		movel	#0x40000003,%d0			/* to 0xC000 in VRAM, Nametable A*/
		moveq	#0x27,%d1
		moveq	#0x1B,%d2
		jsr	(Plane_Map_To_VRAM)
		move	#0x2300,%sr
		rts
/* --------------------------------------------------------------------------- */

loc_44B8:
		lea	(RAM_start+0x8000),%a1			/* Buffer 2*/
		moveal	(%a2)+,%a0				/* Enigma Mappings*/
		movew	#0x300,%d0
		cmpiw	#7,%d7
		bhss	loc_44CC
		movew	#0,%d0

loc_44CC:
		bsrw	Eni_Decomp
		cmpiw	#7,%d7
		bhss	loc_44E2
		tstb	(Graphics_flags)
		bmis	loc_44E2
		moveq	#0,%d0
		movel	%d0,(RAM_start+0x83AC)

loc_44E2:
		move	#0x2700,%sr
		lea	(Level_layout_header),%a1
		movel	#0x60000003,%d0			/* to 0xE000 in VRAM Nametable B*/
		moveq	#0x27,%d1
		moveq	#0x1B,%d2
		jsr	(Plane_Map_To_VRAM)
		move	#0x2300,%sr
		rts
/* End of function TitleSonic_LoadFrame*/

