SK_Alone_Title_Screen:
		lea	(ArtKos_SKTitleScreenBG),%a0
		lea	(RAM_start),%a1
		bsrw	Kos_Decomp
		lea	(ArtKos_BigSEGA),%a0
		bsrw	Kos_Decomp
		lea	(ArtKos_SKTitle_SonicFall),%a0		/* Get title BG, Sega logo, and Sonic falling frame going*/
		bsrw	Kos_Decomp
		movew	%a1,%d3
		lsrw	#1,%d3
		movel	#0xFF0000,%d1
		movew	#0,%d2
		movew	#0xE20,%d3
		jsr	(Add_To_DMA_Queue)		/* DMA the BG first to 0x0 in VRAM*/
		movel	#0xFF1C40,%d1
		movew	#0x9380,%d2
		movew	#0x1640,%d3
		jsr	(Add_To_DMA_Queue)		/* Then DMA the logo and Sonic falling frame to 0x9380 in VRAM*/
		lea	(RAM_start+0x4E00),%a1
		lea	(ArtKos_SKTitle_DeathEgg),%a0
		bsrw	Kos_Decomp
		movel	#0xFF4E00,%d1
		movew	#0xD000,%d2
		movew	#0x720,%d3
		jsr	(Add_To_DMA_Queue)		/* DMA the Death Egg title screen art to 0xD000 in VRAM*/
		lea	(RAM_start+0x5D00),%a1
		lea	(ArtKos_SKTitle_Mountain),%a0
		bsrw	Kos_Decomp
		movel	#0xFF5D00,%d1
		movew	#0xF400,%d2
		movew	#0x150,%d3
		jsr	(Add_To_DMA_Queue)		/* DMA the little section of mountain that is drawn above the Death Egg*/
		lea	(Chunk_table+0x7400),%a1
		lea	(MapEni_SKTitle_Sega),%a0	/* Get the SEGA logo mappings*/
		movew	#0x849C,%d0
		bsrw	Eni_Decomp
		tstb	(Graphics_flags)
		bmis	loc_5122
		movew	#0xA49C,%d0
		movew	%d0,(Chunk_table+0x775C)
		movew	%d0,(Chunk_table+0x775E)
		movew	%d0,(Chunk_table+0x7760)
		movew	%d0,(Chunk_table+0x77AC)
		movew	%d0,(Chunk_table+0x77AE)
		movew	%d0,(Chunk_table+0x77B0)		/* Remove the TM from the Sega logo .if on a Japan console*/

loc_5122:
		lea	(Chunk_table+0x7400),%a1
		movel	#0x40000003,%d0
		moveq	#0x27,%d1
		moveq	#0x1B,%d2
		jsr	(Plane_Map_To_VRAM)		/* Copy Sega logo mappings to VRAM location 0xC000*/
		lea	(Chunk_table+0x7CC0),%a1
		lea	(MapEni_SKTitle_Background),%a0
		movew	#0,%d0
		bsrw	Eni_Decomp
		lea	(Chunk_table+0x7CC0),%a1
		movel	#0x60000003,%d0
		bsrw	RAM_Map_Data_To_VDP		/* Copy SK Title Background mappings to VRAM location 0xE000*/
		lea	(RAM_start+0x8580),%a1
		lea	(MapEni_SKTitle_Frame1),%a0
		movew	#0x80E2,%d0
		bsrw	Eni_Decomp
		lea	(RAM_start+0x8E40),%a1
		lea	(MapEni_SKTitle_Frame2),%a0
		movew	#0x80E2,%d0
		bsrw	Eni_Decomp
		lea	(RAM_start+0x9700),%a1
		lea	(MapEni_SKTitle_Frame3),%a0
		movew	#0x80E2,%d0
		bsrw	Eni_Decomp
		lea	(RAM_start+0x9FC0),%a1
		lea	(MapEni_SKTitle_Frame4),%a0
		movew	#0x80E2,%d0
		bsrw	Eni_Decomp
		lea	(ArtKos_SKTitle_SonKnuxHand),%a1
		lea	(RAM_start+0x4800),%a2
