loc_5666:
		cmpiw	#3,(Events_routine_fg)
		bnes	loc_56AA		/* Wait until the proper phase of the title sequence*/
		oriw	#0x8000,0xA(%a0)	/* Modify the priority of the sprite*/
		cmpiw	#0xE0,(Camera_Y_pos)
		bhss	loc_56B0		/* If the foreground Y is past 0xE0, branch*/
		addqw	#8,(Camera_Y_pos)	/* Otherwise scroll foreground by 8 pixels*/
		cmpiw	#0xC8,(Camera_Y_pos)
		bnes	loc_5698
		lea	(ArtKosM_SonicLand),%a1 /* Once foreground has hit C8 Y*/
		movew	#0x8C40,%d2
		jsr	(Queue_Kos_Module)	/* Queue the landing frames into VRAM*/

loc_5698:
		lea	(RAM_start+0x8580),%a1		/* First frame data (Knuckles only)*/
		movel	#0x40000003,%d0
		movew	(Camera_Y_pos),%d1
		bsrw	Copy_Map_Line_To_VRAM	/* Since the nametable is only 32 tiles high, we can't copy the first foreground mapping frame for Sonic and Knuckles wholesale.*/
										/* We set up each line of mappings data every time the screen scrolls down further*/

loc_56AA:
		jmp	(Draw_Sprite)
/* --------------------------------------------------------------------------- */

loc_56B0:
		bnes	loc_56D4
		move	#0x2700,%sr		/* Only do this when screen scrolling has his E0 Y*/
		lea	(RAM_start+0x8E40),%a1	/* Second frame data (Sonic lands)*/
		movel	#0x40000003,%d0
		moveq	#0x27,%d1
		moveq	#0x1B,%d2
		jsr	(Plane_Map_To_VRAM)	/* Copy the frame data*/
		move	#0x2300,%sr
		moveb	#6,0x24(%a0)			/* Set up an internal timer*/

loc_56D4:
		cmpiw	#0x100,(Camera_Y_pos)
		beqs	loc_56E2			/* When screen has hit 0x100 Y, branch*/
		addqw	#8,(Camera_Y_pos)
		rts
