Obj_SKTitle_SonicFallLand:
		subqb	#1,0x24(%a0)
		bpls	locret_5716
		move	#0x2700,%sr
		lea	(Block_table+0x700),%a1	/* Get third mapping frame (Sonic starting to stand)*/
		movel	#0x40000003,%d0
		moveq	#0x27,%d1
		moveq	#0x1B,%d2
		jsr	(Plane_Map_To_VRAM)
		move	#0x2300,%sr
