		addw	0x46(%a0),%d0
		negw	%d3
		negw	%d2
		addw	0x44(%a0),%d3
		addw	0x46(%a0),%d2
		moveq	#0,%d4
		moveq	#2,%d5
		moveb	0x26(%a0),%d6
		subib	#0xA0,%d6
		bpls	loc_5BF6
