SKTitle_ScreenShake:
		tstw	(Screen_shake_flag)
		beqs	locret_5D92			/* If timer has run out, don't do anything*/
		subqw	#1,(Screen_shake_flag)
		bnes	loc_5D72
		addqw	#1,(Events_routine_fg)	/* Increment title routine counter when this is done*/

loc_5D72:
		movew	(V_int_run_count+2),%d0
		andiw	#0x3F,%d0				/* Get frame counter then AND it for offset*/
		lea	(SKTitle_ShakeOffsets),%a1
		lea	(%a1,%d0:w),%a1
		moveq	#0,%d0
		moveb	(%a1)+,%d0
		movew	%d0,(Camera_Y_pos_P2_copy)
		moveb	(%a1)+,%d0
		movew	%d0,(Camera_X_pos_P2_copy)

locret_5D92:
		rts
/* End of function SKTitle_ScreenShake*/


