SKTitle_DeformBG:
		movew	(Camera_Y_pos),(V_scroll_value)
		movew	(Camera_Y_pos_P2),(V_scroll_value_BG)		/* Move BG position values to their proper spots*/
		moveq	#0,%d2
		tstw	(Screen_shake_flag)
		beqs	loc_5DB8
		movew	(Camera_Y_pos_P2_copy),%d0
		addw	%d0,(V_scroll_value)
		addw	%d0,(V_scroll_value_BG)				/* Shake the screen by the proper offsets .if screen shaking is on*/
		movew	(Camera_X_pos_P2_copy),%d2				/* Move shake X amount to %d2*/

loc_5DB8:
		lea	(H_scroll_buffer),%a1
		movew	(Events_routine_fg),%d0
		bnes	loc_5DE0

loc_5DC2:
		movew	#0xDF,%d1							/* If routine counter is zero*/
		movew	(Camera_X_pos),%d0
		addw	%d2,%d0
		negw	%d0
		swap	%d0
		movew	(Camera_X_pos_P2),%d0
		addw	%d2,%d0
		negw	%d0

loc_5DD8:
		movel	%d0,(%a1)+						/* Do normal deformation, nothing special*/
		dbf	%d1,loc_5DD8
		rts
/* --------------------------------------------------------------------------- */

loc_5DE0:
		subqw	#1,%d0
		bnes	loc_5E0E
		addw	(Camera_X_pos_P2),%d2				/* If routine counter is 1*/
		negw	%d2
		movew	#0x6F,%d3

loc_5DEE:
		jsr	(Random_Number)
		andiw	#7,%d0
		movew	%d0,(%a1)+		/* Shake the scanlines of the foreground (SEGA logo) by random amounts to simulate static*/
		movew	%d2,(%a1)+
		swap	%d0
		andiw	#7,%d0
		negw	%d0
		movew	%d0,(%a1)+
		movew	%d2,(%a1)+
		dbf	%d3,loc_5DEE
		rts
/* --------------------------------------------------------------------------- */

loc_5E0E:
		subqw	#1,%d0
		bnes	loc_5DC2
		subqw	#1,(Events_bg+0x00)		/* If routine counter is 2*/
		bnes	loc_5E52
		addqw	#1,(Events_routine_fg)		/* If above timer has expired*/
		move	#0x2700,%sr
		movel	#0x45000003,%d0
		movew	#0xFF,%d3
		bsrw	ClearVRAMArea			/* Clear the Sega logo mappings from foreground*/
		move	#0x2300,%sr
		lea	(Pal_SKTitle_Knux),%a0
		lea	(Normal_palette_line_2),%a2
		moveq	#7,%d0

loc_5E3E:
		movel	(%a0)+,(%a2)+				/* Load the knuckles palette into the final line*/
		dbf	%d0,loc_5E3E
		movel	#Obj_SKTitle_HandAnim,(Dynamic_object_RAM+object_size)	/* Start hand animations*/
		moveq	#0,%d2
		braw	loc_5DC2				/* Then do normal deformation*/
/* --------------------------------------------------------------------------- */

loc_5E52:
		movew	(Camera_X_pos_P2),%d2
		negw	%d2
		movew	#0x6F,%d3

loc_5E5C:
		jsr	(Random_Number)
		addqw	#8,(%a1)			/* On every other line, alternate between moving the line randomly to the left and randomly to the right*/
		andiw	#7,%d0			/* The result is a staticy phaseout effect of the SEGA logo*/
		addw	%d0,(%a1)
		cmpiw	#0xFC,(%a1)
		blts	loc_5E74
		movew	#0xFC,(%a1)

loc_5E74:
		addqw	#2,%a1
		movew	%d2,(%a1)+
		subqw	#8,(%a1)
		swap	%d0
		andiw	#7,%d0
		subw	%d0,(%a1)
		cmpiw	#-0x104,(%a1)
		bgts	loc_5E8C
		movew	#-0x104,(%a1)

loc_5E8C:
		addqw	#2,%a1
		movew	%d2,(%a1)+
		dbf	%d3,loc_5E5C
		rts
/* End of function SKTitle_DeformBG*/

