LevelSelect_S2Options:
		clrw	(Current_zone_and_act)
		bsrw	Pal_FadeToBlack
		move	#0x2700,%sr
		movew	(VDP_reg_1_command),%d0
		andib	#0xBF,%d0
		movew	%d0,(VDP_control_port)
		bsrw	Clear_DisplayData
		lea	(VDP_control_port),%a6
		movew	#0x8004,(%a6)
		movew	#0x8230,(%a6)
		movew	#0x8407,(%a6)
		movew	#0x8230,(%a6)
		movew	#0x8700,(%a6)
		movew	#0x8C81,(%a6)
		movew	#0x9001,(%a6)
		movew	#0x8B00,(%a6)
		lea	(Sprite_table_input),%a1
		moveq	#0,%d0
		movew	#0xFF,%d1

loc_7AC2:
		movel	%d0,(%a1)+
		dbf	%d1,loc_7AC2
		lea	(Object_RAM),%a1
		moveq	#0,%d0
		movew	#(Kos_decomp_buffer-Object_RAM)/4-1,%d1

loc_7AD2:
		movel	%d0,(%a1)+
		dbf	%d1,loc_7AD2
		clrw	(DMA_queue)
		movel	#DMA_queue,(DMA_queue_slot)
		movel	#0x42000000,(VDP_control_port)
		lea	(ArtNem_S22POptions),%a0
		bsrw	Nem_Decomp
		lea	(RAM_start),%a1
		lea	(MapEni_S22POptions),%a0
		movew	#0x6000,%d0
		bsrw	Eni_Decomp
		lea	(RAM_start),%a1
		movel	#0x60000003,%d0
		moveq	#0x27,%d1
		moveq	#0x1B,%d2
		jsr	(Plane_Map_To_VRAM)

		/* Begin level select code*/

		/* S3 loaded S2's level select plane map here, for the level icon emblem*/
		/*lea	(RAM_start),%a1*/
		/*lea	(MapEng_LevSel),%a0*/
		/*movew	#0,%d0*/
		/*bsrw	Eni_Decomp*/

		/* Remember that plane map we just decompressed? Yeah, we're deleting that*/
		lea	(RAM_start),%a3
		/* S3 only cleared 1600 bytes, to preserve the level icon emblem*/
		movew	#((2240>>1)-1),%d1	/* This is the size of your usual decompressed plane map*/

	.clearloop:
		movew	#0,(%a3)+
		dbf	%d1,.clearloop

		/* S3 would remove the one zone name that wasn't cleared// Oil Ocean*/
		/*lea     (RAM_start+((0x50 * 0x15) - (2 * 3))),%a3*/
		/*movew  #0xF,%d1*/

	/*.loop:*/
		/*movew  #0,(%a3)+*/
		/*dbf     %d1,.loop*/

		/* Build new plane map from LevelSelectText and LevSel_MappingOffsets*/

		lea	(RAM_start),%a3
		lea	(LevelSelectText),%a1
		lea	(LevSel_MappingOffsets),%a5
		moveq	#0,%d0
		movew	#0x10,%d1		/* This is how many entries there are in LevelSelectText*/

	.writezone:
		movew	(%a5)+,%d3	/* Get relative address in plane map to write to*/
		lea	(%a3,%d3:w),%a2	/* Get absolute address*/
		moveq	#0,%d2
		moveb	(%a1)+,%d2	/* Get length of string*/
		movew	%d2,%d3		/* Store it*/

	.writeletter:
		moveb	(%a1)+,%d0	/* Get character from string*/
		subib  #0x20,d0
		beqs .isspace
		subib 	#3,d0
	.isspace:
		/*oriw	#((0&1)<<15)+((0&3)<<13)+(0x0000&tile_mask),%d0*/
		movew	%d0,(%a2)+	/* Send it to plane map*/
		dbf	%d2,.writeletter	/* Loop for entire string*/

		movew	#0xD,%d2		/* Maximum length of string*/
		subw	%d3,%d2		/* Get remaining space in string*/
		bcss	.stringfull	/* If there is none, skip ahead*/

	.blankloop:
		movew	#((0&1)<<15)+((0&3)<<13)+(0x20&tile_mask),(%a2)+	/* Full the remaining space with blank characters*/
		dbf	%d2,.blankloop

	.stringfull:
		movew	#((0&1)<<15)+((0&3)<<13)+(0x31&tile_mask),(%a2)	/* Write (act) '1'*/
		lea	0x50(%a2),%a2	/* Next line*/
		movew	#((0&1)<<15)+((0&3)<<13)+(0x32&tile_mask),(%a2)	/* Write (act) '2'*/
		dbf	%d1,.writezone

		/* Assuming the last line was the sound test...*/
		movew	#((0&1)<<15)+((0&3)<<13)+(0x20&tile_mask),(%a2)	/* Get rid of (act) '2'*/
		lea	-0x50(%a2),%a2	/* Go back to (act) '1'*/
		movew	#((0&1)<<15)+((0&3)<<13)+(0x2A&tile_mask),(%a2)	/* Replace that with '*'*/

		/* Overwrite duplicate LAVA REEF 1/2 with 3/4 (obviously, S3 didn't do this)*/
		movew	#((0&1)<<15)+((0&3)<<13)+(0x33&tile_mask),(RAM_start+((0x50 * 4) - (2 * 0x25)))
		movew	#((0&1)<<15)+((0&3)<<13)+(0x34&tile_mask),(RAM_start+((0x50 * 5) - (2 * 0x25)))

		/* Send our built plane map to VRAM*/
		lea	(RAM_start),%a1
		movel	#0x40000003,%d0
		moveq	#0x27,%d1
		moveq	#0x1B,%d2
		jsr	(Plane_Map_To_VRAM)

		moveq	#palette_line_0,%d3
		bsrw	LevelSelect_DrawSoundNumber

		/* in S3, there was some code here for the zone icons, but it was removed in S&K*/
		/*lea	(RAM_start+0x8C0),%a1		// 2240// after the plane map*/
		/*lea	(MapEng_LevSelIcon),%a0*/
		/*movew	#0x90,%d0*/
		/*bsrw	Eni_Decomp*/
		/*bsrw	LevelSelect_DrawIcon*/

		clrw	(Player_mode)
		clrw	(Results_screen_2P)
		clrb	(Level_started_flag)
		clrw	(Anim_Counters)
		lea	(AniPLC_SONICMILES),%a2
		jsr	(AnimateTiles_DoAniPLC)
		moveq	#4,%d0
		bsrw	LoadPalette
		lea	(Normal_palette_line_3),%a1
		lea	(Target_palette_line_3),%a2
		moveq	#7,%d1

loc_7BE4:
		movel	(%a1),(%a2)+
		clrl	(%a1)+
		dbf	%d1,loc_7BE4
		moveb	#mus_DataSelect,%d0
		jsr	(Play_Sound)
		movew	#0x707,(Demo_timer)
		clrw	(Competition_mode)
		clrl	(Camera_X_pos)
		clrl	(Camera_Y_pos)
		clrl	(Save_pointer)
		clrl	(Collected_special_ring_array)
		clrb	(Last_star_post_hit)
		clrb	(Special_bonus_entry_flag)
		clrb	(Blue_spheres_stage_flag)
		nop
		nop
		nop
		nop
		nop
		nop
		clrw	(Level_select_cheat_counter)
		clrw	(Debug_mode_cheat_counter)
		moveb	#0x16,(V_int_routine)
		bsrw	Wait_VSync
		movew	(VDP_reg_1_command),%d0
		orib	#0x40,%d0
		movew	%d0,(VDP_control_port)
		bsrw	Pal_FadeFromBlack

LevelSelect_Main:	/* routine running during level select*/
		moveb	#0x16,(V_int_routine)
		bsrw	Wait_VSync
		move	#0x2700,%sr
		moveq	#palette_line_0-palette_line_0,%d3
		bsrw	LevelSelect_MarkFields
		bsrw	LevSelControls
		movew	#palette_line_3-palette_line_0,%d3
		bsrw	LevelSelect_MarkFields
		/* In S3, there was a branch to some zone icon code here*/
		/*bsrw	LevelSelect_DrawIcon*/
		move	#0x2300,%sr
		lea	(AniPLC_SONICMILES),%a2
		jsr	(AnimateTiles_DoAniPLC)
		moveb	(Ctrl_1_pressed),%d0
		orb	(Ctrl_2_pressed),%d0
		andib	#0x80,%d0
		bnes	LevelSelect_PressStart
		braw	LevelSelect_Main
