LevelSelect_PressStart:
		tstw	(SK_alone_flag)
		beqs	loc_7CA0
		cmpiw	#3,(Player_option)
		bhss	loc_7CA0
		movew	#1,(Player_option)

loc_7CA0:
		movew	(Player_option),(Player_mode)
		lea	LS_Level_Order(%pc),%a1
		movew	(Level_select_option),%d0
		addw	%d0,%d0
		movew	(%a1,%d0:w),%d0
		bmiw	LevelSelect_Return	/* sound test*/
		cmpiw	#0x5555,%d0		/* This was used in Sonic 3 for the S&K zones*/
		beqw	LevelSelect_Main	/* If entry is 0x5555, don't do anything*/
		moveb	#3,(Life_count)
		moveb	#0,(SK_special_stage_flag)
		cmpiw	#0x4000,%d0			/* Is Special Stage 1 selected?*/
		beqw	LevelSelect_SpecialStageCheck	/* If so, branch*/
		cmpiw	#0x4001,%d0			/* Is Special Stage 2 selected?*/
		bnew	LevelSelect_CheckKnuckles	/* If not, branch*/
		moveb	#1,(SK_special_stage_flag)

LevelSelect_SpecialStage:
