		tstw	(SK_alone_flag)
		beqs	locret_7D12
		cmpiw	#0x400,(Current_zone_and_act)
		beqs	locret_7D12
		cmpiw	#0x700,(Current_zone_and_act)
		bhss	locret_7D12
		movew	#0x700,%d0
		movew	%d0,(Current_zone_and_act)
		movew	%d0,(Apparent_zone_and_act)
		movew	%d0,(Saved_zone_and_act)
		movew	%d0,(Saved_apparent_zone_and_act)

locret_7D12:
		rts
