		moveb	#1,(SK_special_stage_flag)
		bras	LevelSelect_SpecialStage
/* --------------------------------------------------------------------------- */
LS_Level_Order:
		.word    0	/* AIZ act 1*/
		.word    1	/* AIZ act 2*/
		.word 0x100	/* HCZ act 1*/
		.word 0x101	/* HCZ act 2*/
		.word 0x200	/* MGZ act 1*/
		.word 0x201	/* MGZ act 2*/
		.word 0x300	/* CNZ act 1*/
		.word 0x301	/* CNZ act 2*/
		.word 0x500	/* ICZ act 1*/
		.word 0x501	/* ICZ act 2*/
		.word 0x600	/* LBZ act 1*/
		.word 0x601	/* LBZ act 2*/
		.word 0x700	/* MHZ act 1*/
		.word 0x701	/* MHZ act 2*/
		.word 0x400	/* FBZ act 1*/
		.word 0x401	/* FBZ act 2*/
		.word 0x800	/* SOZ act 1*/
		.word 0x801	/* SOZ act 2*/
		.word 0x900	/* LRZ act 1*/
		.word 0x901	/* LRZ act 2*/
		.word 0x1600	/* LRZ act 3*/
		.word 0x1601	/* LRZ act 4*/
		.word 0xA00	/* SSZ act 1*/
		.word 0xA01	/* SSZ act 2*/
		.word 0xB00	/* DEZ act 1*/
		.word 0xB01	/* DEZ act 2*/
		.word 0xC00	/* DDZ act 1*/
		.word 0x1700	/* DDZ act 2*/
		.word 0x1400	/* Bonus Stage 1*/
		.word 0x1500	/* Bonus Stage 2*/
		.word 0x4000	/* Special Stage 1*/
		.word 0x4001	/* Special Stage 2*/
		.word 0xFFFF	/* Sound Test*/
/* --------------------------------------------------------------------------- */

LevelSelect_Return:
		moveb	#0,(Game_mode)
		rts
/* --------------------------------------------------------------------------- */

LevelSelect_CheckKnuckles:
		tstw	(Debug_cheat_flag)
		bnes	loc_7DBA
		cmpiw	#3,(Player_mode)		/* Are we Knuckles?*/
		blos	LevelSelect_CheckSonicTails	/* If not, branch*/
		cmpiw	#0xA00,%d0			/* Is SSZ act 1 selected?*/
		beqs	LevelSelect_DenySelection	/* If so, branch and deny entry*/
		cmpiw	#0xC00,%d0			/* Is DDZ act 1 selected?*/
		beqs	LevelSelect_DenySelection	/* If so, branch and deny entry*/
		cmpiw	#0x1600,%d0			/* Is LRZ act 3 selected?*/
		beqs	LevelSelect_DenySelection	/* If so, branch and deny entry*/
		cmpiw	#0x1700,%d0			/* Is DDZ act 2 selected?*/
		bnes	LevelSelect_CheckSonicTails	/* If not, branch*/


LevelSelect_DenySelection:
		moveb	#sfx_Error,%d0			/* Play error buzzer sound*/
		jsr	(Play_Sound_2)
		braw	LevelSelect_Main
/* --------------------------------------------------------------------------- */

LevelSelect_CheckSonicTails:
		cmpiw	#3,(Player_mode)		/* Are we Knuckles (any character with an ID of 3+)?*/
		bhss	loc_7DAC			/* If so, branch*/
		cmpiw	#0xA01,%d0			/* Is SSZ act 2 selected?*/
		beqs	LevelSelect_DenySelection	/* If so, branch and deny entry*/

loc_7DAC:
		cmpiw	#2,(Player_mode)		/* Are we Tails?*/
		bnes	loc_7DBA			/* If not, branch*/
		cmpiw	#0xC00,%d0			/* Is DDZ act 1 selected?*/
		beqs	LevelSelect_DenySelection	/* If so, branch and deny entry*/

loc_7DBA:
		tstw	(SK_alone_flag)	/* Are we playing S3K and not S&K?*/
		beqs	LevelSelect_StartZone	/* If so, branch*/
		/* This here stops you from accessing S3 zones in S&K*/
		movew	%d0,%d1			/* Load selection*/
		moveb	#0,%d1			/* Eliminate act byte, leaving only the zone*/
		cmpiw	#0x400,%d1		/* Is FBZ selected?*/
		beqs	LevelSelect_StartZone	/* If so, branch*/
		cmpiw	#0x700,%d1		/* Is any other S&K zone selected?*/
		bhss	LevelSelect_StartZone	/* If so, branch*/
		movew	#0x700,%d0		/* If any S3 zone is selected, force it to be MHZ*/

LevelSelect_StartZone:
		andiw	#0x3FFF,%d0
		movew	%d0,(Current_zone_and_act)
		movew	%d0,(Apparent_zone_and_act)
		movew	%d0,(Saved_zone_and_act)
		movew	%d0,(Saved_apparent_zone_and_act)
		movew	#0x1000,%d0
		movew	%d0,(Saved_camera_max_Y_pos)
		movew	%d0,(Saved2_camera_max_Y_pos)
		moveb	#0xC,(Game_mode)
		moveb	#3,(Life_count)
		moveb	#3,(Life_count_P2)
		moveq	#0,%d0
		movew	%d0,(Ring_count)
		movel	%d0,(Timer)
		movel	%d0,(Score)
		movew	%d0,(Ring_count_P2)
		movel	%d0,(Timer_P2)
		movel	%d0,(Score_P2)
		moveb	%d0,(Continue_count)
		movew	%d0,(Demo_mode_flag)
		movel	#5000,(Next_extra_life_score)
		movel	#5000,(Next_extra_life_score_P2)
		moveb	#mus_FadeOut,%d0
		jsr	(Play_Sound)
		moveq	#0,%d0
		movew	%d0,(Competition_mode_monitors)
		movew	%d0,(Competition_mode)
		cmpib	#0xE,(Current_zone)
		blos	locret_7E62
		cmpib	#0x13,(Current_zone)
		bhss	locret_7E62
		movew	#1,(Competition_mode)

locret_7E62:
		rts

/* =============== S U B R O U T I N E =======================================*/


LevSelControls:
		moveb	(Ctrl_1_pressed),%d1
		andib	#3,%d1
		bnes	loc_7E74	/* up/down pressed*/
		subqw	#1,(Level_select_repeat)
		bpls	LevSelControls_CheckLR

loc_7E74:
		movew	#0xB,(Level_select_repeat)
		moveb	(Ctrl_1),%d1
		andib	#3,%d1
		beqs	LevSelControls_CheckLR	/* up/down not pressed, check for left & right*/
		movew	(Level_select_option),%d0
		btst	#0,%d1
		beqs	loc_7E94
		subqw	#1,%d0		/* decrease by 1*/
		bccs	loc_7E94	/* >= 0?*/
		moveq	#0x20,%d0		/* set to 0x20*/

loc_7E94:
		btst	#1,%d1
		beqs	loc_7EA4
		addqw	#1,%d0		/* yes, add 1*/
		cmpiw	#0x21,%d0
		blos	loc_7EA4	/* smaller than 0x21?*/
		moveq	#0,%d0		/* .if not, set to 0*/

loc_7EA4:
		movew	%d0,(Level_select_option)
		rts
/* --------------------------------------------------------------------------- */

LevSelControls_CheckLR:
		cmpiw	#0x20,(Level_select_option)		/* are we in the sound test?*/
		bnes	LevSelControls_SwitchSide	/* no*/
		movew	(Sound_test_sound),%d0
		moveb	(Ctrl_1_pressed),%d1
		btst	#2,%d1
		beqs	loc_7EC6
		subqb	#1,%d0
		bccs	loc_7EC6
		moveq	#0,%d0

loc_7EC6:
		btst	#3,%d1
		beqs	loc_7ED6
		addqb	#1,%d0
		cmpiw	#0x100,%d0
		blos	loc_7ED6
		moveq	#0,%d0

loc_7ED6:
		btst	#6,%d1
		beqs	loc_7EE4
		addib	#0x10,%d0
		andib	#0xFF,%d0

loc_7EE4:
		movew	%d0,(Sound_test_sound)
		btst	#4,%d1
		beqs	loc_7EF8
		moveb	#mus_MutePSG,%d0
		jmp	(Play_Sound)
/* --------------------------------------------------------------------------- */

loc_7EF8:
		btst	#5,%d1
		beqs	locret_7F06
		movew	(Sound_test_sound),%d0
	.if sfx_First<>0
		cmpib	#sfx_First,%d0
		blos	.play_music
	.endif
	.if sfx_First<0xff
		cmpib	#sfx__End,%d0
		bhis	.play_music
	.endif
		jmp	(Play_Sound_2)
/* --------------------------------------------------------------------------- */

.play_music:
		jmp	(Play_Sound)

/* --------------------------------------------------------------------------- */

locret_7F06:
		rts
/* --------------------------------------------------------------------------- */

LevSelControls_SwitchSide:
		moveb	(Ctrl_1_pressed),%d1
		andib	#0xC,%d1
		beqs	loc_7F1E
		movew	(Level_select_option),%d0
		moveb	LevelSelect_SwitchTable(%pc,%d0:w),%d0
		movew	%d0,(Level_select_option)

loc_7F1E:
		bras	loc_7F46
/* --------------------------------------------------------------------------- */
		rts
/* --------------------------------------------------------------------------- */
