		.byte 0x1F	/* 13*/
		.byte 0x20	/* 14*/
		.byte 0x20	/* 15*/
		.byte 0x20	/* 16*/
		.byte 0x20	/* 17*/
		.byte 0		/* 18*/
		.byte 1		/* 19*/
		.byte 2		/* 20*/
		.byte 3		/* 21*/
		.byte 4		/* 22*/
		.byte 5		/* 23*/
		.byte 6		/* 24*/
		.byte 7		/* 25*/
