		.byte 0xE		/* 32*/
		.byte 0xF		/* 33*/
		.byte 0x10	/* 34*/
		.byte 0x11	/* 35*/
/* --------------------------------------------------------------------------- */

loc_7F46:
		btst	#5,(Ctrl_1_pressed)
		beqs	locret_7F60
		addqw	#1,(Player_option)
		cmpiw	#5,(Player_option)
		blos	locret_7F60
		movew	#0,(Player_option)

locret_7F60:
		rts
