		movew	#0x400,%d6
		bsrw	FindWall
		movew	%d1,-(%sp)
		movew	0x14(%a0),%d2
		movew	0x10(%a0),%d3
		moveq	#0,%d0
		moveb	0x1F(%a0),%d0
		extw	%d0
		addw	%d0,%d2
		moveb	0x1E(%a0),%d0
		extw	%d0
		subw	%d0,%d3
		eoriw	#0xF,%d3
		lea	(Secondary_Angle),%a4
		moveaw	#-0x10,%a3
		movew	#0x400,%d6
		bsrw	FindWall
		movew	(%sp)+,%d0
		moveb	#0x40,%d2
		braw	loc_F7E2
/* End of function CheckLeftCeilingDist*/


