		movew	0x10(%a0),%d3
		moveq	#0,%d0
		moveb	0x1E(%a0),%d0
		extw	%d0
		subw	%d0,%d2
		moveb	0x1F(%a0),%d0
		extw	%d0
		subw	%d0,%d3
		eoriw	#0xF,%d3
		lea	(Primary_Angle),%a4
