TouchResponse_CompetitionMode:
		nop
		movew	x_pos(%a0),%d2				/* Get player's x_pos*/
		movew	y_pos(%a0),%d3				/* Get player's y_pos*/
		subiw	#4,%d2					/* Subtract Obj_Sonic2P's x_radius-1 from x_pos*/
		moveq	#0,%d5
		moveb	y_radius(%a0),%d5
		subqb	#3,%d5
		subw	%d5,%d3
		movew	#8,%d4					/* Player's width*/
		addw	%d5,%d5
		bras	Touch_Process
/* --------------------------------------------------------------------------- */

TouchResponse:
		nop
		jsr	(Test_Ring_Collisions)
		bsrw	ShieldTouchResponse
		tstb	character_id(%a0)			/* Is the player Sonic?*/
		bnes	Touch_NoInstaShield			/* If not, branch*/
		moveb	status_secondary(%a0),%d0
		andib	#0x73,%d0					/* Does the player have any shields or is invincible?*/
		bnes	Touch_NoInstaShield			/* If so, branch*/
		/* By this point, we're focussing purely on the Insta-Shield*/
		cmpib	#1,double_jump_flag(%a0)			/* Is the Insta-Shield currently in its 'attacking' mode?*/
		bnes	Touch_NoInstaShield			/* If not, branch*/
		moveb	status_secondary(%a0),%d0			/* Get status_secondary...*/
		movew	%d0,-(%sp)				/* ...and save it*/
		bset	#Status_Invincible,status_secondary(%a0)	/* Make the player invincible*/
		movew	x_pos(%a0),%d2				/* Get player's x_pos*/
		movew	y_pos(%a0),%d3				/* Get player's y_pos*/
		subiw	#0x18,%d2					/* Subtract width of Insta-Shield*/
		subiw	#0x18,%d3					/* Subtract height of Insta-Shield*/
		movew	#0x30,%d4					/* Player's width*/
		movew	#0x30,%d5					/* Player's height*/
		bsrs	Touch_Process
		movew	(%sp)+,%d0				/* Get the backed-up status_secondary*/
		btst	#Status_Invincible,%d0			/* Was the player already invincible (wait, what? An earlier check ensures that this can't happen)*/
		bnes	.alreadyinvincible			/* If so, branch*/
		bclr	#Status_Invincible,status_secondary(%a0)	/* Make the player vulnerable again*/

	.alreadyinvincible:
		moveq	#0,%d0
		rts
/* --------------------------------------------------------------------------- */

Touch_NoInstaShield:
		movew	x_pos(%a0),%d2				/* Get player's x_pos*/
		movew	y_pos(%a0),%d3				/* Get player's y_pos*/
		subiw	#8,%d2					/* Subtract Obj_Sonic's x_radius-1 from x_pos (becomes player's left collision boundary)*/
		moveq	#0,%d5
		moveb	y_radius(%a0),%d5
		subqb	#3,%d5					/* Now player's collision height*/
		subw	%d5,%d3
		/* Note the lack of a check for .if the player is ducking*/
		/* Height is no longer reduced by ducking*/
		movew	#0x10,%d4					/* Player's collision width*/
		addw	%d5,%d5

Touch_Process:
		lea	(Collision_response_list),%a4
		movew	(%a4)+,%d6				/* Get number of objects queued*/
		beqs	locret_FF1C				/* If there are none, return*/

Touch_Loop:
		moveaw	(%a4)+,%a1				/* Get address of first object's RAM*/
		moveb	collision_flags(%a1),%d0			/* Get its collision_flags*/
		bnes	Touch_Width				/* If it actually has collision, branch*/

Touch_NextObj:
		subqw	#2,%d6					/* Count the object as done*/
		bnes	Touch_Loop				/* If there are still objects left, loop*/
		moveq	#0,%d0

locret_FF1C:
		rts
/* --------------------------------------------------------------------------- */

Touch_Width:
		andiw	#0x3F,%d0					/* Get only collision size*/
		addw	%d0,%d0					/* Turn into index*/
		lea	Touch_Sizes(%pc,%d0:w),%a2
		moveq	#0,%d1
		moveb	(%a2)+,%d1				/* Get width value from Touch_Sizes*/
		movew	x_pos(%a1),%d0				/* Get object's x_pos*/
		subw	%d1,%d0					/* Subtract object's width*/
		subw	%d2,%d0					/* Subtract player's left collision boundary*/
		bccs	.checkrightside0				/* If player's left side is to the left of the object, branch*/
		addw	%d1,%d1					/* Double object's width value*/
		addw	%d1,%d0					/* Add object's width*2 (now at right of object)*/
		bcss	Touch_Height				/* If carry, branch (player is within the object's boundaries)*/
		bras	Touch_NextObj				/* If not, loop and check next object*/
/* --------------------------------------------------------------------------- */

	.checkrightside0:
		cmpw	%d4,%d0					/* Is player's right side to the left of the object?*/
		bhis	Touch_NextObj				/* If so, loop and check next object*/

Touch_Height:
		moveq	#0,%d1
		moveb	(%a2)+,%d1				/* Get height value from Touch_Sizes*/
		movew	y_pos(%a1),%d0				/* Get object's y_pos*/
		subw	%d1,%d0					/* Subtract object's height*/
		subw	%d3,%d0					/* Subtract player's bottom collision boundary*/
		bccs	.checktop0				/* If bottom of player is under the object, branch*/
		addw	%d1,%d1					/* Double object's height value*/
		addw	%d1,%d0					/* Add object's height*2 (now at top of object)*/
		bcsw	Touch_ChkValue				/* If carry, branch (player is within the object's boundaries)*/
		bras	Touch_NextObj				/* If not, loop and check next object*/
/* --------------------------------------------------------------------------- */

	.checktop0:
		cmpw	%d5,%d0					/* Is top of player under the object?*/
		bhis	Touch_NextObj				/* If so, loop and check next object*/
		braw	Touch_ChkValue
/* --------------------------------------------------------------------------- */
/* collision sizes (width,height)*/
Touch_Sizes:	.byte    4,   4
		.byte  0x14, 0x14
		.byte   0xC, 0x14
		.byte  0x14,  0xC
		.byte    4, 0x10
		.byte   0xC, 0x12
		.byte  0x10, 0x10
		.byte    6,   6
		.byte  0x18,  0xC
		.byte   0xC, 0x10
		.byte  0x10,   8
		.byte    8,   8
		.byte  0x14, 0x10
		.byte  0x14,   8
		.byte   0xE,  0xE
		.byte  0x18, 0x18
		.byte  0x28, 0x10
		.byte  0x10, 0x18
		.byte    8, 0x10
		.byte  0x20, 0x70
		.byte  0x40, 0x20
		.byte  0x80, 0x20
		.byte  0x20, 0x20
		.byte    8,   8
		.byte    4,   4
		.byte  0x20,   8
		.byte   0xC,  0xC
		.byte    8,   4
		.byte  0x18,   4
		.byte  0x28,   4
		.byte    4,   8
		.byte    4, 0x18
		.byte    4, 0x28
		.byte  0x18, 0x18
		.byte  0x18, 0x18
		.byte   0xC, 0x18
		.byte  0x48,   8
		.byte  0x18, 0x28
		.byte  0x10,   4
		.byte  0x20,   2
		.byte  0x10, 0x1C
		.byte   0xC, 0x24
		.byte  0x10,   2
		.byte    4, 0x40
		.byte  0x18, 0x40
		.byte  0x20, 0x10
		.byte  0x1C, 0x14
		.byte  0x10,   2
		.byte  0x10,   1
		.byte    2,   8
		.byte  0x10, 0x40
		.byte   0xC,   4
		.byte    8,  0xC
		.byte  0x28, 0x20
		.byte  0x40,   2
		.byte  0x60,   2
		.byte  0x28, 0x28
/* --------------------------------------------------------------------------- */

Touch_ChkValue:
		moveb	collision_flags(%a1),%d1			/* Get its collision_flags*/
		andib	#0xC0,%d1					/* Get only collision type bits*/
		beqw	Touch_Enemy				/* If 00, enemy, branch*/
		cmpib	#0xC0,%d1
		beqw	Touch_Special				/* If 11, "special thing for starpole", branch*/
		tstb	%d1
		bmiw	Touch_ChkHurt				/* If 10, "harmful", branch*/
		/* If 01...*/
		moveb	collision_flags(%a1),%d0			/* Get collision_flags*/
		andib	#0x3F,%d0					/* Get only collision size*/
		cmpib	#6,%d0					/* Is touch response 0x46 ?*/
		beqs	Touch_Monitor				/* If yes, branch*/
		moveb	(Player_1+invulnerability_timer),%d0	/* Get the main character's invulnerability_timer*/
		tstw	(Competition_mode)			/* Is the competition mode?*/
		beqs	.notcompetition				/* If not, branch*/
		moveb	invulnerability_timer(%a0),%d0		/* Get invulnerability_timer from whoever branched to TouchResponse*/

	.notcompetition:
		cmpib	#90,%d0					/* Is there more than 90 frames on the timer remaining?*/
		bhsw	.return0					/* If so, branch*/
		moveb	#4,routine(%a1)				/* Set target object's routine to 4 (must be reserved for collision response)*/

	.return0:
		rts
/* --------------------------------------------------------------------------- */

Touch_Monitor:
		movew	y_vel(%a0),%d0				/* Get player's y_vel*/
		tstb	(Reverse_gravity_flag)		/* Are we in reverse gravity mode?*/
		beqs	.normalgravity0				/* If not, branch*/
		negw	%d0					/* Negate player's y_vel*/

	.normalgravity0:
		btst	#1,render_flags(%a1)			/* Is the monitor upside down?*/
		beqs	.monitornotupsidedown			/* If not, branch*/
		tstw	%d0
		beqs	.checkdestroy				/* If player isn't moving up or down at all, branch*/
		bmis	.checkdestroy				/* If player is moving up, branch*/
		bras	.checkfall				/* If player is moving down, branch*/
/* --------------------------------------------------------------------------- */

	.monitornotupsidedown:
		tstw	%d0
		bpls	.checkdestroy				/* If player is moving down, branch*/

	.checkfall:
		/* This check is responsible for S&K's monitors not falling .if hit from below (but only in regular gravity. See below)*/
		btst	#1,status(%a1)				/* Is the monitor upside down (different way of checking)?*/
		beqs	.checkdestroy				/* If not, branch*/
		btst	#1,render_flags(%a1)			/* Is the monitor upside down?*/
		bnes	.monitorupsidedown			/* If so, branch*/
		movew	y_pos(%a0),%d0				/* Get player's y_pos*/
		subiw	#0x10,%d0					/* Subtract height of monitor from it*/
		cmpw	y_pos(%a1),%d0
		blos	.return1					/* If new value is lower than monitor's y_pos, return*/
		bras	.monitorfall
/* --------------------------------------------------------------------------- */

	.monitorupsidedown:
		movew	y_pos(%a0),%d0				/* Get player's y_pos*/
		addiw	#0x10,%d0					/* Add height of monitor from it*/
		cmpw	y_pos(%a1),%d0
		bhss	.return1					/* If new value is higher than monitor's y_pos, return*/

	.monitorfall:
		/* Fun fact: In S3, like the games before it, hitting a monitor from below would make it fall*/
		/* In S&K, that was removed, and they are destroyed as normal.*/
		/* However, according to this code, .if a monitor is upside down, and player is in reverse gravity,*/
		/* hitting the monitor from below will still make it fall.*/
		/* Playing with Debug Mode confirms this.*/
		negw	y_vel(%a0)				/* Reverse Sonic's y-motion*/
		movew	#-0x180,y_vel(%a1)
		tstb	routine_secondary(%a1)
		bnes	.return1
		moveb	#4,routine_secondary(%a1)		/* Set the monitor's routine_secondary counter,*/
		rts
/* --------------------------------------------------------------------------- */

	.checkdestroy:
		cmpaw	#Player_1,%a0				/* Is this the main character?*/
		beqs	.validcharacter				/* If so, branch*/
		tstw	(Competition_mode)			/* Are we in competition mode?*/
		beqs	.return1					/* If not, return*/

	.validcharacter:
		cmpib	#2,anim(%a0)				/* Is player in his rolling animation?*/
		beqs	.okaytodestroy				/* If so, branch*/
		cmpib	#2,character_id(%a0)			/* Is player Knuckles?*/
		bnes	.return1					/* If not, return*/
		cmpib	#1,double_jump_flag(%a0)			/* Is Knuckles gliding?*/
		beqs	.okaytodestroy				/* If so, branch*/
		cmpib	#3,double_jump_flag(%a0)			/* Is Knuckles sliding across the ground after gliding?*/
		bnes	.return1					/* If not, branch*/

	.okaytodestroy:
		negw	y_vel(%a0)
		moveb	#4,routine(%a1)
		movew	%a0,parent(%a1)

	.return1:
		rts
/* --------------------------------------------------------------------------- */

Touch_Enemy:
		btst	#Status_Invincible,status_secondary(%a0)	/* Is player invincible?*/
		bnes	.checkhurtenemy				/* If so, branch*/
		cmpib	#9,anim(%a0)				/* Is player in their spin dash animation?*/
		beqs	.checkhurtenemy				/* If so, branch*/
		cmpib	#2,anim(%a0)				/* Is player in their rolling animation?*/
		beqs	.checkhurtenemy				/* If so, branch*/
		cmpib	#2,character_id(%a0)			/* Is player Knuckles?*/
		bnes	.notknuckles				/* If not, branch*/
		cmpib	#1,double_jump_flag(%a0)			/* Is Knuckles gliding?*/
		beqs	.checkhurtenemy				/* If so, branch*/
		cmpib	#3,double_jump_flag(%a0)			/* Is Knuckles sliding across the ground after gliding?*/
		beqs	.checkhurtenemy				/* If so, branch*/
		braw	Touch_ChkHurt
/* --------------------------------------------------------------------------- */

	.notknuckles:
		cmpib	#1,character_id(%a0)			/* Is player Tails*/
		bnew	Touch_ChkHurt				/* If not, branch*/
		tstb	double_jump_flag(%a0)			/* Is Tails flying ("gravity-affected")*/
		beqw	Touch_ChkHurt				/* If not, branch*/
		btst	#Status_Underwater,status(%a0)		/* Is Tails underwater*/
		bnew	Touch_ChkHurt				/* If not, branch*/
		movew	x_pos(%a0),%d1
		movew	y_pos(%a0),%d2
		subw	x_pos(%a1),%d1
		subw	y_pos(%a1),%d2
		jsr	(GetArcTan)
		subib	#0x20,%d0
		cmpib	#0x40,%d0
		bhsw	Touch_ChkHurt

	.checkhurtenemy:
		/* Boss related? Could be special enemies in general*/
		tstb	boss_hitcount2(%a1)		/* Is this a boss? (?)*/
		beqs	Touch_EnemyNormal		/* If not, branch*/
		negw	x_vel(%a0)			/* Bounce player directly off boss*/
		negw	y_vel(%a0)
		negw	ground_vel(%a0)
		moveb	collision_flags(%a1),0x25(%a1)	/* ???*/
		movew	%a0,%d0				/* Save value of RAM address of which player hit the boss:*/
		moveb	%d0,0x1C(%a1)			/* (0xFFFFB000) for main character, (0xFFFFB04A) for sidekick*/
		moveb	#0,collision_flags(%a1)
		subqb	#1,boss_hitcount2(%a1)		/* Subtract from boss hit counter*/
		bnes	.bossnotedefeated		/* If boss is not defeated yet, branch*/
		bset	#7,status(%a1)

	.bossnotedefeated:
		cmpib	#2,character_id(%a0)		/* Is player Knuckles?*/
		bnes	.return3				/* If not, return*/
		cmpib	#1,double_jump_flag(%a0)		/* Is Knuckles gliding?*/
		bnes	.return3				/* If not, return*/
		moveb	#2,double_jump_flag(%a0)		/* Make him stop gliding*/
		moveb	#0x21,anim(%a0)			/* Put Knuckles in his falling animation*/
		/* Decide which direction to make Knuckles face*/
		bclr	#0,status(%a0)
		tstw	x_vel(%a0)
		bmis	.directiondecided
		bset	#0,status(%a0)

	.directiondecided:
		moveb	default_y_radius(%a0),y_radius(%a0)
		moveb	default_x_radius(%a0),x_radius(%a0)

	.return3:
		rts
/* --------------------------------------------------------------------------- */

Touch_EnemyNormal:
		btst	#2,status(%a1)			/* Should the object remember that it's been destroyed (Remember Sprite State flag)?*/
		beqs	.dontremember0			/* If not, branch*/
		moveb	ros_bit(%a1),%d0
		moveaw	ros_addr(%a1),%a2
		bclr	%d0,(%a2)				/* Mark object as destroyed*/

	.dontremember0:
		bset	#7,status(%a1)
		moveq	#0,%d0
		movew	(Chain_bonus_counter),%d0	/* Get copy of chain bonus counter*/
		addqw	#2,(Chain_bonus_counter)	/* Add 2 to chain bonus counter*/
		cmpiw	#6,%d0				/* Has the counter already surpassed 5?*/
		blos	.notreachedlimit0		/* If not, branch*/
		moveq	#6,%d0				/* Cap counter at 6*/

	.notreachedlimit0:
		movew	%d0,objoff_3E(%a1)
		movew	Enemy_Points(%pc,%d0:w),%d0	/* Get appropriate number of points*/
		cmpiw	#16*2,(Chain_bonus_counter)	/* Have 16 enemies been destroyed?*/
		blos	.notreachedlimit20		/* If not, branch*/
		movew	#1000,%d0			/* Fix bonus to 10000 points*/
		movew	#0xA,objoff_3E(%a1)

	.notreachedlimit20:
		moveaw	%a0,%a3
		bsrw	HUD_AddToScore
		movel	#Obj_Explosion,(%a1)		/* Create enemy destruction explosion*/
		moveb	#0,routine(%a1)
		tstw	y_vel(%a0)			/* Is player moving up?*/
		bmis	.bounceplayerdown		/* If so, branch*/
		movew	y_pos(%a0),%d0
		cmpw	y_pos(%a1),%d0			/* Was player above, or at the same height as, the enemy when it was destroyed*/
		bhss	.bounceplayerup			/* If so, branch*/
		negw	y_vel(%a0)			/* Totally negate velocity (???)*/
		rts
/* --------------------------------------------------------------------------- */

	.bounceplayerdown:
		addiw	#0x100,y_vel(%a0)			/* Bounce down*/
		rts
