/* --------------------------------------------------------------------------- */
/* Subroutine for checking .if Sonic/Tails/Knuckles should be hurt and hurting them .if so*/
/* note: character must be at %a0*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/

Touch_ChkHurt:
		moveb	status_secondary(%a0),%d0
		andib	#0x73,%d0					/* Does player have any shields or is invincible?*/
		beqs	Touch_ChkHurt_NoPowerUp			/* If not, branch*/
		andb	shield_reaction(%a1),%d0			/* Does one of the player's shields grant immunity to this object??*/
		bnes	Touch_ChkHurt_Return			/* If so, branch*/
		btst	#Status_Shield,status_secondary(%a0)	/* Does the player have a shield (strange time to ask)*/
		bnes	Touch_ChkHurt_HaveShield		/* If so, branch*/

Touch_ChkHurt2:
		btst	#Status_Invincible,status_secondary(%a0)	/* Is player invincible?*/
		beqs	Touch_Hurt				/* If not, branch*/

Touch_ChkHurt_Return:
		moveq	#-1,%d0
		rts
/* --------------------------------------------------------------------------- */

Touch_ChkHurt_NoPowerUp:
		/* Note that this check could apply to the Insta-Shield,*/
		/* but the check that branches to this requires the player not be invincible.*/
		/* The Insta-Shield grants temporary invincibility. See the problem?*/
		cmpib	#1,double_jump_flag(%a0)			/* Is player Insta-Shield-attacking (Sonic), flying (Tails) or gliding (Knuckles)?*/
		bnes	Touch_ChkHurt2				/* If not, branch*/

Touch_ChkHurt_HaveShield:
		moveb	shield_reaction(%a1),%d0
		andib	#8,%d0					/* Should the object be bounced away by a shield?*/
		beqs	Touch_ChkHurt2				/* If not, branch*/

Touch_ChkHurt_Bounce_Projectile:
		movew	x_pos(%a0),%d1
		movew	y_pos(%a0),%d2
		subw	x_pos(%a1),%d1
		subw	y_pos(%a1),%d2
		jsr	(GetArcTan)
		jsr	(GetSineCosine)
		mulsw	#-0x800,%d1
		asrl	#8,%d1
		movew	%d1,x_vel(%a1)
		mulsw	#-0x800,%d0
		asrl	#8,%d0
		movew	%d0,y_vel(%a1)
		clrb	collision_flags(%a1)
		bras	Touch_ChkHurt_Return
/* --------------------------------------------------------------------------- */

Touch_Hurt:
		nop
		tstb	invulnerability_timer(%a0)	/* Is the player invulnerable?*/
		bnes	Touch_ChkHurt_Return		/* If so, branch*/
		moveal	%a1,%a2

/* End of function TouchResponse*/
/* continue straight to HurtCharacter*/

