Add_SpriteToCollisionResponseList:
		lea	(Collision_response_list),%a1
		cmpiw	#0x7E,(%a1)	/* Is list full?*/
		bhss	.return4		/* If so, return*/
		addqw	#2,(%a1)		/* Count this new entry*/
		addaw	(%a1),%a1		/* Offset into right area of list*/
		movew	%a0,(%a1)		/* Store RAM address in list*/

	.return4:
		rts
/* End of function Add_SpriteToCollisionResponseList*/


