ShieldTouchResponse:
		moveb	status_secondary(%a0),%d0
		andib	#0x71,%d0				/* Does the player have any shields?*/
		beqs	locret_1045C
		movew	x_pos(%a0),%d2			/* Get player's x_pos*/
		movew	y_pos(%a0),%d3			/* Get player's y_pos*/
		subiw	#0x18,%d2				/* Subtract width of shield*/
		subiw	#0x18,%d3				/* Subtract height of shield*/
		movew	#0x30,%d4				/* Player's width*/
		movew	#0x30,%d5				/* Player's height*/
		lea	(Collision_response_list),%a4
		movew	(%a4)+,%d6			/* Get number of objects queued*/
		beqs	locret_1045C			/* If there are none, return*/

ShieldTouch_Loop:
		moveaw	(%a4)+,%a1			/* Get address of first object's RAM*/
		moveb	collision_flags(%a1),%d0		/* Get its collision_flags*/
		andib	#0xC0,%d0				/* Get only collision type bits*/
		cmpib	#0x80,%d0				/* Is only the high bit set ("harmful")?*/
		beqs	ShieldTouch_Width		/* If so, branch*/

ShieldTouch_NextObj:
		subqw	#2,%d6				/* Count the object as done*/
		bnes	ShieldTouch_Loop		/* If there are still objects left, loop*/

locret_1045C:
		rts
/* --------------------------------------------------------------------------- */

ShieldTouch_Width:
		moveb	collision_flags(%a1),%d0		/* Get collision_flags*/
		andiw	#0x3F,%d0				/* Get only collision size*/
		beqs	ShieldTouch_NextObj		/* If it doesn't have a size, branch*/
		addw	%d0,%d0				/* Turn into index*/
		lea	(Touch_Sizes),%a2
		lea	(%a2,%d0:w),%a2			/* Go to correct entry*/
		moveq	#0,%d1
		moveb	(%a2)+,%d1			/* Get width value from Touch_Sizes*/
		movew	x_pos(%a1),%d0			/* Get object's x_pos*/
		subw	%d1,%d0				/* Subtract object's width*/
		subw	%d2,%d0				/* Subtract player's left collision boundary*/
		bhss	.checkrightside1			/* If player's left side is to the left of the object, branch*/
		addw	%d1,%d1				/* Double object's width value*/
		addw	%d1,%d0				/* Add object's width*2 (now at right of object)*/
		blos	ShieldTouch_Height		/* If carry, branch (player is within the object's boundaries)*/
		bras	ShieldTouch_NextObj		/* If not, loop and check next object*/
/* --------------------------------------------------------------------------- */

	.checkrightside1:
		cmpw	%d4,%d0				/* Is player's right side to the left of the object?*/
		bhis	ShieldTouch_NextObj		/* If so, loop and check next object*/

ShieldTouch_Height:
		moveq	#0,%d1
		moveb	(%a2)+,%d1			/* Get height value from Touch_Sizes*/
		movew	y_pos(%a1),%d0			/* Get object's y_pos*/
		subw	%d1,%d0				/* Subtract object's height*/
		subw	%d3,%d0				/* Subtract player's bottom collision boundary*/
		bccs	.checktop1			/* If bottom of player is under the object, branch*/
		addw	%d1,%d1				/* Double object's height value*/
		addw	%d1,%d0				/* Add object's height*2 (now at top of object)*/
		bcsw	.checkdeflect			/* If carry, branch (player is within the object's boundaries)*/
		bras	ShieldTouch_NextObj		/* If not, loop and check next object*/
/* --------------------------------------------------------------------------- */

	.checktop1:
		cmpw	%d5,%d0				/* Is top of player under the object?*/
		bhis	ShieldTouch_NextObj		/* If so, loop and check next object*/

	.checkdeflect:
		moveb	shield_reaction(%a1),%d0
		andib	#8,%d0				/* Should the object be bounced away by a shield?*/
		beqs	ShieldTouch_NextObj		/* If not, branch*/
		movew	x_pos(%a0),%d1
		movew	y_pos(%a0),%d2
		subw	x_pos(%a1),%d1
		subw	y_pos(%a1),%d2
		jsr	(GetArcTan)
		jsr	(GetSineCosine)
		mulsw	#-0x800,%d1
		asrl	#8,%d1
		movew	%d1,x_vel(%a1)
		mulsw	#-0x800,%d0
		asrl	#8,%d0
		movew	%d0,y_vel(%a1)
		clrb	collision_flags(%a1)
		rts
/* End of function ShieldTouchResponse*/


/* =============== S U B R O U T I N E =======================================*/

/* It seems this is used by Hyper Sonic & Hyper Knuckles for their screen-nukes*/
/* (Hyper Dash, and Hyper Knuckles gliding into a wall)*/

HyperAttackTouchResponse:
		moveml	%a2-%a4,-(%sp)
		lea	(Collision_response_list),%a4
		movew	(%a4)+,%d6			/* Get number of objects queued*/
		beqs	HyperTouch_Exit			/* If there are none, branch*/

HyperTouch_Loop:
		moveaw	(%a4)+,%a1			/* Get address of first object's RAM*/
		moveb	collision_flags(%a1),%d0		/* Get its collision_flags*/
		beqs	HyperTouch_NextObj		/* If it doesn't have collision, branch*/
		bsrs	HyperTouch_ChkValue		/* Else, process object*/

HyperTouch_NextObj:
		subqw	#2,%d6				/* Count the object as done*/
		bnes	HyperTouch_Loop			/* If there are still objects left, loop*/
		moveq	#0,%d0

HyperTouch_Exit:
		moveml	(%sp)+,%a2-%a4
		rts
/* End of function HyperAttackTouchResponse*/


/* =============== S U B R O U T I N E =======================================*/


HyperTouch_ChkValue:
		tstb	render_flags(%a1)		/* Is object on-screen?*/
		bpls	.return5				/* If not, return (screen-nuke only affects what's on-screen)*/
		andib	#0xC0,%d0				/* Get collision_flags type data*/
		beqs	HyperTouch_Enemy		/* If 00, enemy, branch*/
		cmpib	#0xC0,%d0
		beqw	HyperTouch_Special		/* If 11, "special thing for starpole", branch*/
		tstb	%d0
		bmis	HyperTouch_Harmful		/* If 10, "harmful", branch*/

	.return5:
		rts
/* --------------------------------------------------------------------------- */

HyperTouch_Enemy:
		tstb	collision_property(%a1)		/* Is this a special enemy?*/
		beqs	HyperTouch_DestroyEnemy		/* If not, branch*/
		rts
/* --------------------------------------------------------------------------- */

/* Similar to other enemy destruction subroutines, but this one doesn't make the player bounce*/

HyperTouch_DestroyEnemy:
		btst	#2,status(%a1)			/* Should the object remember that it's been destroyed (Remember Sprite State flag)?*/
		beqs	.dontremember1			/* If not, branch*/
		moveb	ros_bit(%a1),%d0
		moveaw	ros_addr(%a1),%a2
		bclr	%d0,(%a2)				/* Mark object as destroyed*/

	.dontremember1:
		bset	#7,status(%a1)
		moveq	#0,%d0
		movew	(Chain_bonus_counter),%d0	/* Get copy of chain bonus counter*/
		addqw	#2,(Chain_bonus_counter)	/* Add 2 to chain bonus counter*/
		cmpiw	#6,%d0				/* Has the counter already surpassed 5?*/
		blos	.notreachedlimit1		/* If not, branch*/
		moveq	#6,%d0				/* Cap counter at 6*/

	.notreachedlimit1:
		movew	%d0,objoff_3E(%a1)
		movew	HyperEnemy_Score(%pc,%d0:w),%d0	/* Get appropriate number of points*/
		cmpiw	#16*2,(Chain_bonus_counter)	/* Have 16 enemies been destroyed?*/
		blos	.notreachedlimit21		/* If not, branch*/
		movew	#1000,%d0			/* Fix bonus to 10000 points*/
		movew	#0xA,objoff_3E(%a1)

	.notreachedlimit21:
		moveaw	%a0,%a3
		bsrw	HUD_AddToScore
		movel	#Obj_Explosion,(%a1)		/* Create enemy destruction explosion*/
		moveb	#0,routine(%a1)
		rts
/* --------------------------------------------------------------------------- */
HyperEnemy_Score:	.word 10, 20, 50, 100
/* --------------------------------------------------------------------------- */

HyperTouch_Harmful:
		moveb	shield_reaction(%a1),%d0
		andib	#8,%d0				/* Should the object be bounced away by a shield?*/
		bnew	Touch_ChkHurt_Bounce_Projectile	/* If so, branch*/
		rts
/* --------------------------------------------------------------------------- */

HyperTouch_Special:
		orib	#3,collision_property(%a1)
		cmpiw	#3,(Player_mode)		/* Are we in Knuckles Alone mode?*/
		blos	.sonicortails			/* If not, branch*/
		movew	x_pos(%a1),(Player_2+x_pos)	/* ???*/
		movew	y_pos(%a1),(Player_2+y_pos)	/* ???*/

	.sonicortails:
		moveb	#2,(Player_2+anim)		/* Put sidekick in his rolling animation*/
		bset	#Status_InAir,(Player_2+status)
		rts
/* End of function HyperTouch_ChkValue*/

