Obj_Sonic:
		/* Load some addresses into registers*/
		/* This is done to allow some subroutines to be*/
		/* shared with Tails/Knuckles.*/
		lea	(Max_speed),%a4
		lea	(Distance_from_top),%a5
		lea	(Dust),%a6

		tstw	(Debug_placement_mode)
		beqs	Sonic_Normal

		/* Debug only code*/
		cmpib	#1,(Debug_placement_type)	/* Are Sonic in debug object placement mode?*/
		beqs	JmpTo_DebugMode			/* If so, skip to debug mode routine*/
		/* By this point, we're assuming you're in frame cycling mode*/
		btst	#button_B,(Ctrl_1_pressed)
		beqs	loc_10ABC
		movew	#0,(Debug_placement_mode)	/* Leave debug mode*/

loc_10ABC:
		addqb	#1,mapping_frame(%a0)		/* Next frame*/
		cmpib	#0xFB,mapping_frame(%a0)		/* Have we reached the end of Sonic's frames?*/
		blos	loc_10ACE
		moveb	#0,mapping_frame(%a0)		/* If so, reset to Sonic's first frame*/

loc_10ACE:
		bsrw	Sonic_Load_PLC
		jmp	(Draw_Sprite)
/* --------------------------------------------------------------------------- */

JmpTo_DebugMode:
		jmp	(DebugMode)
/* --------------------------------------------------------------------------- */

Sonic_Normal:
		moveq	#0,%d0
		moveb	routine(%a0),%d0
		movew	Sonic_Index(%pc,%d0:w),%d1
		jmp	Sonic_Index(%pc,%d1:w)
/* --------------------------------------------------------------------------- */
Sonic_Index:	.word Sonic_Init-Sonic_Index	/*  0*/
		.word Sonic_Control-Sonic_Index	/*  2*/
		.word loc_122BE-Sonic_Index	/*  4*/
		.word loc_12390-Sonic_Index	/*  6*/
		.word loc_1257C-Sonic_Index	/*  8*/
		.word loc_12590-Sonic_Index	/* 0xA*/
		.word loc_125AC-Sonic_Index	/* 0xC*/
/* --------------------------------------------------------------------------- */

Sonic_Init:	/* Routine 0*/
		addqb	#2,routine(%a0)		/* => Obj01_Control*/
		moveb	#0x13,y_radius(%a0)	/* this sets Sonic's collision height (2*pixels)*/
		moveb	#9,x_radius(%a0)
		moveb	#0x13,default_y_radius(%a0)
		moveb	#9,default_x_radius(%a0)
		movel	#Map_Sonic,mappings(%a0)
		movew	#0x100,priority(%a0)
		moveb	#0x18,width_pixels(%a0)
		moveb	#0x18,height_pixels(%a0)
		moveb	#4,render_flags(%a0)
		moveb	#0,character_id(%a0)
		movew	#0x600,Max_speed-Max_speed(%a4)
		movew	#0xC,Acceleration-Max_speed(%a4)
		movew	#0x80,Deceleration-Max_speed(%a4)
		tstb	(Last_star_post_hit)
		bnes	Sonic_Init_Continued
		/* only happens when not starting at a checkpoint:*/
		movew	#ArtTile_Player_1,art_tile(%a0)
		moveb	#0xC,top_solid_bit(%a0)
		moveb	#0xD,lrb_solid_bit(%a0)
		cmpib	#2,(Special_bonus_entry_flag)
		beqs	Sonic_Init_Continued
		/* only happens when not starting at a Special Stage ring:*/
		movew	x_pos(%a0),(Saved_X_pos)
		movew	y_pos(%a0),(Saved_Y_pos)
		movew	art_tile(%a0),(Saved_art_tile)
		movew	top_solid_bit(%a0),(Saved_solid_bits)

Sonic_Init_Continued:
		moveb	#0,flips_remaining(%a0)
		moveb	#4,flip_speed(%a0)
		moveb	#0,(Super_Sonic_Knux_flag)
		moveb	#0x1E,air_left(%a0)
		subiw	#0x20,x_pos(%a0)
		addiw	#4,y_pos(%a0)
		bsrw	Reset_Player_Position_Array
		addiw	#0x20,x_pos(%a0)
		subiw	#4,y_pos(%a0)
		rts

