/* Normal state for Sonic*/
/* --------------------------------------------------------------------------- */

Sonic_Control:	/* Routine 2*/
		tstw	(Debug_mode_flag)		/* is debug cheat enabled?*/
		beqs	loc_10BF0			/* .if not, branch*/
		bclr	#button_A,(Ctrl_1_pressed)	/* is button A pressed?*/
		beqs	loc_10BCE			/* .if not, branch*/
		eorib	#1,(Reverse_gravity_flag)	/* toggle reverse gravity*/

loc_10BCE:
		btst	#button_B,(Ctrl_1_pressed)	/* is button B pressed?*/
		beqs	loc_10BF0			/* .if not, branch*/
		movew	#1,(Debug_placement_mode)	/* change Sonic into a ring/item*/
		clrb	(Ctrl_1_locked)		/* unlock control*/
		btst	#button_C,(Ctrl_1_held)	/* was button C held before pressing B?*/
		beqs	locret_10BEE			/* .if not, branch*/
		movew	#2,(Debug_placement_mode)	/* enter animation cycle mode*/

locret_10BEE:
		rts
/* --------------------------------------------------------------------------- */

loc_10BF0:
		tstb	(Ctrl_1_locked)		/* are controls locked?*/
		bnes	loc_10BFC			/* .if yes, branch*/
		movew	(Ctrl_1),(Ctrl_1_logical)	/* copy new held buttons, to enable joypad control*/

loc_10BFC:
		btst	#0,object_control(%a0)	/* is Sonic interacting with another object that holds him in place or controls his movement somehow?*/
		beqs	loc_10C0C		/* .if yes, branch to skip Sonic's control*/
		moveb	#0,double_jump_flag(%a0)	/* enable double jump*/
		bras	loc_10C26
/* --------------------------------------------------------------------------- */

loc_10C0C:
		moveml	%a4-%a6,-(%sp)
		moveq	#0,%d0
		moveb	status(%a0),%d0
		andiw	#6,%d0
		movew	Sonic_Modes(%pc,%d0:w),%d1
		jsr	Sonic_Modes(%pc,%d1:w)	/* run Sonic's movement control code*/
		moveml	(%sp)+,%a4-%a6

loc_10C26:
		cmpiw	#-0x100,(Camera_min_Y_pos)	/* is vertical wrapping enabled?*/
		bnes	loc_10C36			/* .if not, branch*/
		movew	(Screen_Y_wrap_value),%d0
		andw	%d0,y_pos(%a0)			/* perform wrapping of Sonic's y position*/

loc_10C36:
		bsrs	Sonic_Display
		bsrw	SonicKnux_SuperHyper
		bsrw	Sonic_RecordPos
		bsrw	Sonic_Water
		moveb	(Primary_Angle),next_tilt(%a0)
		moveb	(Secondary_Angle),tilt(%a0)
		tstb	(WindTunnel_flag)
		beqs	loc_10C62
		tstb	anim(%a0)
		bnes	loc_10C62
		moveb	prev_anim(%a0),anim(%a0)

loc_10C62:
		btst	#1,object_control(%a0)
		bnes	loc_10C7E
		bsrw	Animate_Sonic
		tstb	(Reverse_gravity_flag)
