/* secondary states under state Sonic_Control*/
Sonic_Modes:	.word Sonic_MdNormal-Sonic_Modes
		.word Sonic_MdAir-Sonic_Modes
		.word Sonic_MdRoll-Sonic_Modes
		.word Sonic_MdJump-Sonic_Modes

/* =============== S U B R O U T I N E =======================================*/


Sonic_Display:
		moveb	invulnerability_timer(%a0),%d0
		beqs	loc_10CA6
		subqb	#1,invulnerability_timer(%a0)
		lsrb	#3,%d0
		bccs	Sonic_ChkInvin

loc_10CA6:
		jsr	(Draw_Sprite)

Sonic_ChkInvin:	/* Checks .if invincibility has expired and disables it .if it has.*/
		btst	#Status_Invincible,status_secondary(%a0)
		beqs	Sonic_ChkShoes
		tstb	invincibility_timer(%a0)
		beqs	Sonic_ChkShoes	/* If there wasn't any time left, that means we're in Super/Hyper mode*/
		moveb	(Level_frame_counter+1),%d0
		andib	#7,%d0
		bnes	Sonic_ChkShoes
		subqb	#1,invincibility_timer(%a0)	/* reduce invincibility_timer only on every 8th frame*/
		bnes	Sonic_ChkShoes			/* .if time is still left, branch*/
		tstb	(Boss_flag)		/* Don't change music .if in a boss fight*/
		bnes	Sonic_RmvInvin
		cmpib	#0xC,air_left(%a0)	/* Don't change music .if drowning*/
		blos	Sonic_RmvInvin
		movew	(Level_music),%d0
		jsr	(Play_Sound)		/* stop playing invincibility theme and resume normal level music*/

Sonic_RmvInvin:
		bclr	#Status_Invincible,status_secondary(%a0)

Sonic_ChkShoes:	/* Checks .if Speed Shoes have expired and disables them .if they have.*/
		btst	#Status_SpeedShoes,status_secondary(%a0)	/* does Sonic have speed shoes?*/
		beqs	Sonic_ExitChk				/* .if so, branch*/
		tstb	speed_shoes_timer(%a0)
		beqs	Sonic_ExitChk
		moveb	(Level_frame_counter+1),%d0
		andib	#7,%d0
		bnes	Sonic_ExitChk
		subqb	#1,speed_shoes_timer(%a0)	/* reduce speed_shoes_timer only on every 8th frame*/
		bnes	Sonic_ExitChk
		tstw	(Competition_mode)		/* is this Competition mode?*/
		bnes	Sonic_ChkShoesCompetition	/* .if so, branch*/
		movew	#0x600,Max_speed-Max_speed(%a4)		/* set Max_speed*/
		movew	#0xC,Acceleration-Max_speed(%a4)		/* set Acceleration*/
		movew	#0x80,Deceleration-Max_speed(%a4)		/* set Deceleration*/
		tstb	(Super_Sonic_Knux_flag)
		beqs	loc_10D32	/* .if Super/Hyper, set different values*/
		movew	#0xA00,Max_speed-Max_speed(%a4)		/* set Max_speed*/
		movew	#0x30,Acceleration-Max_speed(%a4)		/* set Acceleration*/
		movew	#0x100,Deceleration-Max_speed(%a4)	/* set Deceleration*/

loc_10D32:
		bclr	#Status_SpeedShoes,status_secondary(%a0)
		moveq	#0,%d0		/* Slow down tempo*/
		jmp	(Change_Music_Tempo)
/* --------------------------------------------------------------------------- */

Sonic_ExitChk:
		rts
/* --------------------------------------------------------------------------- */

Sonic_ChkShoesCompetition:
		lea	(Character_Speeds),%a1
		moveq	#0,%d0
		moveb	character_id(%a0),%d0
		lslw	#3,%d0
		lea	(%a1,%d0:w),%a1
		movew	(%a1)+,(%a4)
		movew	(%a1)+,2(%a4)
		movew	(%a1)+,4(%a4)
		bclr	#Status_SpeedShoes,status_secondary(%a0)
		rts
/* End of function Sonic_Display*/

