Sonic_Water:
		tstb	(Water_flag)	/* does level have water?*/
		bnes	Sonic_InWater	/* .if yes, branch*/

locret_10E2C:
		rts
/* --------------------------------------------------------------------------- */

Sonic_InWater:
		movew	(Water_level),%d0
		cmpw	y_pos(%a0),%d0	/* is Sonic above the water?*/
		bges	Sonic_OutWater	/* .if yes, branch*/

		bset	#Status_Underwater,status(%a0)	/* set underwater flag*/
		bnes	locret_10E2C	/* .if already underwater, branch*/

		addqb	#1,(Water_entered_counter)
		moveal	%a0,%a1
		bsrw	Player_ResetAirTimer
		movel	#Obj_Air_CountDown,(Breathing_bubbles)	/* load Sonic's breathing bubbles*/
		moveb	#0x81,(Breathing_bubbles+subtype)
		movel	%a0,(Breathing_bubbles+0x40)
		movew	#0x300,Max_speed-Max_speed(%a4)
		movew	#6,Acceleration-Max_speed(%a4)
		movew	#0x40,Deceleration-Max_speed(%a4)
		tstb	(Super_Sonic_Knux_flag)
		beqs	loc_10E82		/* .if Super/Hyper, set different values*/
		movew	#0x500,Max_speed-Max_speed(%a4)
		movew	#0x18,Acceleration-Max_speed(%a4)
		movew	#0x80,Deceleration-Max_speed(%a4)

loc_10E82:
		tstb	object_control(%a0)
		bnes	locret_10E2C
		asr	x_vel(%a0)
		asr	y_vel(%a0)		/* memory operands can only be shifted one bit at a time*/
		asr	y_vel(%a0)
		beqs	locret_10E2C
		movew	#0x100,anim(%a6)		/* splash animation, write 1 to anim and clear prev_anim*/
		movew	#sfx_Splash,%d0
		jmp	(Play_Sound_2)
/* --------------------------------------------------------------------------- */

Sonic_OutWater:
		bclr	#Status_Underwater,status(%a0)	/* unset underwater flag*/
		beqw	locret_10E2C			/* .if already above water, branch*/
		addqb	#1,(Water_entered_counter)

		moveal	%a0,%a1
		bsrw	Player_ResetAirTimer
		movew	#0x600,Max_speed-Max_speed(%a4)
		movew	#0xC,Acceleration-Max_speed(%a4)
		movew	#0x80,Deceleration-Max_speed(%a4)
		tstb	(Super_Sonic_Knux_flag)
		beqs	loc_10EE0	/* .if Super/Hyper, set different values*/
		movew	#0xA00,Max_speed-Max_speed(%a4)
		movew	#0x30,Acceleration-Max_speed(%a4)
		movew	#0x100,Deceleration-Max_speed(%a4)

loc_10EE0:
		cmpib	#4,routine(%a0)	/* is Sonic falling back from getting hurt?*/
		beqs	loc_10EFC	/* .if yes, branch*/
		tstb	object_control(%a0)
		bnes	loc_10EFC
		movew	y_vel(%a0),%d0
		cmpiw	#-0x400,%d0
		blts	loc_10EFC
		asl	y_vel(%a0)

loc_10EFC:
		cmpib	#0x1C,anim(%a0)	/* is Sonic in his 'blank' animation*/
		beqw	locret_10E2C	/* .if so, branch*/
		tstw	y_vel(%a0)
		beqw	locret_10E2C
		movew	#0x100,anim(%a6)	/* splash animation, write 1 to anim and clear prev_anim*/
		cmpiw	#-0x1000,y_vel(%a0)
		bgts	loc_10F22
		movew	#-0x1000,y_vel(%a0)	/* limit upward y velocity exiting the water*/

loc_10F22:
		movew	#sfx_Splash,%d0
		jmp	(Play_Sound_2)
/* End of function Sonic_Water*/

