/* =============== S U B R O U T I N E =======================================*/


Sonic_Move:
		movew	Max_speed-Max_speed(%a4),%d6	/* set Max_speed*/
		movew	Acceleration-Max_speed(%a4),%d5	/* set Acceleration*/
		movew	Deceleration-Max_speed(%a4),%d4	/* set Deceleration*/
		tstb	status_secondary(%a0)	/* is bit 7 set? (Infinite inertia)*/
		bmiw	loc_11332		/* .if so, branch*/
		tstw	move_lock(%a0)
		bnew	loc_112EA
		btst	#button_left,(Ctrl_1_logical)	/* is left being pressed?*/
		beqs	Sonic_NotLeft			/* .if not, branch*/
		bsrw	sub_113F6

Sonic_NotLeft:
		btst	#button_right,(Ctrl_1_logical)	/* is right being pressed?*/
		beqs	Sonic_NotRight				/* .if not, branch*/
		bsrw	sub_11482

Sonic_NotRight:
		moveb	angle(%a0),%d0
		addib	#0x20,%d0
		andib	#0xC0,%d0		/* is Sonic on a slope?*/
		bnew	loc_112EA	/* .if yes, branch*/
		tstw	ground_vel(%a0)	/* is Sonic moving?*/
		bnew	loc_112EA	/* .if yes, branch*/
		bclr	#Status_Push,status(%a0)
		moveb	#5,anim(%a0)	/* use standing animation*/
		btst	#Status_OnObj,status(%a0)
		beqw	Sonic_Balance
		moveaw	interact(%a0),%a1	/* load interacting object's RAM space*/
		tstb	status(%a1)	/* is status bit 7 set? (unused?)*/
		bmiw	loc_11276	/* .if so, branch*/

		/* Calculations to determine where on the object Sonic is, and make him balance accordingly*/
		moveq	#0,%d1			/* Clear %d1*/
		moveb	width_pixels(%a1),%d1	/* Load interacting object's width into %d1*/
		movew	%d1,%d2			/* Move to %d2 for seperate calculations*/
		addw	%d2,%d2			/* Double object width, converting it to X pos' units of measurement*/
		subqw	#2,%d2			/* Subtract 2: This is the margin for 'on edge'*/
		addw	x_pos(%a0),%d1		/* Add Sonic's X position to object width*/
		subw	x_pos(%a1),%d1		/* Subtract object's X position from width+Sonic's X pos, giving you Sonic's distance from left edge of object*/
		tstb	(Super_Sonic_Knux_flag)	/* is Sonic Super/Hyper?*/
		bnew	SuperSonic_Balance		/* .if so, branch*/
		cmpiw	#2,%d1		/* is Sonic within two units of object's left edge?*/
		blts	Sonic_BalanceOnObjLeft	/* .if so, branch*/
		cmpw	%d2,%d1
		bges	Sonic_BalanceOnObjRight	/* .if Sonic is within two units of object's right edge, branch (Realistically, it checks this, and BEYOND the right edge of the object)*/
		braw	loc_11276	/* .if Sonic is more than 2 units from both edges, branch*/
/* --------------------------------------------------------------------------- */

SuperSonic_Balance:
		cmpiw	#2,%d1		/* is Sonic within two units of object's left edge?*/
		bltw	loc_11268	/* .if so, branch*/
		cmpw	%d2,%d1
		bgew	loc_11258	/* .if Sonic is within two units of object's right edge, branch (Realistically, it checks this, and BEYOND the right edge of the object)*/
		braw	loc_11276	/* .if Sonic is more than 2 units from both edges, branch*/
/* --------------------------------------------------------------------------- */
/* balancing checks for when you're on the right edge of an object*/

Sonic_BalanceOnObjRight:
		btst	#Status_Facing,status(%a0)	/* is Sonic facing right?*/
		bnes	loc_11128			/* .if so, branch*/
		moveb	#6,anim(%a0)	/* Balance animation 1*/
		addqw	#6,%d2		/* extend balance range*/
		cmpw	%d2,%d1		/* is Sonic within (two units before and) four units past the right edge?*/
		bltw	loc_112EA	/* .if so branch*/
		moveb	#0xC,anim(%a0)	/* .if REALLY close to the edge, use different animation (Balance animation 2)*/
		braw	loc_112EA

loc_11128:
		/* Somewhat dummied out/redundant code from Sonic 2*/
		/* Originally, Sonic displayed different animations for each direction faced*/
		/* But now, Sonic uses only the one set of animations no matter what, making the check pointless, and the code redundant*/
		bclr	#Status_Facing,status(%a0)
		moveb	#6,anim(%a0)	/* Balance animation 1*/
		addqw	#6,%d2		/* extend balance range*/
		cmpw	%d2,%d1		/* is Sonic within (two units before and) four units past the right edge?*/
		bltw	loc_112EA	/* .if so branch*/
		moveb	#0xC,anim(%a0)	/* .if REALLY close to the edge, use different animation (Balance animation 2)*/
		braw	loc_112EA
/* --------------------------------------------------------------------------- */

Sonic_BalanceOnObjLeft:
		btst	#Status_Facing,status(%a0)	/* is Sonic facing right?*/
		beqs	loc_11166
		moveb	#6,anim(%a0)	/* Balance animation 1*/
		cmpiw	#-4,%d1		/* is Sonic within (two units before and) four units past the left edge?*/
		bgew	loc_112EA	/* .if so branch (instruction signed to match)*/
		moveb	#0xC,anim(%a0)	/* .if REALLY close to the edge, use different animation (Balance animation 2)*/
		braw	loc_112EA

loc_11166:
