/* --------------------------------------------------------------------------- */
/* Subroutine for moving Sonic left or right when he's in the air*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Sonic_ChgJumpDir:
		movew	Max_speed-Max_speed(%a4),%d6
		movew	Acceleration-Max_speed(%a4),%d5
		aslw	#1,%d5
		/* Good riddance!*/
		/* btst	#Status_RollJump,status(%a0)		// did Sonic jump from rolling?*/
		/* bnes	Sonic_Jump_ResetScr	// .if yes, branch to skip midair control*/
		movew	x_vel(%a0),%d0
		btst	#button_left,(Ctrl_1_logical)
		beqs	loc_11682	/* .if not holding left, branch*/

		bset	#Status_Facing,status(%a0)
		subw	%d5,%d0	/* add acceleration to the left*/
		movew	%d6,%d1
		negw	%d1
		cmpw	%d1,%d0	/* compare new speed with top speed*/
		bgts	loc_11682	/* .if new speed is less than the maximum, branch*/
		addw	%d5,%d0		/* remove this frame's acceleration change*/
		cmpw	%d1,%d0		/* compare speed with top speed*/
		bles	loc_11682	/* .if speed was already greater than the maximum, branch*/
		movew	%d1,%d0

loc_11682:
		btst	#button_right,(Ctrl_1_logical)
		beqs	loc_1169E	/* .if not holding right, branch*/

		bclr	#Status_Facing,status(%a0)
		addw	%d5,%d0	/* accelerate right in the air*/
		cmpw	%d6,%d0	/* compare new speed with top speed*/
		blts	loc_1169E	/* .if new speed is less than the maximum, branch*/
		subw	%d5,%d0		/* remove this frame's acceleration change*/
		cmpw	%d6,%d0		/* compare speed with top speed*/
		bges	loc_1169E	/* .if speed was already greater than the maximum, branch*/
		movew	%d6,%d0

loc_1169E:
		movew	%d0,x_vel(%a0)

Sonic_Jump_ResetScr:
		cmpiw	#0x60,(%a5)	/* is screen in its default position?*/
		beqs	Sonic_JumpPeakDecelerate	/* .if yes, branch*/
		bhss	loc_116AC	/* depending on the sign of the difference,*/
		addqw	#4,(%a5)		/* either add 2*/

loc_116AC:
		subqw	#2,(%a5)		/* or subtract 2*/

Sonic_JumpPeakDecelerate:
		cmpiw	#-0x400,y_vel(%a0)	/* is Sonic moving faster than -0x400 upwards?*/
		blos	locret_116DC		/* .if yes, return*/
		movew	x_vel(%a0),%d0
		movew	%d0,%d1
		asrw	#5,%d1		/* %d1 = x_velocity / 32*/
		beqs	locret_116DC	/* return .if %d1 is 0*/
		bmis	Sonic_JumpPeakDecelerateLeft	/* branch .if moving left*/

		subw	%d1,%d0	/* reduce x velocity by %d1*/
		bccs	loc_116CA
		movew	#0,%d0

loc_116CA:
		movew	%d0,x_vel(%a0)
		rts
/* --------------------------------------------------------------------------- */

Sonic_JumpPeakDecelerateLeft:
		subw	%d1,%d0	/* reduce x velocity by %d1*/
		bcss	loc_116D8
		movew	#0,%d0

loc_116D8:
		movew	%d0,x_vel(%a0)

locret_116DC:
		rts
/* End of function Sonic_ChgJumpDir*/


/* --------------------------------------------------------------------------- */
/* Subroutine to prevent Sonic from leaving the boundaries of a level*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Player_LevelBound:
		movel	x_pos(%a0),%d1
		movew	x_vel(%a0),%d0
		extl	%d0
		asll	#8,%d0
		addl	%d0,%d1
		swap	%d1
		movew	(Camera_min_X_pos),%d0
		addiw	#0x10,%d0
		cmpw	%d1,%d0			/* has Sonic touched the left boundary?*/
		bhis	Player_Boundary_Sides	/* .if yes, branch*/
		movew	(Camera_max_X_pos),%d0
		addiw	#0x128,%d0
		cmpw	%d1,%d0
		blos	Player_Boundary_Sides

Player_Boundary_CheckBottom:
		tstb	(Disable_death_plane)
		bnes	locret_11720
		tstb	(Reverse_gravity_flag)
		bnes	loc_11722
		movew	(Camera_max_Y_pos),%d0
		addiw	#0xE0,%d0
		cmpw	y_pos(%a0),%d0		/* has Sonic touched the bottom boundary?*/
		blts	Player_Boundary_Bottom	/* .if yes, branch*/

locret_11720:
		rts
/* --------------------------------------------------------------------------- */

loc_11722:
		movew	(Camera_min_Y_pos),%d0
		cmpw	y_pos(%a0),%d0
		blts	locret_11720

Player_Boundary_Bottom:
		jmp	(Kill_Character)
/* --------------------------------------------------------------------------- */

Player_Boundary_Sides:
		movew	%d0,x_pos(%a0)
		movew	#0,2+x_pos(%a0) /* subpixel x*/
		movew	#0,x_vel(%a0)
		movew	#0,ground_vel(%a0)
		bras	Player_Boundary_CheckBottom
/* End of function Player_LevelBound*/


/* =============== S U B R O U T I N E =======================================*/


SonicKnux_Roll:
		tstb	status_secondary(%a0)
		bmis	locret_1177E
		moveb	(Ctrl_1_logical),%d0
		andib	#button_left_mask+button_right_mask,%d0 /* is left/right being pressed?*/
		bnes	locret_1177E	/* .if yes, branch*/
		btst	#button_down,(Ctrl_1_logical) /* is down being pressed?*/
		beqs	Player_ChkWalk			/* .if not, branch*/
		movew	ground_vel(%a0),%d0
		bpls	loc_1176A
		negw	%d0

loc_1176A:
		cmpiw	#0x100,%d0		/* is Sonic moving at 0x100 speed or faster?*/
		bhss	Player_ChkRoll		/* .if so, branch*/
		btst	#Status_OnObj,status(%a0)
		bnes	locret_1177E
		moveb	#8,anim(%a0)	/* enter ducking animation*/

locret_1177E:
		rts
/* --------------------------------------------------------------------------- */

Player_ChkWalk:
		cmpib	#8,anim(%a0)	/* is Sonic ducking?*/
		bnes	locret_1177E
		moveb	#0,anim(%a0)	/* .if so, enter walking animation*/
		rts
/* --------------------------------------------------------------------------- */

Player_ChkRoll:
		btst	#Status_Roll,status(%a0)	/* is Sonic already rolling?*/
		beqs	Player_DoRoll	/* .if not, branch*/
		rts
/* --------------------------------------------------------------------------- */

Player_DoRoll:
		bset	#Status_Roll,status(%a0)
		moveb	#0xE,y_radius(%a0)
		moveb	#7,x_radius(%a0)
		moveb	#2,anim(%a0)	/* enter roll animation*/
		addqw	#5,y_pos(%a0)
		tstb	(Reverse_gravity_flag)
		beqs	loc_117C2
		subiw	#0xA,y_pos(%a0)

loc_117C2:
		movew	#sfx_Roll,%d0
		jsr	(Play_Sound_2)
		tstw	ground_vel(%a0)
		bnes	locret_117D8
		movew	#0x200,ground_vel(%a0)

locret_117D8:
		rts
/* End of function SonicKnux_Roll*/


/* --------------------------------------------------------------------------- */
/* Subroutine allowing Sonic to jump*/
/* --------------------------------------------------------------------------- */

/* =============== S U B R O U T I N E =======================================*/


Sonic_Jump:
		moveb	(Ctrl_1_pressed_logical),%d0
		andib	#button_B_mask+button_C_mask+button_A_mask,%d0 /* is A, B or C pressed?*/
		beqw	locret_118B2	/* .if not, return*/
		btst 	#Status_InAir,status(%a0)
		bnes 	.notInAir
		/* TODO: figure out how to get Tails to airlift Sonic/Knuckles*/
.notInAir:
		moveq	#0,%d0
		moveb	angle(%a0),%d0
		tstb	(Reverse_gravity_flag)
		beqs	loc_117FC
		addib	#0x40,%d0
		negb	%d0
		subib	#0x40,%d0

loc_117FC:
		addib	#-0x80,%d0
		moveml	%a4-%a6,-(%sp)
		bsrw	CalcRoomOverHead
		moveml	(%sp)+,%a4-%a6
		cmpiw	#6,%d1			/* does Sonic have enough room to jump?*/
		bltw	locret_118B2		/* .if not, branch*/
		movew	#0x680,%d2
		tstb	(Super_Sonic_Knux_flag)
		beqs	loc_11822
		movew	#0x800,%d2	/* set higher jump speed .if super*/

loc_11822:
		btst	#Status_Underwater,status(%a0)	/* Test .if underwater*/
		beqs	loc_1182E
		movew	#0x380,%d2	/* set lower jump speed .if under*/

loc_1182E:
		moveq	#0,%d0
		moveb	angle(%a0),%d0
		subib	#0x40,%d0
		jsr	(GetSineCosine)
		mulsw	%d2,%d1
		asrl	#8,%d1
		addw	%d1,x_vel(%a0)	/* make Sonic jump (in X... this adds nothing on level ground)*/
		mulsw	%d2,%d0
		asrl	#8,%d0
		addw	%d0,y_vel(%a0)	/* make Sonic jump (in Y)*/
		bset	#Status_InAir,status(%a0)
		bclr	#Status_Push,status(%a0)
		addql	#4,%sp
		moveb	#1,jumping(%a0)
		clrb	stick_to_convex(%a0)
		movew	#sfx_Jump,%d0
		jsr	(Play_Sound_2)
		moveb	default_y_radius(%a0),y_radius(%a0)
		moveb	default_x_radius(%a0),x_radius(%a0)
		btst	#Status_Roll,status(%a0)
		bnes	Sonic_RollJump
		moveb	#0xE,y_radius(%a0)
		moveb	#7,x_radius(%a0)
		moveb	#2,anim(%a0)	/* use "jumping" animation*/
		bset	#Status_Roll,status(%a0)
		moveb	y_radius(%a0),%d0
		subb	default_y_radius(%a0),%d0
		extw	%d0
		tstb	(Reverse_gravity_flag)
		beqs	loc_118AE
		negw	%d0

loc_118AE:
		subw	%d0,y_pos(%a0)

locret_118B2:
		rts
/* --------------------------------------------------------------------------- */

Sonic_RollJump:
		bset	#Status_RollJump,status(%a0)	/* set the rolling+jumping flag*/
		rts
/* End of function Sonic_Jump*/


/* =============== S U B R O U T I N E =======================================*/

Sonic_JumpHeight:
		tstb	jumping(%a0)	/* is Sonic jumping?*/
		beqs	Sonic_UpVelCap	/* .if not, branch*/

		movew	#-0x400,%d1
		btst	#Status_Underwater,status(%a0)	/* is Sonic underwater?*/
		beqs	loc_118D2			/* .if not, branch*/
		movew	#-0x200,%d1			/* Underwater-specific*/

loc_118D2:
		cmpw	y_vel(%a0),%d1		/* is y speed greater than 4? (2 .if underwater)*/
		blew	Sonic_InstaAndShieldMoves		/* .if not, branch*/
		moveb	(Ctrl_1_logical),%d0
		andib	#0x70,%d0			/* are buttons A, B or C being pressed?*/
		bnes	locret_118E8		/* .if yes, branch*/
		movew	%d1,y_vel(%a0)		/* cap jump height*/

locret_118E8:
		rts
/* --------------------------------------------------------------------------- */

Sonic_UpVelCap:
		tstb	spin_dash_flag(%a0)	/* is Sonic charging his spin dash?*/
		bnes	locret_118FE		/* .if yes, branch*/
		cmpiw	#-0xFC0,y_vel(%a0)	/* is Sonic's Y speed faster (less than) than -15.75 (-0xFC0)?*/
		bges	locret_118FE		/* .if not, branch*/
		movew	#-0xFC0,y_vel(%a0)	/* cap upward speed*/

locret_118FE:
		rts
/* --------------------------------------------------------------------------- */

Sonic_InstaAndShieldMoves:
		tstb	double_jump_flag(%a0)		/* is Sonic currently performing a double jump?*/
		bnew	locret_11A14			/* .if yes, branch*/
		moveb	(Ctrl_1_pressed_logical),%d0
		andib	#0x70,%d0				/* are buttons A, B, or C being pressed?*/
		beqw	locret_11A14			/* .if not, branch*/
		bclr	#Status_RollJump,status(%a0)
		tstb	(Super_Sonic_Knux_flag)	/* check Super-state*/
		beqs	Sonic_FireShield		/* .if not in a super-state, branch*/
		bmiw	Sonic_HyperDash			/* .if Hyper, branch*/
		moveb	#1,double_jump_flag(%a0)
		rts
/* --------------------------------------------------------------------------- */

Sonic_FireShield:
		btst	#Status_Invincible,status_secondary(%a0)	/* first, does Sonic have invincibility?*/
		bnew	locret_11A14				/* .if yes, branch*/
		btst	#Status_FireShield,status_secondary(%a0)	/* does Sonic have a Fire Shield?*/
		beqs	Sonic_LightningShield			/* .if not, branch*/
		moveb	#1,(Shield+anim)
		moveb	#1,double_jump_flag(%a0)
		movew	#0x800,%d0
		btst	#Status_Facing,status(%a0)		/* is Sonic facing left?*/
		beqs	loc_11958				/* .if not, branch*/
		negw	%d0					/* reverse speed value, moving Sonic left*/

loc_11958:
		movew	%d0,x_vel(%a0)		/* apply velocity...*/
		movew	%d0,ground_vel(%a0)	/* ...both ground and air*/
		movew	#0,y_vel(%a0)		/* kill y-velocity*/
		movew	#0x2000,(H_scroll_frame_offset)
		bsrw	Reset_Player_Position_Array
		movew	#sfx_FireAttack,%d0
		jmp	(Play_Sound_2)
/* --------------------------------------------------------------------------- */

Sonic_LightningShield:
		btst	#Status_LtngShield,status_secondary(%a0)	/* does Sonic have a Lightning Shield?*/
		beqs	Sonic_BubbleShield			/* .if not, branch*/
		moveb	#1,(Shield+anim)
		moveb	#1,double_jump_flag(%a0)
		movew	#-0x580,y_vel(%a0)	/* bounce Sonic up, creating the double jump effect*/
		clrb	jumping(%a0)
		movew	#sfx_ElectricAttack,%d0
		jmp	(Play_Sound_2)
/* --------------------------------------------------------------------------- */

Sonic_BubbleShield:
		btst	#Status_BublShield,status_secondary(%a0)	/* does Sonic have a Bubble Shield*/
		beqs	Sonic_CheckTransform			/* .if not, branch*/
		moveb	#1,(Shield+anim)
		moveb	#1,double_jump_flag(%a0)
		movew	#0,x_vel(%a0)		/* halt horizontal speed...*/
		movew	#0,ground_vel(%a0)	/* ...both ground and air*/
		movew	#0x800,y_vel(%a0)		/* force Sonic down*/
		movew	#sfx_BubbleAttack,%d0
		jmp	(Play_Sound_2)
/* --------------------------------------------------------------------------- */
/* Code that transforms Sonic into Super/Hyper Sonic*/
/* .if he has enough rings and emeralds*/
/* --------------------------------------------------------------------------- */

Sonic_CheckTransform:
		cmpib	#7,(Super_emerald_count)	/* does Sonic have all 7 Super Emeralds?*/
		bhss	loc_119E8			/* .if yes, branch*/
		cmpib	#7,(Emerald_count)		/* does Sonic have all 7 Chaos Emeralds?*/
		blos	Sonic_InstaShield		/* .if not, branch*/
		tstb	(Emeralds_converted_flag)
		bnes	Sonic_InstaShield

loc_119E8:
		cmpiw	#50,(Ring_count)	/* does Sonic have at least 50 rings?*/
		blos	Sonic_InstaShield	/* .if not, perform Insta-Shield*/
		tstb	(Update_HUD_timer)
		bnes	Sonic_Transform

Sonic_InstaShield:
		btst	#Status_Shield,status_secondary(%a0)	/* does Sonic have an S2 shield (The Elementals were already filtered out at this point)?*/
		bnes	locret_11A14				/* .if yes, branch*/
		moveb	#1,(Shield+anim)
		moveb	#1,double_jump_flag(%a0)
		movew	#sfx_InstaAttack,%d0
		jmp	(Play_Sound_2)
/* --------------------------------------------------------------------------- */

locret_11A14:
		rts
/* --------------------------------------------------------------------------- */

Sonic_Transform:
		moveb	#1,(Super_palette_status)	/* set Super/Hyper palette status to 'fading'*/
		moveb	#0xF,(Palette_timer)
		movew	#60,(Super_frame_count)
		movel	#Map_SuperSonic,mappings(%a0)
		moveb	#0x81,object_control(%a0)
		moveb	#0x1F,anim(%a0)				/* enter 'transformation' animation*/
		cmpib	#7,(Super_emerald_count)		/* does Sonic have all 7 Super Emeralds?*/
		blos	.super0					/* .if not, turn Super*/

		moveb	#-1,(Super_Sonic_Knux_flag)		/* set flag to Hyper Sonic*/
		movel	#Obj_HyperSonic_Stars,(Invincibility_stars)	/* load Hyper Stars object*/
		movel	#Obj_HyperSonicKnux_Trail,(Super_stars)	/* load After-Images object*/
		bras	.continued0
/* --------------------------------------------------------------------------- */

	.super0:
		moveb	#1,(Super_Sonic_Knux_flag)		/* set flag to Super Sonic*/
		movel	#Obj_SuperSonicKnux_Stars,(Super_stars)	/* load Super Stars object*/

	.continued0:
		movew	#0xA00,Max_speed-Max_speed(%a4)
		movew	#0x30,Acceleration-Max_speed(%a4)
		movew	#0x100,Deceleration-Max_speed(%a4)
		moveb	#0,invincibility_timer(%a0)
		bset	#Status_Invincible,status_secondary(%a0)
		moveb	#sfx_SuperTransform,%d0
		jsr	(Play_Sound_2)
		moveb	#mus_Super,%d0		/* play invincibility theme*/
		jmp	(Play_Sound)
/* --------------------------------------------------------------------------- */

Sonic_HyperDash:
		bsrw	HyperAttackTouchResponse
		movew	#0x2000,(H_scroll_frame_offset)
		bsrw	Reset_Player_Position_Array
		moveb	#1,double_jump_flag(%a0)
		moveb	#1,(Invincibility_stars+anim)	/* This causes the screen flash, and sparks to come out of Sonic*/
		moveb	#sfx_Dash,%d0
		jsr	(Play_Sound_2)
		moveb	(Ctrl_1_logical),%d0
		andiw	#button_up_mask+button_down_mask+button_left_mask+button_right_mask,%d0	/* Get D-pad input*/
		beqs	.noInput
		/* Any values totalling 0xB or above are produced by holding*/
		/* both opposing directions on the D-pad, which is invalid*/
		cmpib	#0xB,%d0
		bhss	.noInput
		lslw	#2,%d0
		lea	Sonic_HyperDash_Velocities-4(%pc,%d0:w),%a1
		movew	(%a1)+,%d0
		movew	%d0,x_vel(%a0)
		movew	%d0,ground_vel(%a0)
		movew	(%a1)+,%d0
		movew	%d0,y_vel(%a0)
		rts
/* --------------------------------------------------------------------------- */

	.noInput:
		/* If there's no directional input, we just dash forward*/
		movew	#0x800,%d0	/* Go right...*/
		btst	#Status_Facing,status(%a0)	/* ...unless Sonic is facing left...*/
		beqs	.applySpeeds
		negw	%d0		/* ...in which case, go left*/

	.applySpeeds:
		movew	%d0,x_vel(%a0)
		movew	%d0,ground_vel(%a0)
		movew	#0,y_vel(%a0)
		rts
/* End of function Sonic_JumpHeight*/

/* --------------------------------------------------------------------------- */
Sonic_HyperDash_Velocities:
		.word      0, -0x800	/* up*/
		.word      0,  0x800	/* down*/
		.word      0,     0	/* up - down (shouldn't happen)*/
		.word  -0x800,     0	/* left*/
		.word  -0x800, -0x800	/* left - up*/
		.word  -0x800,  0x800	/* left - down*/
		.word      0,     0	/* left - up - down (shouldn't happen)*/
		.word   0x800,     0	/* right*/
		.word   0x800, -0x800	/* right - up*/
		.word   0x800,  0x800	/* right - down*/
		/* Everything after this would be bad button combinations*/
/* --------------------------------------------------------------------------- */

Tails_Super:
		tstb	(Super_Tails_flag)
		beqw	.return6
		bras	.continued1

/* =============== S U B R O U T I N E =======================================*/


SonicKnux_SuperHyper:
		tstb	(Super_Sonic_Knux_flag)
		beqw	.return6		/* If not Super/Hyper, return*/

	.continued1:
		tstb	(Update_HUD_timer)	/* Level over?*/
		beqs	.revertToNormal
		subqw	#1,(Super_frame_count)
		bplw	.return6			/* This should be a 'bhi'// currently counts down 61 frames*/
		movew	#60,(Super_frame_count)
		tstw	(Ring_count)
		beqs	.revertToNormal	/* If rings depleted, return to normal*/
		/* This checks .if the ring counter needs to be blanked*/
		/* for example, this ticks '10' down to ' 9' instead of '19' (yes, this does happen)*/
		orib	#1,(Update_HUD_ring_count)	/* Update ring counter*/
		cmpiw	#1,(Ring_count)
		beqs	.resetHUD
		cmpiw	#10,(Ring_count)
		beqs	.resetHUD
		cmpiw	#100,(Ring_count)
		bnes	.updateHUD

	.resetHUD:
		orib	#0x80,(Update_HUD_ring_count)	/* Re-init ring counter*/

	.updateHUD:
		subqw	#1,(Ring_count)
		bnes	.return6	/* If rings aren't depleted, we're done here*/
		/* If rings depleted, return to normal*/

	.revertToNormal:
		moveb	#2,(Super_palette_status)
		movew	#0x1E,(Palette_frame)
		moveb	#0,(Super_Sonic_Knux_flag)
		moveb	#0,(Super_Tails_flag)
		moveb	#-1,(Player_prev_frame)
		tstb	character_id(%a0)	/* Is this Sonic?*/
		bnes	.notSonic
		movel	#Map_Sonic,mappings(%a0)	/* If so, load Sonic's normal mappings (was using Super/Hyper mappings)*/

	.notSonic:
		moveb	#1,prev_anim(%a0)
		moveb	#1,invincibility_timer(%a0)
		movew	#0x600,Max_speed-Max_speed(%a4)
		movew	#0xC,Acceleration-Max_speed(%a4)
		movew	#0x80,Deceleration-Max_speed(%a4)
		btst	#6,status(%a0)
		beqs	.return6
		/* If underwater, apply corrected speed/acceleration/deceleration*/
		movew	#0x300,Max_speed-Max_speed(%a4)
		movew	#6,Acceleration-Max_speed(%a4)
		movew	#0x40,Deceleration-Max_speed(%a4)

	.return6:
		rts
/* End of function SonicKnux_SuperHyper*/


