/* 76b*/
/* Small bubbles from Sonic's face while underwater*/
/* 76b*/
Obj_Air_CountDown:
		moveq	#0,%d0
		moveb	routine(%a0),%d0
		movew	AirCountdown_Index(%pc,%d0:w),%d1
		jmp	AirCountdown_Index(%pc,%d1:w)
/* --------------------------------------------------------------------------- */
AirCountdown_Index:
		.word AirCountdown_Init-AirCountdown_Index
		.word AirCountdown_Animate-AirCountdown_Index
		.word AirCountdown_ChkWater-AirCountdown_Index
		.word AirCountdown_Display-AirCountdown_Index
		.word AirCountdown_Delete-AirCountdown_Index
		.word AirCountdown_Countdown-AirCountdown_Index
		.word AirCountdown_AirLeft-AirCountdown_Index
		.word AirCountdown_DisplayNumber-AirCountdown_Index
		.word AirCountdown_Delete-AirCountdown_Index
/* --------------------------------------------------------------------------- */

AirCountdown_Init:
		addqb	#2,routine(%a0)
		movel	#Map_Bubbler,mappings(%a0)
		tstb	parent+1(%a0)
		beqs	loc_1819E
		movel	#Map_Bubbler2,mappings(%a0)

loc_1819E:
		movew	#0x45C,art_tile(%a0)
		moveb	#0x84,render_flags(%a0)
		moveb	#0x10,width_pixels(%a0)
		movew	#0x80,priority(%a0)
		moveb	subtype(%a0),%d0
		bpls	loc_181CC
		addqb	#8,routine(%a0)
		andiw	#0x7F,%d0
		moveb	%d0,0x37(%a0)
		braw	AirCountdown_Countdown
/* --------------------------------------------------------------------------- */

loc_181CC:
		moveb	%d0,anim(%a0)
		movew	x_pos(%a0),0x34(%a0)
		movew	#-0x100,y_vel(%a0)

AirCountdown_Animate:
		lea	(Ani_Shields),%a1
		jsr	(Animate_Sprite)

AirCountdown_ChkWater:
		movew	(Water_level),%d0
		cmpw	y_pos(%a0),%d0		/* has bubble reached the water surface?*/
		blos	AirCountdown_Wobble	/* .if not, branch*/
		/* pop the bubble:*/
		moveb	#6,routine(%a0)
		addqb	#7,anim(%a0)
		cmpib	#0xD,anim(%a0)
		beqs	AirCountdown_Display
		bcss	AirCountdown_Display
		moveb	#0xD,anim(%a0)
		bras	AirCountdown_Display
/* --------------------------------------------------------------------------- */

AirCountdown_Wobble:
		tstw	(WindTunnel_flag)
		beqs	loc_18218
		addqw	#4,0x34(%a0)

loc_18218:
		moveb	angle(%a0),%d0
		addqb	#1,angle(%a0)
		andiw	#0x7F,%d0
		lea	(AirCountdown_WobbleData),%a1
		moveb	(%a1,%d0:w),%d0
		extw	%d0
		addw	0x34(%a0),%d0
		movew	%d0,x_pos(%a0)
		bsrw	AirCountdown_ShowNumber
		jsr	(MoveSprite2)
		tstb	render_flags(%a0)
		bpls	loc_1824E
		jmp	(Draw_Sprite)
/* --------------------------------------------------------------------------- */

loc_1824E:
		jmp	(Delete_Current_Sprite)
/* --------------------------------------------------------------------------- */
/* AirCountdown_Display and AirCountdown_DisplayNumber were split in this*/
/* game, unlike Sonic 2, to fix a bug where the countdown numbers corrupted*/
/* .if they reached the surface of the water.*/
/* (The start of ARZ Act 1 is a good place to see this).*/


AirCountdown_Display:
		bsrs	AirCountdown_ShowNumber
		lea	(Ani_Shields),%a1
		jsr	(Animate_Sprite)
		bsrw	AirCountdown_Load_Art
		jmp	(Draw_Sprite)
/* --------------------------------------------------------------------------- */

AirCountdown_Delete:
		jmp	(Delete_Current_Sprite)
/* --------------------------------------------------------------------------- */

AirCountdown_AirLeft:
		moveal	0x40(%a0),%a2	/* a2=character*/
		cmpib	#0xC,air_left(%a2)	/* check air remaining*/
		bhis	loc_182AC		/* .if higher than 0xC, branch*/
		subqw	#1,0x3C(%a0)
		bnes	AirCountdown_Display2
		moveb	#0xE,routine(%a0)
		addqb	#7,anim(%a0)
		bras	AirCountdown_Display
/* --------------------------------------------------------------------------- */

AirCountdown_Display2:
		lea	(Ani_Shields),%a1
		jsr	(Animate_Sprite)
		bsrw	AirCountdown_Load_Art
		tstb	render_flags(%a0)
		bpls	loc_182AC
		jmp	(Draw_Sprite)
/* --------------------------------------------------------------------------- */

loc_182AC:
		jmp	(Delete_Current_Sprite)
/* --------------------------------------------------------------------------- */

AirCountdown_DisplayNumber:
		moveal	0x40(%a0),%a2	/* a2=character*/
		cmpib	#0xC,air_left(%a2)
		bhis	AirCountdown_Delete
		bsrs	AirCountdown_ShowNumber
		lea	(Ani_Shields),%a1
		jsr	(Animate_Sprite)
		jmp	(Draw_Sprite)

