Obj_Insta_Shield:
		/* Init*/
		movel	#Map_InstaShield,mappings(%a0)
		movel	#DPLC_InstaShield,DPLC_Address(%a0)			/* Used by PLCLoad_Shields*/
		movel	#ArtUnc_InstaShield,Art_Address(%a0)			/* Used by PLCLoad_Shields*/
		moveb	#4,render_flags(%a0)
		movew	#0x80,priority(%a0)
		moveb	#0x18,width_pixels(%a0)
		moveb	#0x18,height_pixels(%a0)
		movew	#ArtTile_Shield,art_tile(%a0)
		movew	#((ArtTile_Shield&0x7FF)<<5),vram_art(%a0)	/* Used by PLCLoad_Shields*/
		btst	#7,(Player_1+art_tile)
		beqs	.nothighpriority0
		bset	#7,art_tile(%a0)

	.nothighpriority0:
		movew	#1,anim(%a0)			/* Clear anim and set prev_anim to 1*/
		moveb	#-1,LastLoadedDPLC(%a0)		/* Reset LastLoadedDPLC (used by PLCLoad_Shields)*/
		movel	#Obj_Insta_Shield_Main,(%a0)

Obj_Insta_Shield_Main:
		moveaw	parent(%a0),%a2
		btst	#Status_Invincible,status_secondary(%a2) /* Is the player invincible?*/
		bnes	locret_195A4			/* If so, return*/
		movew	x_pos(%a2),x_pos(%a0)		/* Inherit player's x_pos*/
		movew	y_pos(%a2),y_pos(%a0)		/* Inherit player's y_pos*/
		moveb	status(%a2),status(%a0)		/* Inherit status*/
		andib	#1,status(%a0)			/* Limit inheritance to 'orientation' bit*/
		tstb	(Reverse_gravity_flag)
		beqs	.normalgravity1
		orib	#2,status(%a0)			/* Reverse the vertical mirror render_flag bit (On .if Off beforehand and vice versa)*/

	.normalgravity1:
		andiw	#drawing_mask,art_tile(%a0)
		tstw	art_tile(%a2)
		bpls	.nothighpriority1
		oriw	#high_priority,art_tile(%a0)

	.nothighpriority1:
		lea	(Ani_InstaShield),%a1
		jsr	(Animate_Sprite)
		cmpib	#7,mapping_frame(%a0)		/* Has it reached then end of its animation?*/
		bnes	.notover			/* If not, branch*/
		tstb	double_jump_flag(%a2)		/* Is it in its attacking state?*/
		beqs	.notover			/* If not, branch*/
		moveb	#2,double_jump_flag(%a2)		/* Mark attack as over*/

	.notover:
		tstb	mapping_frame(%a0)		/* Is this the first frame?*/
		beqs	.loadnewDPLC			/* If so, branch and load the DPLC for this and the next few frames*/
		cmpib	#3,mapping_frame(%a0)		/* Is this the third frame?*/
		bnes	.skipDPLC			/* If not, branch as we don't need to load another DPLC yet*/

	.loadnewDPLC:
		bsrw	PLCLoad_Shields

	.skipDPLC:
		jmp	(Draw_Sprite)
/* --------------------------------------------------------------------------- */

locret_195A4:
		rts
/* --------------------------------------------------------------------------- */

Obj_Fire_Shield:
		/* Init*/
		movel	#Map_FireShield,mappings(%a0)
		movel	#DPLC_FireShield,DPLC_Address(%a0)			/* Used by PLCLoad_Shields*/
		movel	#ArtUnc_FireShield,Art_Address(%a0)			/* Used by PLCLoad_Shields*/
		moveb	#4,render_flags(%a0)
		movew	#0x80,priority(%a0)
		moveb	#0x18,width_pixels(%a0)
		moveb	#0x18,height_pixels(%a0)
		movew	#ArtTile_Shield,art_tile(%a0)
		movew	#((ArtTile_Shield&0x7FF)<<5),vram_art(%a0)	/* Used by PLCLoad_Shields*/
		btst	#7,(Player_1+art_tile)
		beqs	loc_195F0
		bset	#7,art_tile(%a0)

loc_195F0:
		movew	#1,anim(%a0)				/* Clear anim and set prev_anim to 1*/
		moveb	#-1,LastLoadedDPLC(%a0)			/* Reset LastLoadedDPLC (used by PLCLoad_Shields)*/
		movel	#Obj_Fire_Shield_Main,(%a0)

Obj_Fire_Shield_Main:
		moveaw	parent(%a0),%a2
		btst	#Status_Invincible,status_secondary(%a2) /* Is player invincible?*/
		bnew	locret_19690				/* If so, do not display and do not update variables*/
		cmpib	#0x1C,anim(%a2)				/* Is player in their 'blank' animation?*/
		beqs	locret_19690				/* If so, do not display and do not update variables*/
		btst	#Status_Shield,status_secondary(%a2) 	/* Should the player still have a shield?*/
		beqw	Obj_Fire_Shield_Destroy			/* If not, change to Insta-Shield*/
		btst	#Status_Underwater,status(%a2)		/* Is player underwater?*/
		bnes	Obj_Fire_Shield_DestroyUnderwater	/* If so, branch*/
		movew	x_pos(%a2),x_pos(%a0)
		movew	y_pos(%a2),y_pos(%a0)
		tstb	anim(%a0)				/* Is shield in its 'dashing' state?*/
		bnes	.nothighpriority2			/* If so, do not update orientation or allow changing of the priority art_tile bit*/
		moveb	status(%a2),status(%a0)			/* Inherit status*/
		andib	#1,status(%a0)				/* Limit inheritance to 'orientation' bit*/
		tstb	(Reverse_gravity_flag)
		beqs	.normalgravity2
		orib	#2,status(%a0)				/* If in reverse gravity, reverse the vertical mirror render_flag bit (On .if Off beforehand and vice versa)*/

	.normalgravity2:
		andiw	#drawing_mask,art_tile(%a0)
		tstw	art_tile(%a2)
		bpls	.nothighpriority2
		oriw	#high_priority,art_tile(%a0)

	.nothighpriority2:
		lea	(Ani_FireShield),%a1
		jsr	(Animate_Sprite)
		movew	#0x80,priority(%a0)		/* Layer shield over player sprite*/
		cmpib	#0xF,mapping_frame(%a0)		/* Are these the frames that display in front of the player?*/
		blos	.overplayer0			/* If so, branch*/
		movew	#0x200,priority(%a0)		/* If not, layer shield behind player sprite*/

	.overplayer0:
