superTailsBirds_target_found = 0x30
superTailsBirds_search_delay = 0x32
superTailsBirds_angle = 0x34
superTailsBirds_target_address = 0x42

Obj_SuperTailsBirds:
		lea	(ArtKosM_SuperTailsBirds),%a1
		movew	#((ArtTile_Player_1&0x7FF)<<5),%d2
		jsr	(Queue_Kos_Module)
		lea	(%a0),%a1
		moveq	#0,%d0
		moveq	#4-1,%d1

	.loop1:
		movel	#Obj_SuperTailsBirds_Init,(%a1)
		moveb	%d0,superTailsBirds_angle(%a1)
		addib	#0x40,%d0	/* 90 degrees*/
		lea	next_object(%a1),%a1
		dbf	%d1,.loop1

Obj_SuperTailsBirds_Init:
		/* Wait for the object's art to finish loading*/
		tstb	(Kos_modules_left)
		beqs	.art_done_loading
		rts
/* --------------------------------------------------------------------------- */

	.art_done_loading:
		movel	#Map_SuperTails_Birds,mappings(%a0)
		moveb	#4,render_flags(%a0)
		movew	#0x80,priority(%a0)
		moveb	#8,width_pixels(%a0)
		moveb	#8,height_pixels(%a0)
		movew	#((1&1)<<15)+((0&3)<<13)+(ArtTile_Player_1&tile_mask),art_tile(%a0)
		movew	(Player_1+x_pos),x_pos(%a0)
		movew	(Player_1+y_pos),y_pos(%a0)
		subiw	#0xC0,x_pos(%a0)
		subiw	#0xC0,y_pos(%a0)
		movew	#0,x_vel(%a0)
		movew	#0,y_vel(%a0)
		movel	#Obj_SuperTailsBirds_Main,(%a0)

Obj_SuperTailsBirds_Main:
		tstb	(Super_Tails_flag)
		bnes	.tails_still_super
		/* Tails has returned to normal - make the birds fly away*/
		moveq	#0,%d0
		movew	%d0,(Player_2+x_pos)
		movew	%d0,(Player_2+y_pos)
		moveb	%d0,(Player_2+anim)
		tstb	superTailsBirds_target_found(%a0)
		beqs	.no_target
		moveaw	superTailsBirds_target_address(%a0),%a1
		moveb	%d0,0x2D(%a1)	/* Seems to be for indicating whether an object has been 'locked-onto' or not*/

	.no_target:
		moveb	%d0,superTailsBirds_target_found(%a0)
		moveb	#60*2,superTailsBirds_search_delay(%a0)	/* Only search for enemies every two seconds (probably to reduce lag)*/
		movel	#Obj_SuperTailsBirds_FlyAway,(%a0)

	.tails_still_super:
		bsrs	Obj_SuperTailsBirds_GetDestination

	.move:
		bsrw	Obj_SuperTailsBirds_Move
		addib	#2,superTailsBirds_angle(%a0)
		/* Update which way the sprite faces*/
		tstw	x_vel(%a0)
		beqs	.x_flip_done
		bpls	.face_right

		bset	#0,render_flags(%a0)
		bras	.x_flip_done
/* --------------------------------------------------------------------------- */

	.face_right:
		bclr	#0,render_flags(%a0)

	.x_flip_done:
		/* Update whether the sprite should be upside down*/
		andib	#~2,render_flags(%a0)
		tstb	(Reverse_gravity_flag)
		beqs	.not_upside_down0
		orib	#2,render_flags(%a0)

	.not_upside_down0:
		subqb	#1,anim_frame_timer(%a0)
		bpls	.timer_not_over
		moveb	#1,anim_frame_timer(%a0)
		addqb	#1,mapping_frame(%a0)
		andib	#1,mapping_frame(%a0)

	.timer_not_over:
		jmp	(Draw_Sprite)
/* --------------------------------------------------------------------------- */

Obj_SuperTailsBirds_FlyAway:
		/* Set bird's destination to top-left of the screen*/
		movew	(Player_1+x_pos),%d2
		movew	(Player_1+y_pos),%d3
		subiw	#0xC0,%d2
		subiw	#0xC0,%d3

		tstb	render_flags(%a0)
		bmis	Obj_SuperTailsBirds_Main.move
		jmp	(Delete_Current_Sprite)	/* If sprite is off-screen, delete it*/

/* =============== S U B R O U T I N E =======================================*/


Obj_SuperTailsBirds_GetDestination:
		tstb	superTailsBirds_target_found(%a0)
		bnes	.fly_towards_enemy
		tstb	superTailsBirds_search_delay(%a0)
		beqs	.look_for_target
		subqb	#1,superTailsBirds_search_delay(%a0)
		bras	.fly_around_tails
/* --------------------------------------------------------------------------- */

	.look_for_target:
		bsrw	Obj_SuperTailsBirds_FindTarget
		tstw	%d1
		bnes	.fly_towards_enemy

	.fly_around_tails:
		moveb	superTailsBirds_angle(%a0),%d0
		jsr	(GetSineCosine)
		asrw	#3,%d0
		asrw	#4,%d1
		movew	(Player_1+x_pos),%d2
		movew	(Player_1+y_pos),%d3
		subiw	#0x20,%d3
		tstb	(Reverse_gravity_flag)
		beqs	.not_upside_down1
		addiw	#0x20*2,%d3

	.not_upside_down1:
		addw	%d0,%d2
		addw	%d1,%d3
		rts
/* --------------------------------------------------------------------------- */

	.fly_towards_enemy:
		moveaw	superTailsBirds_target_address(%a0),%a1
		movew	x_pos(%a1),%d2
		movew	y_pos(%a1),%d3
		tstb	render_flags(%a1)
		bpls	.enemy_off_screen
		movew	x_pos(%a0),%d0
		subw	%d2,%d0
		addiw	#0xC,%d0
		cmpiw	#0x18,%d0
		bhss	.enemy_out_of_range
		movew	y_pos(%a0),%d1
		subw	%d3,%d1
		addiw	#0xC,%d1
		cmpiw	#0x18,%d1
		bhss	.enemy_out_of_range
		bsrs	.hit_enemy

	.enemy_off_screen:
		moveb	#0,0x2D(%a1)
		moveb	#0,superTailsBirds_target_found(%a0)
		moveb	#60*2,superTailsBirds_search_delay(%a0)

	.enemy_out_of_range:
		rts
/* End of function Obj_SuperTailsBirds_GetDestination*/


/* =============== S U B R O U T I N E =======================================*/


	.hit_enemy:
		moveb	collision_flags(%a1),%d0
		beqs	.no_collision	/* If object has no collision, give up*/
		andib	#0xC0,%d0
		beqs	.enemy
		cmpib	#0xC0,%d0
		beqs	.special

	.no_collision:
		rts
/* --------------------------------------------------------------------------- */

	.enemy:
		tstb	collision_property(%a1)
		beqs	.destroy_enemy
		/* Boss*/
		moveb	collision_flags(%a1),0x25(%a1)
		movew	#Player_2,%d0
		moveb	%d0,0x1C(%a1)
		moveb	#0,collision_flags(%a1)
		subqb	#1,collision_property(%a1)
		bnes	.skip
		bset	#7,status(%a1)

	.skip:
		bras	.done4
/* --------------------------------------------------------------------------- */

	.destroy_enemy:
		jmp	(HyperTouch_DestroyEnemy)
/* --------------------------------------------------------------------------- */

	.special:
		orib	#2,collision_property(%a1)

	.done4:
		movew	x_pos(%a0),(Player_2+x_pos)
		movew	y_pos(%a0),(Player_2+y_pos)
		moveb	#2,(Player_2+anim)
		rts
/* End of function sub_1A31E*/


/* =============== S U B R O U T I N E =======================================*/


Obj_SuperTailsBirds_Move:
		/* Update the bird's x_vel*/
		movew	#0x20,%d1
		cmpw	x_pos(%a0),%d2
		bges	.go_right
		negw	%d1
		tstw	x_vel(%a0)
		bmis	.x_vel_done
		/* Going the wrong way - make it turn around faster*/
		addw	%d1,%d1
		addw	%d1,%d1
		bras	.x_vel_done
/* --------------------------------------------------------------------------- */

	.go_right:
