Obj_HyperSonicKnux_Trail:
		/* init*/
		movel	#Map_Knuckles,mappings(%a0)	/* Load Knuckles' mappings*/
		cmpiw	#3,(Player_mode)		/* Are we playing as Knuckles?*/
		bhss	.playingasknux			/* If so, branch*/
		movel	#Map_SuperSonic,mappings(%a0)	/* If not, you must be Hyper Sonic, load Super/Hyper Sonic mappings*/

	.playingasknux:
		movew	#ArtTile_Player_1,art_tile(%a0)
		movew	#0x100,priority(%a0)
		moveb	#0x18,width_pixels(%a0)
		moveb	#0x18,height_pixels(%a0)
		moveb	#4,render_flags(%a0)
		movel	#Obj_HyperSonicKnux_Trail_Main,(%a0)

Obj_HyperSonicKnux_Trail_Main:
		tstb	(Super_Sonic_Knux_flag)	/* Are we in non-super/hyper state?*/
		beqw	Delete_Current_Sprite		/* If so, branch and delete*/
		moveq	#0xC,%d1				/* This will be subtracted from Pos_table_index, giving the object an older entry*/
		btst	#0,(Level_frame_counter+1)	/* Even frame? (Think of it as 'every other number' logic)*/
		beqs	.evenframe			/* If so, branch*/
		moveq	#0x14,%d1				/* On every other frame, use a different number to subtract, giving the object an even older entry*/

	.evenframe:
		movew	(Pos_table_index),%d0
		lea	(Pos_table),%a1
		subb	%d1,%d0
		lea	(%a1,%d0:w),%a1
		movew	(%a1)+,x_pos(%a0)			/* Use previous player x_pos*/
		movew	(%a1)+,y_pos(%a0)			/* Use previous player y_pos*/
		lea	(Stat_table),%a1
		moveb	3(%a1,%d0:w),art_tile(%a0)
		moveb	(Player_1+mapping_frame),mapping_frame(%a0)	/* Use player's current mapping_frame*/
		moveb	(Player_1+render_flags),render_flags(%a0)	/* Use player's current render_flags*/
		movew	(Player_1+priority),priority(%a0)		/* Use player's current priority*/
		braw	Draw_Sprite
