GiveRing:
		cmpiw	#999,(Total_ring_count)	/* did Sonic collect 999 or more rings?*/
		bhss	GiveRing_1P			/* .if yes, branch*/
		addqw	#1,(Total_ring_count)		/* add 1 to the number of collected rings*/

GiveRing_1P:
		movew	#sfx_RingRight,%d0				/* prepare to play the ring sound*/
		cmpiw	#999,(Ring_count)		/* does the player 1 have 999 or more rings?*/
		bhss	JmpTo_Play_Sound_2		/* .if yes, play the ring sound*/
		addqw	#1,(Ring_count)		/* add 1 to the ring count*/
		orib	#1,(Update_HUD_ring_count)	/* set flag to update the ring counter in the HUD*/
		cmpiw	#100,(Ring_count)		/* does the player 1 have less than 100 rings?*/
		blos	JmpTo_Play_Sound_2		/* .if yes, play the ring sound*/
		bset	#1,(Extra_life_flags)		/* test and set the flag for the first extra life*/
		beqs	loc_1A5D8			/* .if it was clear before, branch*/
		cmpiw	#200,(Ring_count)		/* does the player 1 have less than 200 rings?*/
		blos	JmpTo_Play_Sound_2		/* .if yes, play the ring sound*/
		bset	#2,(Extra_life_flags)		/* test and set the flag for the second extra life*/
		bnes	JmpTo_Play_Sound_2		/* .if it was set before, play the ring sound*/

