/* --------------------------------------------------------------------------- */
Monitor_Index:
		.word Obj_MonitorInit-Monitor_Index
		.word Obj_MonitorMain-Monitor_Index
		.word Obj_MonitorBreak-Monitor_Index
		.word Obj_MonitorAnimate-Monitor_Index
		.word loc_1D61A-Monitor_Index
/* --------------------------------------------------------------------------- */

Obj_MonitorInit:
		addqb	#2,routine(%a0)	/* => Obj_MonitorMain*/
		moveb	#0xF,y_radius(%a0)
		moveb	#0xF,x_radius(%a0)
		movel	#Map_Monitor,mappings(%a0)
		movew	#ArtTile_Monitors,art_tile(%a0)
		orib	#4,render_flags(%a0)
		movew	#0x180,priority(%a0)
		moveb	#0xE,width_pixels(%a0)
		moveb	#0x10,height_pixels(%a0)
		movew	respawn_addr(%a0),%d0	/* Get address in respawn table*/
		beqs	.notbroken0		/* If it's zero, it isn't remembered*/
		moveaw	%d0,%a2			/* Load address into %a2*/
		btst	#0,(%a2)			/* Is this monitor broken?*/
		beqs	.notbroken0		/* If not, branch*/
		moveb	#0xB,mapping_frame(%a0)	/* Use 'broken monitor' frame*/
		movel	#Sprite_OnScreen_Test,(%a0)
