		movew	x_pos(%a0),%d4
		lea	(Player_1),%a1
		moveq	#p1_standing_bit,%d6
		moveml	%d1-%d4,-(%sp)
		bsrw	SolidObject_Monitor_SonicKnux
		moveml	(%sp)+,%d1-%d4
		lea	(Player_2),%a1
		moveq	#p2_standing_bit,%d6
		bsrw	SolidObject_Monitor_Tails
		jsr	(Add_SpriteToCollisionResponseList)
		lea	(Ani_Monitor),%a1
		bsrw	Animate_Sprite

