Obj_MonitorAnimate:
		cmpib	#0xB,mapping_frame(%a0)	/* Is monitor broken?*/
		bnes	.notbroken1		/* If not, branch*/
		movel	#loc_1D61A,(%a0)

	.notbroken1:
		lea	(Ani_Monitor),%a1
		bsrw	Animate_Sprite
		braw	Sprite_OnScreen_Test

/* =============== S U B R O U T I N E =======================================*/


Obj_MonitorFall:
		moveb	routine_secondary(%a0),%d0
		beqs	locret_1D694
		btst	#1,render_flags(%a0)	/* Is monitor upside down?*/
		bnes	Obj_MonitorFallUpsideDown /* If so, branch*/
		bsrw	MoveSprite
		tstw	y_vel(%a0)		/* Is monitor moving up?*/
		bmis	locret_1D694		/* If so, return*/
		jsr	(ObjCheckFloorDist)
		tstw	%d1			/* Is monitor in the ground?*/
		beqs	.inground0		/* If so, branch*/
		bpls	locret_1D694		/* .if not, return*/

	.inground0:
		addw	%d1,y_pos(%a0)		/* Move monitor out of the ground*/
		clrw	y_vel(%a0)
		clrb	routine_secondary(%a0)	/* Stop monitor from falling*/
		rts
/* --------------------------------------------------------------------------- */

Obj_MonitorFallUpsideDown:
		bsrw	MoveSprite2
		subiw	#0x38,y_vel(%a0)
		tstw	y_vel(%a0)		/* Is monitor moving down?*/
		bpls	locret_1D694		/* If so, return*/
		jsr	(ObjCheckCeilingDist)
		tstw	%d1			/* Is monitor in the ground (ceiling)?*/
		beqs	.inground1		/* If so, branch*/
		bpls	locret_1D694		/* .if not, return*/

	.inground1:
		subw	%d1,y_pos(%a0)		/* Move monitor out of the ground*/
		clrw	y_vel(%a0)
		clrb	routine_secondary(%a0)	/* Stop monitor from falling*/

locret_1D694:
		rts
/* End of function Obj_MonitorFall*/


