SolidObject_Monitor_SonicKnux:
		btst	%d6,status(%a0)		/* Is Sonic/Knux standing on the monitor?*/
		bnes	Monitor_ChkOverEdge	/* If so, branch*/
		cmpib	#2,anim(%a1)		/* Is Sonic/Knux in their rolling animation?*/
		beqs	locret_1D6BC		/* If so, return*/
		cmpib	#2,character_id(%a1)	/* Is character Knuckles?*/
		bnes	loc_1D6BE		/* If not, branch*/
		cmpib	#1,double_jump_flag(%a1)	/* Is Knuckles gliding?*/
		beqs	locret_1D6BC		/* If so, return*/
		cmpib	#3,double_jump_flag(%a1)	/* Is Knuckles sliding after gliding?*/
		bnes	loc_1D6BE		/* If not, branch*/

locret_1D6BC:
		rts
/* --------------------------------------------------------------------------- */

loc_1D6BE:
		braw	SolidObject_cont
/* End of function SolidObject_Monitor_SonicKnux*/


