SolidObject_Monitor_Tails:
		btst	%d6,status(%a0)		/* Is Tails standing on the monitor?*/
		bnes	Monitor_ChkOverEdge	/* If so, branch*/
		tstw	(Competition_mode)	/* Are we in competition mode?*/
		beqw	SolidObject_cont	/* If not, branch*/
		cmpib	#2,anim(%a1)		/* Is Tails in his rolling animation?*/
		bnew	SolidObject_cont	/* If not, branch*/
		rts
/* --------------------------------------------------------------------------- */

Monitor_ChkOverEdge:
		movew	%d1,%d2
		addw	%d2,%d2
		btst	#1,status(%a1)		/* Is the character in the air?*/
		bnes	.notonmonitor		/* If so, branch*/
		/* Check .if character is standing on*/
		movew	x_pos(%a1),%d0
		subw	x_pos(%a0),%d0
		addw	%d1,%d0
		bmis	.notonmonitor		/* Branch, .if character is behind the left edge of the monitor*/
		cmpw	%d2,%d0
		blos	Monitor_CharStandOn	/* Branch, .if character is not beyond the right edge of the monitor*/

	.notonmonitor:
		/* .if the character isn't standing on the monitor*/
		bclr	#3,status(%a1)		/* Clear 'on object' bit*/
		bset	#1,status(%a1)		/* Set 'in air' bit*/
		bclr	%d6,status(%a0)		/* Clear 'standing on' bit for the current character*/
		moveq	#0,%d4
		rts
/* --------------------------------------------------------------------------- */

Monitor_CharStandOn:
		movew	%d4,%d2
		bsrw	MvSonicOnPtfm
		moveq	#0,%d4
		rts
/* End of function SolidObject_Monitor_Tails*/

