Obj_MonitorBreak:
		moveb	status(%a0),%d0
		andib	#standing_mask+pushing_mask,%d0	/* Is someone touching the monitor?*/
		beqs	Obj_MonitorSpawnIcon		/* If not, branch*/
		moveb	%d0,%d1
		andib	#p1_standing+p1_pushing,%d1	/* Is it the main character?*/
		beqs	.notmainchar			/* If not, branch*/
		andib	#0xD7,(Player_1+status)
		orib	#2,(Player_1+status)		/* Prevent main character from walking in the air*/

	.notmainchar:
		andib	#p2_standing+p2_pushing,%d0	/* Is it the sidekick?*/
		beqs	Obj_MonitorSpawnIcon		/* If not, branch*/
		andib	#0xD7,(Player_2+status)
		orib	#2,(Player_2+status)		/* Prevent sidekick from walking in the air*/

Obj_MonitorSpawnIcon:
		andib	#3,status(%a0)
		moveb	#0,collision_flags(%a0)
		bsrw	Create_New_Sprite3
		bnes	.skipiconcreation
		movel	#Obj_MonitorContents,(%a1)
		movew	x_pos(%a0),x_pos(%a1)		/* Set icon's position*/
		movew	y_pos(%a0),y_pos(%a1)
		moveb	anim(%a0),anim(%a1)
		moveb	render_flags(%a0),render_flags(%a1)
		moveb	status(%a0),status(%a1)
		movew	parent(%a0),parent(%a1)

	.skipiconcreation:
		bsrw	Create_New_Sprite3
		bnes	.skipexplosioncreation
		movel	#Obj_Explosion,(%a1)
		addqb	#2,routine(%a1)			/* => loc_1E61A*/
		movew	x_pos(%a0),x_pos(%a1)		/* Set explosion's position*/
		movew	y_pos(%a0),y_pos(%a1)

	.skipexplosioncreation:
		movew	respawn_addr(%a0),%d0		/* Get address in respawn table*/
		beqs	.notremembered			/* If it's zero, it isn't remembered*/
		moveaw	%d0,%a2				/* Load address into %a2*/
		bset	#0,(%a2)				/* Mark monitor as destroyed*/

	.notremembered:
		moveb	#0xA,anim(%a0)			/* Display 'broken' animation*/
		movel	#Obj_MonitorAnimate,(%a0)
		braw	Draw_Sprite
