AnimateTiles_DoAniPLC:
		lea	(Anim_Counters),%a3

loc_286E8:
		movew	(%a2)+,%d6			/* Get number of scripts in list*/
		bpls	AnimateTiles_DoAniPLC_Part2	/* If there are any, continue*/
		rts

AnimateTiles_DoAniPLC_Part2:
		subqb	#1,(%a3)		/* Tick down frame duration*/
		bccs	.nextscript	/* If frame isn't over, move on to next script*/

		moveq	#0,%d0
		moveb	1(%a3),%d0	/* Get current frame*/
		cmpb	6(%a2),%d0	/* Have we processed the last frame in the script?*/
		blos	.notlastframe
		moveq	#0,%d0		/* If so, reset to first frame*/
		moveb	%d0,1(%a3)	/* ''*/

	.notlastframe:
		addqb	#1,1(%a3)	/* Consider this frame processed// set counter to next frame*/
		moveb	(%a2),(%a3)	/* Set frame duration to global duration value*/
		bpls	.globalduration
		/* If script uses per-frame durations, use those instead*/
		addw	%d0,%d0
		moveb	9(%a2,%d0:w),(%a3)	/* Set frame duration to current frame's duration value*/

	.globalduration:
	/* Prepare for DMA transfer*/
		/* Get relative address of frame's art*/
		moveb	8(%a2,%d0:w),%d0	/* Get tile ID*/
		lslw	#5,%d0		/* Turn it into an offset*/
		/* Get VRAM destination address*/
		movew	4(%a2),%d2
		/* Get ROM source address*/
		movel	(%a2),%d1		/* Get start address of animated tile art*/
		andil	#0xFFFFFF,%d1
		addl	%d0,%d1		/* Offset into art, to get the address of new frame*/
		/* Get size of art to be transferred*/
		moveq	#0,%d3
		moveb	7(%a2),%d3
		lslw	#4,%d3		/* Turn it into actual size (in words)*/
		/* Use %d1, %d2 and %d3 to queue art for transfer*/
		jsr	(Add_To_DMA_Queue)

	.nextscript:
		moveb	6(%a2),%d0	/* Get total size of frame data*/
		tstb	(%a2)		/* Is per-frame duration data present?*/
		bpls	.globalduration2/* If not, keep the current size// it's correct*/
		addb	%d0,%d0		/* Double size to account for the additional frame duration data*/

	.globalduration2:
		addqb	#1,%d0
		andiw	#0xFE,%d0		/* Round to next even address, .if it isn't already*/
		lea	8(%a2,%d0:w),%a2	/* Advance to next script in list*/
		addqw	#2,%a3		/* Advance to next script's slot in %a3 (usually Anim_Counters)*/
		dbf	%d6,AnimateTiles_DoAniPLC_Part2
		rts
/* End of function AnimateTiles_DoAniPLC*/

/* ===========================================================================*/
/* ZONE ANIMATION SCRIPTS*/
//
/* The AnimateTiles_DoAniPLC subroutine uses these scripts to reload certain tiles,*/
/* thus animating them. All the relevant art must be uncompressed, because*/
/* otherwise the subroutine would spend so much time waiting for the art to be*/
/* decompressed that the VBLANK window would close before all the animating was done.*/

/*    zoneanimdecl -1, ArtUnc_Flowers1, ArtTile_ArtUnc_Flowers1, 6, 2*/
/*	-1			Global frame duration. If -1, then each frame will use its own duration, instead*/
/*	ArtUnc_Flowers1		Source address*/
/*	ArtTile_ArtUnc_Flowers1	Destination VRAM address*/
/*	6			Number of frames*/
/*	2			Number of tiles to load into VRAM for each frame*/

/*    .byte   0,0x7F		// Start of the script proper*/
/*	0			Tile ID of first tile in ArtUnc_Flowers1 to transfer*/
/*	0x7F			Frame duration. Only here .if global duration is -1*/

