Obj_MHZMushroomCap:
		/* init routine*/
		movew	#0x80,priority(%a0)
		moveb	subtype(%a0),%d0		/* If bit 7 set...*/
		bpls	.highspritepriority
		movew	#0x300,priority(%a0)

	.highspritepriority:
		moveb	%d0,%d1
		movew	#0xC369,art_tile(%a0)	/* Dark-spotted mushroom*/
		andib	#1,%d0			/* If bit 0 set...*/
		beqs	.lightmushroom
		movew	#0xC399,art_tile(%a0)	/* Light-spotted mushroom*/
		moveb	#0x14,0x36(%a0)		/* Change animation timing a little, so not all mushrooms are synchronised*/

	.lightmushroom:
		addb	%d1,%d1			/* If bit 6 set...*/
		bpls	.highplanepriority
		andiw	#0x7FFF,art_tile(%a0)	/* Strip 'high priority' bit*/

	.highplanepriority:
		movel	#Map_MHZMushroomCap,mappings(%a0)
		orib	#4,render_flags(%a0)
		moveb	#0x20,width_pixels(%a0)
		moveb	#0x10,height_pixels(%a0)
		bset	#7,status(%a0)		/* ???*/
		movew	x_pos(%a0),0x38(%a0)	/* Store initial x_pos*/
		movew	y_pos(%a0),0x3A(%a0)	/* Store initial y_pos*/
		movel	#Obj_MHZMushroomCap_Main,(%a0)

Obj_MHZMushroomCap_Main:
		/* main routine*/
		lea	(Ani_MHZMushroomCap),%a1
		jsr	(Animate_Sprite)
		tstb	routine(%a0)		/* Has animation byte_3E1E1 ended?*/
		beqs	.animstillgoing
		movew	#0,anim(%a0)		/* and prev_anim*/
		moveb	#0,anim_frame(%a0)
		clrb	routine(%a0)

	.animstillgoing:
		bsrs	MHZMushroomCap_UpdatePosition
		movew	#0x18,%d1
		moveq	#0,%d3
		moveb	mapping_frame(%a0),%d3
		moveb	byte_3E0DA(%pc,%d3:w),%d3
		movew	x_pos(%a0),%d4
		jsr	(SolidObjectTop)
		/* Bounce player*/
		lea	(Player_1),%a1
		moveq	#0x30,%d5		/* 0x30(%a0), player's y_vel*/
		moveq	#3,%d6		/* 'Player standing on this object' bit*/
		bsrw	MHZMushroomCap_BounceCharacter
		/* Bounce sidekick*/
		lea	(Player_2),%a1
		moveq	#0x32,%d5		/* 0x32(%a0), sidekick's y_vel*/
		moveq	#4,%d6		/* 'Sidekick standing on this object' bit*/
		bsrw	MHZMushroomCap_BounceCharacter

		jmp	(Sprite_OnScreen_Test)
