MHZMushroomCap_UpdatePosition:
		moveq	#0,%d0
		moveb	(Anim_Counters+0xF),%d0	/* Update according to level animation*/
		addb	0x36(%a0),%d0		/* Add in offset value, so not all mushrooms animate identically*/
		lea	MHZMushroomCap_Positions(%pc,%d0:w),%a1	/* Get appropriate data*/
		/* Update x_pos*/
		moveb	(%a1)+,%d0
		extw	%d0
		addw	0x38(%a0),%d0	/* Add initial x_pos*/
		movew	%d0,x_pos(%a0)	/* Set x_pos*/
		/* Update y_pos*/
		moveb	(%a1)+,%d1
		extw	%d1
		addw	0x3A(%a0),%d1	/* Add initial y_pos*/
		movew	%d1,y_pos(%a0)	/* Set y_pos*/
		rts
/* End of function MHZMushroomCap_UpdatePosition*/

