MHZMushroomCap_BounceCharacter:
		btst	%d6,status(%a0)		/* Is character standing on object?*/
		bnes	.characteronmushroom	/* If so, prepare to bounce them*/
		movew	y_vel(%a1),(%a0,%d5:w)	/* If not, just store character's y_vel*/
		rts

	.characteronmushroom:
		moveb	#1,anim(%a0)		/* Set mushroom to 'spring' animation*/
		cmpib	#3,mapping_frame(%a0)	/* Are we at an actual 'spring up' frame?*/
		bnes	.return9			/* If not, return and don't do anything .else to the character*/
		movew	(%a0,%d5:w),%d0		/* Get character's previous y_vel*/
		/* These checks make the character bounce higher .if they hit the mushroom at a high speed*/
		movew	#0x660,%d1
		cmpw	%d1,%d0			/* Is character going slow?*/
		blts	.bouncecharacter	/* If so, make them bounce low*/
		movew	#0x760,%d1
		cmpw	%d1,%d0			/* Is character going faster?*/
		blts	.bouncecharacter	/* If so, make them bounce high*/
		movew	#0x860,%d1		/* Otherwise, they're going really fast// make them bounce really high*/

	.bouncecharacter:
		addiw	#0x20,%d1
		negw	%d1
		movew	%d1,y_vel(%a1)		/* Set character's y_vel, bouncing them*/
		bset	#1,status(%a1)		/* Set character's 'in air' bit*/
		bclr	#3,status(%a1)		/* Clear character's 'on object' bit*/
		clrb	jumping(%a1)
		clrb	spin_dash_flag(%a1)
		moveb	#0x10,anim(%a1)		/* Set character to 'spring-jumping' animation*/
		moveb	#2,routine(%a1)
		moveb	#sfx_MushroomBounce,%d0
		jmp	(Play_Sound_2)	/* Play bounce sound*/

	.return9:
		rts
/* End of function MHZMushroomCap_BounceCharacter*/

