/* --------------------------------------------------------------------------- */

HCZ1_ScreenInit:
		clrw	(Events_bg+0x16)
		jsr	Reset_TileOffsetPositionActual(%pc)
		jmp	Refresh_PlaneFull(%pc)
/* --------------------------------------------------------------------------- */

HCZ1_ScreenEvent:
		jmp	DrawTilesAsYouMove(%pc)
/* --------------------------------------------------------------------------- */

HCZ1_BackgroundInit:
		jsr	HCZ1_Deform(%pc)
		jsr	Reset_TileOffsetPositionEff(%pc)
		moveq	#0,%d1
		jsr	Refresh_PlaneFull(%pc)
		moveq	#0x60,%d0
		cmpw	(Events_bg+0x10),%d0
		blts	loc_50BAC
		negw	%d0
		cmpw	(Events_bg+0x10),%d0
		bgts	loc_50BB0

loc_50BAC:
		movew	%d0,(Events_bg+0x10)		/* Cap dynamic art reloading value at 0x60 either way*/

loc_50BB0:
		lea	(HCZ1_BGDeformArray),%a4
		lea	(HScroll_table),%a5
		jmp	ApplyDeformation(%pc)
/* --------------------------------------------------------------------------- */

HCZ1_BackgroundEvent:
		movew	(Events_routine_bg),%d0
		jmp	loc_50BC6(%pc,%d0:w)
/* --------------------------------------------------------------------------- */

loc_50BC6:
		braw	HCZ1BGE_Normal
/* --------------------------------------------------------------------------- */
		braw	HCZ1BGE_DoTransition
/* --------------------------------------------------------------------------- */

HCZ1BGE_Normal:
		tstw	(Events_fg_5)
		beqs	loc_50C2A
		clrw	(Events_fg_5)				/* Do transition*/
		moveml	%d7-%a0/%a2-%a3,-(%sp)
		lea	(HCZ2_128x128_Secondary_Kos),%a1
		lea	(RAM_start+0xA00),%a2
		jsr	(Queue_Kos)
		lea	(HCZ2_16x16_Secondary_Kos),%a1
		lea	(Block_table+0x558),%a2
		jsr	(Queue_Kos)
		lea	(HCZ2_8x8_Secondary_KosM),%a1	/* Load secondary HCZ2 art, blocks, and chunks so as to not compromise current position*/
		movew	#0x2360,%d2
		jsr	(Queue_Kos_Module)
		moveq	#0x10,%d0
		jsr	(Load_PLC)
		moveq	#0x11,%d0
		jsr	(Load_PLC)					/* load HCZ 2 PLCs*/
		moveml	(%sp)+,%d7-%a0/%a2-%a3
		st	(Events_bg+0x16)
		addqw	#4,(Events_routine_bg)

loc_50C2A:
		jsr	HCZ1_Deform(%pc)
		lea	(Camera_Y_pos_BG_copy),%a6
		lea	(Camera_Y_pos_BG_rounded),%a5
		moveq	#0,%d1
		moveq	#0x20,%d6
		jsr	Draw_TileRow(%pc)
		lea	(HCZ1_BGDeformArray),%a4
		lea	(HScroll_table),%a5
		jmp	ApplyDeformation(%pc)
/* --------------------------------------------------------------------------- */

HCZ1BGE_DoTransition:
		tstb	(Kos_modules_left)
		bnew	loc_50CDC			/* Don't do anything .else until kos queue has been cleared*/
		movew	#0x101,(Current_zone_and_act)	/* Change the act*/
		clrb	(Dynamic_resize_routine)		/* Reload resize routine counter*/
		clrb	(Object_load_routine)		/* Reload sprite manager*/
		clrb	(Rings_manager_routine)		/* Reload ring manager*/
		clrb	(Boss_flag)		/* Unlock the screen*/
		clrb	(Respawn_table_keep)		/* Refresh sprite/ring memory*/
		jsr	Clear_Switches(%pc)
		movel	#Obj_HCZWaterSplash,(Dynamic_object_RAM+(object_size*2))	/* Load the splash object*/
		moveb	#1,(Dynamic_object_RAM+(object_size*2)+subtype)
		moveml	%d7-%a0/%a2-%a3,-(%sp)
		jsr	(Load_Level)				/* Load HCZ2 layout*/
		jsr	(LoadSolids)
		jsr	(CheckLevelForWater)
		movew	#0x6A0,%d0
		movew	%d0,(Water_level)
		movew	%d0,(Mean_water_level)
		movew	%d0,(Target_water_level)	/* Set the water up*/
		moveq	#0xD,%d0
		jsr	(LoadPalette_Immediate)	/* Load HCZ2 palette*/
		moveml	(%sp)+,%d7-%a0/%a2-%a3
		movew	#0x3600,%d0
		moveq	#0,%d1
		subw	%d0,(Player_1+x_pos)
		subw	%d0,(Player_2+x_pos)
		jsr	Offset_ObjectsDuringTransition(%pc)
		subw	%d0,(Camera_X_pos)
		subw	%d0,(Camera_X_pos_copy)
		subw	%d0,(Camera_min_X_pos)
		subw	%d0,(Camera_max_X_pos)		/* Offset objects/camera position by specified amount*/
		jsr	Reset_TileOffsetPositionActual(%pc)
		clrw	(Events_routine_bg)

loc_50CDC:
		jsr	HCZ1_Deform(%pc)
		lea	(Camera_Y_pos_BG_copy),%a6
		lea	(Camera_Y_pos_BG_rounded),%a5
		moveq	#0,%d1
		moveq	#0x20,%d6
		jsr	Draw_TileRow(%pc)
		lea	(HCZ1_BGDeformArray),%a4
		lea	(HScroll_table),%a5
		jmp	ApplyDeformation(%pc)

/* =============== S U B R O U T I N E =======================================*/


HCZ1_Deform:
		movew	(Camera_Y_pos_copy),%d0		/* Get the BG camera Y position*/
		subiw	#0x610,%d0				/* Get the difference between that and the water line equilibrium point*/
		movew	%d0,%d1
		asrw	#2,%d0
		movew	%d0,%d2
		addiw	#0x190,%d0
		movew	%d0,(Camera_Y_pos_BG_copy)		/* The effective BG Y is negative when the BG is above the water line, positive when otherwise*/
		subw	%d1,%d2					/* The difference between the effective BG Y and the actual BG Y difference is what's used to calculate how the water line should be drawn*/
		movew	%d2,(Events_bg+0x10)
		movew	(Camera_X_pos_copy),%d0		/* Get the camera BG X*/
		swap	%d0
		clrw	%d0
		tstw	%d2
		beqw	loc_50DDA		/* If equilibrium point, branch*/
		movel	%d0,%d1
		movel	%d0,%d3			/* Set up deformation scroll value*/
		asrl	#7,%d3
		moveq	#0x2F,%d4
		cmpiw	#-0x60,%d2
		bgts	loc_50D52
		lea	(HScroll_table+0x01A),%a1	/* If background is high enough that water line doesn't have to be messed with, just apply the standard formation to it*/

loc_50D3A:
		swap	%d1
		movew	%d1,(%a1)+
		swap	%d1
		subl	%d3,%d1
		swap	%d1
		movew	%d1,(%a1)+
		swap	%d1
		subl	%d3,%d1
		dbf	%d4,loc_50D3A
		braw	loc_50DDA		/* Then finish it up*/
/* --------------------------------------------------------------------------- */

loc_50D52:
		lea	(HScroll_table+0x19A),%a1

loc_50D56:
		swap	%d1				/* If background camera is lower, then apply water line deformation backwards*/
		movew	%d1,-(%a1)
		swap	%d1
		subl	%d3,%d1
		swap	%d1
		movew	%d1,-(%a1)
		swap	%d1
		subl	%d3,%d1
		dbf	%d4,loc_50D56
		cmpiw	#0x60,%d2
		bges	loc_50DDA		/* If background camera is low enough that water line doesn't need to be messed with, then end it.*/
		lea	(HScroll_table+0x0DA),%a1	/* Otherwise, the fun begins*/
