		beqs	CNZMiniboss_BossDefeated
		bset	#6,0x2A(%a0)			/* Set to indicate in hit stun*/
		moveb	#0x20,0x20(%a0)
		moveb	#sfx_BossHit,%d0
		jsr	(Play_Sound_2)		/* Play hit sound*/

loc_6E0D6:
