/* =============== S U B R O U T I N E =======================================*/


SetUp_ObjAttributesSlotted:
		moveq	#0,%d0
		movew	(%a1)+,%d1		/* Maximum number of objects that can be made in this array*/
		movew	%d1,%d2
		movew	(%a1)+,%d3		/* Base VRAM offset of object*/
		movew	(%a1)+,%d4		/* Amount to add to base VRAM offset for each slot*/
		moveq	#0,%d5
		movew	(%a1)+,%d5		/* Index of slot array to use*/
		lea	(Slotted_object_bits),%a2
		addaw	%d5,%a2			/* Get the address of the array to use*/
		moveb	(%a2),%d5
		beqs	loc_84FE4		/* If array is clear, just make the object*/

loc_84FBC:
		lsrb	#1,%d5			/* Check slot (each bit)*/
		bccs	loc_84FE4		/* If clear, make object*/
		addqw	#1,%d0			/* Increment bit number*/
		addw	%d4,%d3			/* Add VRAM offset*/
		dbf	%d1,loc_84FBC		/* Repeat max times*/
		moveq	#0,%d0
		movel	%d0,(%a0)
		movel	%d0,0x10(%a0)
		movel	%d0,0x14(%a0)
		moveb	%d0,0x2C(%a0)
		moveb	%d0,4(%a0)
		movew	%d0,0x2A(%a0)		/* If no open slots, then destroy this object period*/
		addqw	#8,%sp
		rts
/* --------------------------------------------------------------------------- */

loc_84FE4:
		bset	%d0,(%a2)			/* Turn this slot on*/
		moveb	%d0,0x3B(%a0)
		movew	%a2,0x3C(%a0)		/* Keep track of slot address and bit number*/
		movew	%d3,0xA(%a0)		/* Use correct VRAM offset*/
		movel	(%a1)+,0xC(%a0)	/* Mapping address*/
		movew	(%a1)+,8(%a0)		/* Priority*/
		moveb	(%a1)+,7(%a0)		/* Width*/
		moveb	(%a1)+,6(%a0)		/* Height*/
		moveb	(%a1)+,0x22(%a0)	/* Frame number*/
		moveb	(%a1)+,0x28(%a0)	/* Collision number*/
		bset	#2,0x2A(%a0)		/* Turn object slotting on*/
		moveb	#-1,0x3A(%a0)		/* CHECKLATER*/
		bset	#2,4(%a0)		/* Use screen coordinates*/
		addqb	#2,5(%a0)		/* Next routine*/
		rts
/* End of function SetUp_ObjAttributesSlotted*/


/* =============== S U B R O U T I N E =======================================*/


Perform_DPLC:
		moveq	#0,%d0
		moveb	0x22(%a0),%d0		/* Get the frame number*/
		cmpb	0x3A(%a0),%d0		/* If frame number remains the same as before, don't do anything*/
		beqs	locret_8506E
		moveb	%d0,0x3A(%a0)
		moveal	(%a2)+,%a3		/* Source address of art*/
		movew	0xA(%a0),%d4
		andiw	#0x7FF,%d4		/* Isolate tile location offset*/
		lslw	#5,%d4			/* Convert to VRAM address*/
		moveal	(%a2)+,%a2		/* Address of DPLC script*/
		addw	%d0,%d0
		addaw	(%a2,%d0:w),%a2	/* Apply offset to script*/
		movew	(%a2)+,%d5		/* Get number of DMA transactions*/
		moveq	#0,%d3

loc_8504A:
		movew	(%a2)+,%d3		/* Art source offset*/
		movel	%d3,%d1
		andiw	#0xFFF0,%d1		/* Isolate all but lower 4 bits*/
		addw	%d1,%d1
		addl	%a3,%d1			/* Get final source address of art*/
		movew	%d4,%d2			/* Destination VRAM address*/
		andiw	#0xF,%d3
		addqw	#1,%d3
		lslw	#4,%d3			/* %d3 is the total number of words to transfer (maximum 16 tiles per transaction)*/
		addw	%d3,%d4
		addw	%d3,%d4
		jsr	(Add_To_DMA_Queue)	/* Add to queue*/
		dbf	%d5,loc_8504A		/* Keep going*/

locret_8506E:
		rts
/* End of function Perform_DPLC*/

