Run_PalRotationScript:
		tstb	(Palette_rotation_disable)
		bnes	locret_85A00
		lea	(Palette_rotation_data),%a1

loc_85994:
		movew	(%a1),%d0					/* load palette displacement to %d0*/
		beqs	locret_85A00				/* .if 0, return*/
		subqb	#1,2(%a1)				/* decrement delay*/
		bpls	loc_859CA				/* .if still positive, go to next entry*/
		moveal	4(%a1),%a2				/* load palette script address to %a2*/
		moveaw	(%a2),%a3					/* load destination address to %a3*/
		moveal	%a2,%a4					/* copy script address to %a4*/
		addaw	%d0,%a4					/* skip to palette data*/
		movew	(%a4),%d1					/* load the first entry to %d1*/
		bpls	loc_859B0				/* .if positive, it is a normal entry*/
		bsrw	sub_859CE				/* this is a command*/

loc_859B0:
		moveq	#0,%d2
		moveb	2(%a2),%d2				/* load number of colors to %d2*/

loc_859B6:
		movew	(%a4)+,(%a3)+				/* copy the next color into destination*/
		dbf	%d2,loc_859B6				/* loop for every color*/
		movew	(%a4)+,%d0				/* load next delay*/
		moveb	%d0,2(%a1)				/* save the delay*/
		movel	%a4,%d0					/* copy current script position into %d0*/
		movel	%a2,%d1					/* copy palette script origin to %d1*/
		subl	%d1,%d0					/* calculate the current displacement*/
		movew	%d0,(%a1)					/* store it back*/

loc_859CA:
		addqw	#8,%a1					/* go to next script*/
		bras	loc_85994				/* run the code again*/
/* End of function Run_PalRotationScript*/


/* =============== S U B R O U T I N E =======================================*/


sub_859CE:
		moveb	3(%a2),%d2				/* load additional parameter to %d2*/
		beqs	loc_859FC
		negw	%d1
		jmp	.table-8(%pc,%d1:w)
/* --------------------------------------------------------------------------- */

.table:
		braw	loc_859E2
		braw	loc_85A02
/* --------------------------------------------------------------------------- */

loc_859E2:
		addqb	#1,3(%a1)		/* Add one to counter*/
		cmpb	3(%a1),%d2		/* Compare with max counter*/
		bhis	loc_859FC
		movew	2(%a4),%d2
		addaw	%d2,%a2
		movel	%a2,4(%a1)		/* Load new script after counter has finished*/
		moveaw	(%a2),%a3
		clrw	2(%a1)

loc_859FC:
		moveal	%a2,%a4			/* Start from the beginning of the rotation*/
		addql	#4,%a4

locret_85A00:
		rts
/* End of function sub_859CE*/

/* --------------------------------------------------------------------------- */

loc_85A02:
		addqb	#1,3(%a1)
		cmpb	3(%a1),%d2
		bhis	loc_859FC		/* Wait for counter to finish*/
		moveal	(Palette_rotation_custom),%a2
		movel	%a1,-(%sp)
		jsr	(%a2)				/* Run custom routine*/
		moveal	(%sp)+,%a1
		addqw	#4,%sp
		bras	loc_859CA

/* =============== S U B R O U T I N E =======================================*/


