		tstb	(Palette_rotation_disable)
		bnes	locret_85A58
		subqb	#1,0x3A(%a0)
		bpls	locret_85A58
		moveal	(%a1)+,%a3		/* Address of Palette animation data*/
		movew	(%a1)+,%d0		/* Number of colors to replace*/
		moveq	#0,%d1
